insert into public.kkk_recipes(dish_id,recipe,published) values('mixed-berry-shake','{"id":"mixed-berry-shake","name":"Mixed Berry Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"mixed berries","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":160,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Wash and sort the berries. If using frozen berries, follow the packet’s instructions for any required heat treatment and cool before use.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mixed Berry Shake","src":"/photos/mixed-berry-shake-1200.webp","small":"/photos/mixed-berry-shake-600.webp","width":1200,"height":900,"alt":"Mixed Berry Shake served ready to eat","kind":"generated","title":"Mixed Berry Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('muskmelon-shake','{"id":"muskmelon-shake","name":"Muskmelon Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"muskmelon","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":24,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Scrub the whole melon before cutting. Remove the rind and seeds, then cut the flesh into small pieces.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Muskmelon Shake","src":"/photos/muskmelon-shake-1200.webp","small":"/photos/muskmelon-shake-600.webp","width":1200,"height":900,"alt":"Muskmelon Shake served ready to eat","kind":"generated","title":"Muskmelon Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oreo-shake','{"id":"oreo-shake","name":"Oreo Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"eggless chocolate sandwich biscuits","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"eggless vanilla ice cream","qty":200,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Check that the biscuits and ice cream are eggless, then break the biscuits into small pieces.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('papaya-shake','{"id":"papaya-shake","name":"Papaya Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"papaya","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"dates","qty":32,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3}],"steps":["Peel the ripe papaya, scrape out all seeds and chop the flesh. Remove pits from the dates.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Papaya Shake","src":"/photos/papaya-shake-1200.webp","small":"/photos/papaya-shake-600.webp","width":1200,"height":900,"alt":"Papaya Shake served ready to eat","kind":"generated","title":"Papaya Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('peanut-butter-banana-shake','{"id":"peanut-butter-banana-shake","name":"Peanut Butter Banana Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"banana","qty":360,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"peanut butter","qty":80,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Peel and slice the bananas. Stir the peanut butter in its jar so its oil is evenly mixed.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Peanut Butter Banana Shake","src":"/photos/peanut-butter-banana-shake-1200.webp","small":"/photos/peanut-butter-banana-shake-600.webp","width":1200,"height":900,"alt":"Peanut Butter Banana Shake served ready to eat","kind":"generated","title":"Peanut Butter Banana Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('peanut-butter-shake','{"id":"peanut-butter-shake","name":"Peanut Butter Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"peanut butter","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06}],"steps":["Measure the peanut butter and peel the banana. This version is more peanut-forward than the banana shake.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pomegranate-shake','{"id":"pomegranate-shake","name":"Pomegranate Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"pomegranate arils","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"dates","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3}],"steps":["Pick away all white pith from the pomegranate arils. Pulse the arils briefly with a little milk and strain out the hard seed centres.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rose-shake','{"id":"rose-shake","name":"Rose Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"rose syrup","qty":80,"unit":"ml","group":"Other","scale":"linear"},{"name":"basil seeds","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak the basil seeds in plenty of drinking water for 15 minutes until fully swollen, then drain. Reserve them for the finished drink.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Divide the soaked basil seeds between the glasses, pour in the rose milkshake and stir gently before serving."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('strawberry-shake','{"id":"strawberry-shake","name":"Strawberry Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"strawberry","qty":400,"unit":"g","group":"Fruits","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Wash and hull the strawberries, then halve large ones. Taste a berry before deciding how much sugar to add.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tender-coconut-shake','{"id":"tender-coconut-shake","name":"Tender Coconut Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"tender coconut flesh","qty":320,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Use fresh tender coconut flesh, removing any hard shell fragments. Strain the coconut water.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vanilla-shake','{"id":"vanilla-shake","name":"Vanilla Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"eggless vanilla ice cream","qty":320,"unit":"g","group":"Dairy","scale":"linear"},{"name":"vanilla extract","qty":4,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Check that the ice cream is eggless and let it soften for only 2–3 minutes so it blends easily.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kiwi-shake','{"id":"kiwi-shake","name":"Kiwi Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"ripe kiwi","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut milk drink","qty":720,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Peel the ripe kiwi and cut away any hard stem ends. Reserve a few slices if you want a garnish.","Use chilled coconut milk beverage here: fresh kiwi can make dairy milk taste bitter if left standing.","Blend the kiwi with 180 ml of the coconut milk for 20–30 seconds until smooth.","Add the remaining coconut milk and sugar, then blend briefly. Taste and adjust sweetness according to the fruit.","Pour into four chilled glasses and serve immediately; do not store this drink for a long period."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kiwi Shake","src":"/photos/kiwi-shake-1200.webp","small":"/photos/kiwi-shake-600.webp","width":1200,"height":900,"alt":"Kiwi Shake served ready to eat","kind":"generated","title":"Kiwi Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pineapple-shake','{"id":"pineapple-shake","name":"Pineapple Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"pineapple","qty":400,"unit":"g","group":"Fruits","scale":"linear"},{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"vanilla extract","qty":2,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Use drained canned pineapple, or simmer fresh peeled pineapple pieces in a little water for 5 minutes and cool completely. Heating prevents fresh pineapple enzymes from turning a stored milkshake bitter.","Drain excess liquid and chill the pineapple and milk before blending.","Blend pineapple with about 180 ml milk until smooth, then add the remaining milk, sugar and vanilla.","Blend briefly until frothy; taste before adding more sugar because canned fruit may already be sweetened.","Divide into four glasses and serve immediately. Do not blend hot fruit with cold dairy."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('green-apple-smoothie','{"id":"green-apple-smoothie","name":"Green Apple Smoothie","baseServings":4,"batchSize":50,"ingredients":[{"name":"apple","qty":320,"unit":"g","group":"Fruits","scale":"linear"},{"name":"spinach","qty":60,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"curd","qty":480,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"honey","qty":32,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash the apples and spinach thoroughly. Core and chop the apples, discarding the seeds.","Put the fruit and a small amount of the measured liquid into a blender and blend until the fruit is broken down.","Add the remaining ingredients and blend for 45–60 seconds, stopping once to scrape down the sides.","Check for unblended pieces. Thin with a little cold water or milk if necessary; avoid adding so much that the drink loses its smoothie texture.","Divide between four glasses and serve immediately while cold."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Green Apple Smoothie","src":"/photos/green-apple-smoothie-1200.webp","small":"/photos/green-apple-smoothie-600.webp","width":1200,"height":900,"alt":"Green Apple Smoothie served ready to eat","kind":"generated","title":"Green Apple Smoothie","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('strawberry-smoothie','{"id":"strawberry-smoothie","name":"Strawberry Smoothie","baseServings":4,"batchSize":50,"ingredients":[{"name":"strawberry","qty":360,"unit":"g","group":"Fruits","scale":"linear"},{"name":"curd","qty":480,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash and hull the strawberries; peel and slice the banana.","Put the fruit and a small amount of the measured liquid into a blender and blend until the fruit is broken down.","Add the remaining ingredients and blend for 45–60 seconds, stopping once to scrape down the sides.","Check for unblended pieces. Thin with a little cold water or milk if necessary; avoid adding so much that the drink loses its smoothie texture.","Divide between four glasses and serve immediately while cold."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Strawberry Smoothie","src":"/photos/strawberry-smoothie-1200.webp","small":"/photos/strawberry-smoothie-600.webp","width":1200,"height":799,"alt":"Strawberry Smoothie served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Cookies_and_a_strawberry_smoothie_(7342791200).jpg","title":"File:Cookies and a strawberry smoothie (7342791200).jpg","author":"Sonia Belviso from Bratislava, Slovakia","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":852,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ginger-tea','{"id":"ginger-tea","name":"Ginger Tea","baseServings":4,"batchSize":50,"ingredients":[{"name":"black tea","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.5},{"name":"ginger","qty":16,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":400,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Wash and lightly crush the ginger. Put it into a saucepan with the measured water.","Bring to a boil and simmer for 3 minutes so the water takes on the ginger flavour.","Add the black tea and simmer for 1–2 minutes, then add milk and sugar.","Heat until the tea rises toward the rim, lower the heat and simmer for 1 minute while watching to prevent boiling over.","Strain into four cups and serve hot. Shorten the tea simmer if you prefer less bitterness."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kashmiri-kahwa','{"id":"kashmiri-kahwa","name":"Kashmiri Kahwa","baseServings":4,"batchSize":50,"ingredients":[{"name":"green tea","qty":5,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"almond","qty":24,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Crush the cardamom lightly and slice the almonds. Put the water, cardamom and cinnamon in a saucepan.","Bring to a gentle boil and simmer for 3–4 minutes to infuse the spices.","Turn off the heat and let the water cool for about a minute. Add green tea and saffron and steep for 2 minutes.","Strain promptly so the green tea does not become bitter, then stir in sugar to taste.","Divide the sliced almonds between four cups, pour the kahwa over them and serve warm."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-tea','{"id":"lemon-tea","name":"Lemon Tea","baseServings":4,"batchSize":50,"ingredients":[{"name":"black tea","qty":6,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.5},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Heat the drinking water to a boil, then take the pan off the heat.","Add black tea and steep for 2–3 minutes according to the leaf size; avoid a prolonged boil.","Strain the tea into a warm jug and dissolve the sugar while the tea is hot.","Add lemon juice gradually, tasting after each addition so the tea is pleasantly tart.","Divide among four cups and serve warm. Do not add milk to this lemon tea."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Lemon Tea","src":"/photos/lemon-tea-1200.webp","small":"/photos/lemon-tea-600.webp","width":1200,"height":1200,"alt":"Lemon Tea — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Lemon_tea_2.jpg","title":"File:Lemon tea 2.jpg","author":"Gannu03","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3000,"sourceHeight":3000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tulsi-tea','{"id":"tulsi-tea","name":"Tulsi Tea","baseServings":4,"batchSize":50,"ingredients":[{"name":"tulsi leaves","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"honey","qty":24,"unit":"g","group":"Other","scale":"linear"}],"steps":["Rinse the tulsi leaves carefully and discard damaged leaves or tough stems.","Bring the water to a gentle boil, add the tulsi and simmer on low heat for 3 minutes.","Turn off the heat, cover and steep for another 3 minutes.","Strain, allow to cool slightly, then stir in lemon juice and honey to taste.","Divide among four cups and serve warm. This is an herbal drink, not a substitute for medical treatment."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tulsi Tea","src":"/photos/tulsi-tea-1200.webp","small":"/photos/tulsi-tea-600.webp","width":1200,"height":900,"alt":"Tulsi Tea — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Tulsi_Tea.JPG","title":"File:Tulsi Tea.JPG","author":"Miansari66","license":"Public domain","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2816,"sourceHeight":2112,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('saffron-milk','{"id":"saffron-milk","name":"Saffron Milk","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":900,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Warm two tablespoons of the measured milk and crumble the saffron into it; leave for 10 minutes.","Heat the remaining milk in a heavy saucepan over medium-low heat, stirring the base frequently.","When steaming, add sugar, cardamom and the saffron infusion. Simmer gently for 3–4 minutes without boiling over.","Taste and adjust sweetness. Stir so the saffron colour is evenly distributed.","Divide into four small cups and serve warm, or cool promptly and refrigerate for a chilled version."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rose-milk','{"id":"rose-milk","name":"Rose Milk","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":900,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"rose syrup","qty":80,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Chill the milk and four glasses before beginning.","Put the rose syrup into a jug and add about 100 ml of the milk.","Stir until the syrup is completely dissolved with no thick layer remaining at the bottom.","Add the remaining milk and stir again. Taste before adding any extra syrup because brands differ in sweetness.","Pour into the chilled glasses and serve promptly."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":5,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rose Milk","src":"/photos/rose-milk-1200.webp","small":"/photos/rose-milk-600.webp","width":1200,"height":1068,"alt":"Rose Milk — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Rose_Milk_-_Sri_Arasan_Sweets,_Trichy_-_TamilNadu_-_PXL1447.jpg","title":"File:Rose Milk - Sri Arasan Sweets, Trichy - TamilNadu - PXL1447.jpg","author":"Harikrishnan N","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3024,"sourceHeight":2691,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('orange-juice','{"id":"orange-juice","name":"Orange Juice","baseServings":4,"batchSize":50,"ingredients":[{"name":"orange","qty":1600,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Wash and dry the oranges before cutting, even though the peel will not be used.","Halve the oranges across their centres and juice them with a citrus press.","Remove all seeds; strain through a coarse sieve only if you want less pulp.","Stir the collected juice and divide evenly among four glasses. Yield depends on how juicy the fruit is.","Serve immediately, or refrigerate in a clean covered jug and use the same day."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Orange Juice","src":"/photos/orange-juice-1200.webp","small":"/photos/orange-juice-600.webp","width":844,"height":1200,"alt":"Orange Juice — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Orange_juice_1_edit1.jpg","title":"File:Orange juice 1 edit1.jpg","author":"Agency of the United States Department of Agriculture\nEdited Version by: Arad","license":"Public domain","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1566,"sourceHeight":2226,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('watermelon-juice','{"id":"watermelon-juice","name":"Watermelon Juice","baseServings":4,"batchSize":50,"ingredients":[{"name":"watermelon flesh","qty":1200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"lemon juice","qty":24,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Wash the outside of the melon before cutting. Remove the rind and any mature black seeds.","Cut the flesh into blender-sized pieces and chill if time allows.","Blend the watermelon without added water until smooth; the fruit supplies enough liquid.","Stir in lemon juice and strain only if you prefer a very smooth drink.","Divide between four glasses and serve cold. Refrigerate unused juice promptly and use the same day."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jaljeera','{"id":"jaljeera","name":"Jaljeera","baseServings":4,"batchSize":50,"ingredients":[{"name":"mint","qty":30,"unit":"g","group":"Spices","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":60,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"roasted cumin powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":16,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash the mint and coriander thoroughly, discard coarse stems and drain.","Blend the herbs with lemon juice and 100 ml of the measured water to a fine paste.","Strain into a jug if desired, pressing the herb pulp to extract the flavour.","Stir in the remaining chilled water, roasted cumin, black salt and sugar until dissolved.","Taste and balance the sourness and salt, then divide among four glasses. Stir again just before pouring because the spices settle."],"tips":["Serve freshly prepared. Adjust sweetness after tasting."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Jaljeera","src":"/photos/jaljeera-1200.webp","small":"/photos/jaljeera-600.webp","width":1200,"height":900,"alt":"Jaljeera served ready to eat","kind":"generated","title":"Jaljeera","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('amti','{"id":"amti","name":"Amti","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":16,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"goda masala","qty":8,"unit":"g","group":"Other","scale":"linear"}],"steps":["Pick over and rinse the toor dal. Drain after rinsing.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 30–40 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","Heat ghee in a small pan and let cumin sizzle for 20–30 seconds; add any listed whole spices without allowing them to burn.","Stir in tamarind, jaggery and goda masala after the dal is soft; simmer for 6 minutes to balance sweet and sour flavours.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Amti","src":"/photos/amti-1200.webp","small":"/photos/amti-600.webp","width":1200,"height":900,"alt":"Amti served ready to eat","kind":"generated","title":"Amti","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('varan','{"id":"varan","name":"Varan","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Pick over and rinse the toor dal. Drain after rinsing.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 30–40 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","Heat ghee in a small pan and let cumin sizzle for 20–30 seconds; add any listed whole spices without allowing them to burn.","Mash the soft dal lightly, retaining its simple texture; finish with the measured ghee and cumin tempering.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masoor-dal','{"id":"masoor-dal","name":"Masoor Dal","baseServings":4,"batchSize":50,"ingredients":[{"name":"masoor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04}],"steps":["Pick over and rinse the masoor dal. Drain after rinsing.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 20–25 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Mash a small portion of the red lentils against the side of the pan to thicken the dal while keeping it pourable.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Masoor Dal","src":"/photos/masoor-dal-1200.webp","small":"/photos/masoor-dal-600.webp","width":1200,"height":900,"alt":"Masoor Dal served ready to eat","kind":"generated","title":"Masoor Dal","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-banjara','{"id":"dal-banjara","name":"Dal Banjara","baseServings":4,"batchSize":50,"ingredients":[{"name":"split urad dal","qty":160,"unit":"g","group":"Pulses","scale":"linear"},{"name":"chana dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Pick over and rinse the split urad dal and chana dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 45–60 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Keep some lentils intact: this dal should be thick and textured rather than completely smooth.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Banjara","src":"/photos/dal-banjara-1200.webp","small":"/photos/dal-banjara-600.webp","width":1200,"height":900,"alt":"Dal Banjara served ready to eat","kind":"generated","title":"Dal Banjara","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('panchmel-dal','{"id":"panchmel-dal","name":"Panchmel Dal","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":60,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"moong dal","qty":50,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"chana dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"split urad dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"masoor dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Pick over and rinse the toor dal and moong dal and chana dal and split urad dal and masoor dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 45–60 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Check the chana dal in particular; it must crush easily before the combined lentils are considered cooked.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-palak','{"id":"dal-palak","name":"Dal Palak","baseServings":4,"batchSize":50,"ingredients":[{"name":"moong dal","qty":240,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"spinach","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04}],"steps":["Pick over and rinse the moong dal. Drain after rinsing.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 25–35 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Add washed, finely chopped spinach only after the lentils are tender, then simmer uncovered for 6–8 minutes.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Palak","src":"/photos/dal-palak-1200.webp","small":"/photos/dal-palak-600.webp","width":1200,"height":900,"alt":"Dal Palak — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Moong_Dal_Palak.JPG","title":"File:Moong Dal Palak.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4896,"sourceHeight":3672,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sai-bhaji','{"id":"sai-bhaji","name":"Sai Bhaji","baseServings":4,"batchSize":50,"ingredients":[{"name":"chana dal","qty":200,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"spinach","qty":400,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Pick over and rinse the chana dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 50–65 minutes, stirring occasionally and adding boiling water if the base becomes dry. Add washed chopped spinach for the final 15 minutes. The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato and onion. Heat ghee in a separate pan, let cumin sizzle, soften the onion for 6 minutes, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Stir gently to combine the tender vegetables and dal, mashing a few lentils to thicken the mixture.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('doodhi-chana-dal','{"id":"doodhi-chana-dal","name":"Doodhi Chana Dal","baseServings":4,"batchSize":50,"ingredients":[{"name":"chana dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"bottle gourd","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04}],"steps":["Pick over and rinse the chana dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 45–60 minutes, stirring occasionally and adding boiling water if the base becomes dry. After the first 30 minutes, add peeled diced bottle gourd and continue until both are tender. Discard bitter bottle gourd. The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Stir gently to combine the tender vegetables and dal, mashing a few lentils to thicken the mixture.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Doodhi Chana Dal","src":"/photos/doodhi-chana-dal-1200.webp","small":"/photos/doodhi-chana-dal-600.webp","width":1024,"height":768,"alt":"Doodhi Chana Dal served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Lauki_Chana_Dal_Recipe_From_North_Indian_Cuisine_By_Sonia_Goyal.jpg","title":"File:Lauki Chana Dal Recipe From North Indian Cuisine By Sonia Goyal.jpg","author":"Sonia Goyal Jaipur","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":768,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cholar-dal','{"id":"cholar-dal","name":"Cholar Dal","baseServings":4,"batchSize":50,"ingredients":[{"name":"chana dal","qty":260,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"coconut","qty":50,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":16,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"raisins","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Pick over and rinse the chana dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 45–60 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","Heat ghee in a small pan and let cumin sizzle for 20–30 seconds; add any listed whole spices without allowing them to burn.","Keep the cooked chana dal grains whole. Lightly toast coconut and raisins in the tempering, then stir them into the dal with jaggery.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Cholar Dal","src":"/photos/cholar-dal-1200.webp","small":"/photos/cholar-dal-600.webp","width":1200,"height":900,"alt":"Cholar Dal served ready to eat","kind":"generated","title":"Cholar Dal","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gujarati-dal','{"id":"gujarati-dal","name":"Gujarati Dal","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"jaggery","qty":24,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Pick over and rinse the toor dal. Drain after rinsing.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 30–40 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Whisk the cooked dal smooth, add jaggery and simmer for 5 minutes. Add lemon juice after turning off the heat.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-makhani','{"id":"dal-makhani","name":"Dal Makhani","baseServings":4,"batchSize":50,"ingredients":[{"name":"whole black urad dal","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"kidney beans","qty":60,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.16},{"name":"tomato","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cream","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1800,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the whole urad and kidney beans, then soak together in plenty of water for 8–12 hours. Drain and rinse again.","Cover with the measured fresh water in a large saucepan and boil vigorously for 30 minutes, topping up with boiling water to keep the beans submerged. Do not cook raw kidney beans only in a low-temperature slow cooker.","Reduce to a simmer and cook for another 60–90 minutes, or longer if needed, until both beans crush easily and their centres are creamy. Mash a small portion against the side.","Heat butter separately, sizzle cumin and cook minced ginger and garlic for 1 minute. Add pureed tomato and chilli powder and cook for 10 minutes until thick.","Stir this masala and salt into the beans. Simmer very gently for 30–40 minutes, stirring often and adding hot water as needed.","Add cream and garam masala, warm through for 3 minutes and serve. The finished dal should be creamy with soft whole lentils visible."],"tips":["Allow overnight soaking separately. Fully cooked canned kidney beans may replace the dry kidney beans and be added during the final simmer."],"substitutions":[],"status":"complete","prepTime":180,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Makhani","src":"/photos/dal-makhani-1200.webp","small":"/photos/dal-makhani-600.webp","width":900,"height":1200,"alt":"Dal Makhani — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Dal_makhani.jpg","title":"File:Dal makhani.jpg","author":"TarnishedPath","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3019,"sourceHeight":4026,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('achari-paneer','{"id":"achari-paneer","name":"Achari Paneer","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"fennel seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fenugreek seeds","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut the paneer into 2 cm cubes. Lightly crush fennel, mustard and fenugreek seeds.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and the crushed fennel, mustard and fenugreek seeds and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add the paneer to the finished spiced tomato gravy and simmer gently for 5 minutes.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Achari Paneer","src":"/photos/achari-paneer-1200.webp","small":"/photos/achari-paneer-600.webp","width":1200,"height":900,"alt":"Achari Paneer served ready to eat","kind":"generated","title":"Achari Paneer","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('matar-paneer','{"id":"matar-paneer","name":"Matar Paneer","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"peas","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cube the paneer and thaw frozen peas, or rinse fresh peas.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add peas to the gravy and simmer until tender, about 6–8 minutes, before adding paneer for the last 4 minutes.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Matar Paneer","src":"/photos/matar-paneer-1200.webp","small":"/photos/matar-paneer-600.webp","width":1200,"height":900,"alt":"Matar Paneer — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Matar-Paneer.JPG","title":"File:Matar-Paneer.JPG","author":"Mdsmds0","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4896,"sourceHeight":3672,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-butter-masala','{"id":"paneer-butter-masala","name":"Paneer Butter Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"cashew","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"butter","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cream","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"dried fenugreek leaves","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak cashews in hot water for 20 minutes and blend smooth with a little measured water. Cube the paneer.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Blend the cooked tomato base and cashew paste until smooth, return to the pan, add butter and paneer, and simmer for 5 minutes. Finish on low heat with cream and crushed dried fenugreek.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Paneer Butter Masala","src":"/photos/paneer-butter-masala-1200.webp","small":"/photos/paneer-butter-masala-600.webp","width":900,"height":1200,"alt":"Paneer Butter Masala — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Paneer_butter_masala_2.jpg","title":"File:Paneer butter masala 2.jpg","author":"Gannu03","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":12240,"sourceHeight":16320,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-lababdar','{"id":"paneer-lababdar","name":"Paneer Lababdar","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"cream","qty":60,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"dried fenugreek leaves","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Grate 100 g of the paneer and cut the rest into cubes. Soak cashews and blend to a smooth paste.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add cashew paste and grated paneer to the gravy and simmer for 5 minutes; add the cubes for another 4 minutes, then stir in cream and dried fenugreek.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kadai-paneer','{"id":"kadai-paneer","name":"Kadai Paneer","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander seeds","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cube the paneer and capsicum. Toast coriander seeds in a dry pan for 1 minute and crush coarsely.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Stir-fry capsicum separately over high heat for 3 minutes. Add it with paneer and crushed coriander to the reduced tomato gravy, then toss for 4 minutes; keep this curry fairly thick.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kadai Paneer","src":"/photos/kadai-paneer-1200.webp","small":"/photos/kadai-paneer-600.webp","width":1200,"height":799,"alt":"Kadai Paneer served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Kadai_Paneer_(15913018051).jpg","title":"File:Kadai Paneer (15913018051).jpg","author":"Yummy O Yummy","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":852,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('corn-capsicum-masala','{"id":"corn-capsicum-masala","name":"Corn Capsicum Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet corn","qty":400,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Slice the capsicum into bite-size squares and rinse or thaw the corn.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add corn and capsicum to the gravy, cover loosely and simmer for 8–10 minutes until tender but not mushy.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Corn Capsicum Masala","src":"/photos/corn-capsicum-masala-1200.webp","small":"/photos/corn-capsicum-masala-600.webp","width":1200,"height":900,"alt":"Corn Capsicum Masala served ready to eat","kind":"generated","title":"Corn Capsicum Masala","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mix-vegetable-curry','{"id":"mix-vegetable-curry","name":"Mix Vegetable Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Peel and dice carrots, trim beans into short lengths and cube capsicum. Keep the vegetables similar in size.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add carrots and beans first and simmer covered for 10 minutes; add peas and capsicum and cook another 7–8 minutes until all are tender.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mix Vegetable Curry","src":"/photos/mix-vegetable-curry-1200.webp","small":"/photos/mix-vegetable-curry-600.webp","width":1200,"height":900,"alt":"Mix Vegetable Curry served ready to eat","kind":"generated","title":"Mix Vegetable Curry","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mushroom-masala','{"id":"mushroom-masala","name":"Mushroom Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"mushroom","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wipe mushrooms clean, trim the stems and halve or quarter them. Slice capsicum.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Brown the mushrooms separately in a wide pan for 6–8 minutes so excess moisture evaporates. Add them and capsicum to the masala and simmer for 6 minutes.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mushroom Masala","src":"/photos/mushroom-masala-1200.webp","small":"/photos/mushroom-masala-600.webp","width":1200,"height":675,"alt":"Mushroom Masala — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Mushroom_Masala_by_Dr._Raju_Kasambe_IMG_20190701_(9).jpg","title":"File:Mushroom Masala by Dr. Raju Kasambe IMG 20190701 (9).jpg","author":"Dr. Raju Kasambe","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3000,"sourceHeight":1688,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kaju-curry','{"id":"kaju-curry","name":"Kaju Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"cashew","qty":240,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"cream","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak half the cashews in hot water for 20 minutes and blend smooth; lightly toast the remaining whole cashews.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Stir cashew paste into the tomato gravy and simmer for 6 minutes, adding water if it catches. Add whole cashews and cream and heat gently for 3 minutes.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kaju Curry","src":"/photos/kaju-curry-1200.webp","small":"/photos/kaju-curry-600.webp","width":1200,"height":900,"alt":"Kaju Curry — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Kaju_curry_and_Paratha.jpg","title":"File:Kaju curry and Paratha.jpg","author":"Katugoswami21","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4608,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chole-masala','{"id":"chole-masala","name":"Chole Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked chickpeas","qty":700,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"chole masala","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Drain and rinse canned chickpeas, or use chickpeas already boiled until completely tender.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add the chickpeas and chole masala to the gravy. Simmer for 15 minutes, mashing a few chickpeas to thicken the sauce.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chole Masala","src":"/photos/chole-masala-1200.webp","small":"/photos/chole-masala-600.webp","width":1200,"height":800,"alt":"Chole Masala served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Chana_masala_(5727362126).jpg","title":"File:Chana masala (5727362126).jpg","author":"Johan Bichel Lindegaard from Copenhagen, Denmark","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kala-chana-curry','{"id":"kala-chana-curry","name":"Kala Chana Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked black chickpeas","qty":700,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use black chickpeas soaked overnight and fully boiled in advance, or ready-cooked chickpeas. They must crush easily.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add the cooked chickpeas to the gravy and simmer for 15–20 minutes; mash a spoonful to give the sauce body.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('green-moong-curry','{"id":"green-moong-curry","name":"Green Moong Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked whole green moong","qty":700,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse the cooked mung beans gently and drain; they should be soft but still mostly whole.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Fold the cooked moong into the gravy and simmer for 10 minutes, stirring gently so it does not become a paste.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Green Moong Curry","src":"/photos/green-moong-curry-1200.webp","small":"/photos/green-moong-curry-600.webp","width":1200,"height":900,"alt":"Green Moong Curry served ready to eat","kind":"generated","title":"Green Moong Curry","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('soya-chunk-masala','{"id":"soya-chunk-masala","name":"Soya Chunk Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"dry soya chunks","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil the soya chunks in plenty of water for 8–10 minutes or as directed on the packet. Drain, rinse and squeeze out water; chop the capsicum.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add squeezed soya chunks and capsicum to the gravy and simmer covered for 10–12 minutes so the chunks absorb the sauce.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('soya-chaap-masala','{"id":"soya-chaap-masala","name":"Soya Chaap Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"ready-cooked vegetarian soya chaap","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Check that the chaap is vegetarian and eggless. Remove sticks and cut into pieces; lightly pan-brown the pieces.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Turn the heat low and add whisked curd gradually to the cooked masala. Add chaap and simmer gently for 12 minutes; do not boil hard.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Soya Chaap Masala","src":"/photos/soya-chaap-masala-1200.webp","small":"/photos/soya-chaap-masala-600.webp","width":1200,"height":900,"alt":"Soya Chaap Masala served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Soya_Masala_Chops_with_Gravy.JPG","title":"File:Soya Masala Chops with Gravy.JPG","author":"Mdsmds0","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pumpkin-curry','{"id":"pumpkin-curry","name":"Pumpkin Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"pumpkin","qty":750,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":12,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Peel the pumpkin, remove seeds and cut into 2 cm cubes.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add pumpkin and jaggery to the gravy, cover and simmer for 15–18 minutes until a knife enters easily. Finish with lemon juice off the heat.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ringan-bateta','{"id":"ringan-bateta","name":"Ringan Bateta","baseServings":4,"batchSize":50,"ingredients":[{"name":"brinjal","qty":400,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut brinjal into wedges and peeled potatoes into 2 cm cubes; keep the potatoes slightly smaller so they cook in the same time.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add potatoes to the gravy and cook covered for 10 minutes. Add brinjal and cook another 12–15 minutes until both are tender.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('alur-dom','{"id":"alur-dom","name":"Alur Dom","baseServings":4,"batchSize":50,"ingredients":[{"name":"small potatoes","qty":750,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil the potatoes for 12–15 minutes until nearly tender, cool slightly, peel and prick them with a fork.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add the potatoes to the masala, cover and simmer for 15 minutes, turning gently until the sauce coats them.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Alur Dom","src":"/photos/alur-dom-1200.webp","small":"/photos/alur-dom-600.webp","width":1200,"height":675,"alt":"Alur Dom — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Alur_dom_%26_luchi.jpg","title":"File:Alur dom & luchi.jpg","author":"Rocky Masum","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3923,"sourceHeight":2207,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('veg-jalfrezi','{"id":"veg-jalfrezi","name":"Veg Jalfrezi","baseServings":4,"batchSize":50,"ingredients":[{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut carrot and capsicum into thin strips; slice beans on the diagonal.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Stir-fry the vegetables separately over high heat for 5–6 minutes, then toss into a well-reduced masala for 3 minutes. Retain a little crunch.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aloo-gobi','{"id":"aloo-gobi","name":"Aloo Gobi","baseServings":4,"batchSize":50,"ingredients":[{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cauliflower","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Peel and cube potatoes. Cut cauliflower into medium florets, rinse and drain very well.","Measure the spices and keep a wide, heavy pan ready so the vegetables can cook without piling too deeply.","Heat oil over medium heat and let cumin sizzle for 20–30 seconds. Add any listed mustard seeds and allow them to pop.","Reduce the heat and add turmeric, coriander powder and chilli powder briefly; immediately begin the vegetable-cooking sequence in the next step so the spices do not scorch.","Cook potatoes covered with 60 ml water for 8 minutes, then add cauliflower and cook 12–15 minutes more, turning gently until both are tender.","Check tenderness with a knife and add salt to taste. Turn off the heat, add lemon juice and chopped coriander, and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Aloo Gobi","src":"/photos/aloo-gobi-1200.webp","small":"/photos/aloo-gobi-600.webp","width":1024,"height":683,"alt":"Aloo Gobi served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Aloo_gobi.jpg","title":"File:Aloo gobi.jpg","author":"Paul Goyette","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":683,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhinda-nu-shaak','{"id":"bhinda-nu-shaak","name":"Bhinda nu Shaak","baseServings":4,"batchSize":50,"ingredients":[{"name":"okra","qty":750,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash the okra and dry it thoroughly with a clean towel before trimming and slicing into 1 cm pieces.","Measure the spices and keep a wide, heavy pan ready so the vegetables can cook without piling too deeply.","Heat oil over medium heat and let cumin sizzle for 20–30 seconds. Add any listed mustard seeds and allow them to pop.","Reduce the heat and add turmeric, coriander powder and chilli powder briefly; immediately begin the vegetable-cooking sequence in the next step so the spices do not scorch.","Cook uncovered for 15–18 minutes, turning occasionally. Add salt only near the end and avoid adding water so the okra loses its sticky texture.","Check tenderness with a knife and add salt to taste. Turn off the heat, add lemon juice and chopped coriander, and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bhinda nu Shaak","src":"/photos/bhinda-nu-shaak-1200.webp","small":"/photos/bhinda-nu-shaak-600.webp","width":1200,"height":900,"alt":"Bhinda nu Shaak served ready to eat","kind":"generated","title":"Bhinda nu Shaak","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhindi-masala','{"id":"bhindi-masala","name":"Bhindi Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"okra","qty":700,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash okra and dry completely before slicing into short lengths. Slice onion and chop tomato.","Heat 20 ml of the oil in a wide pan and fry okra uncovered for 12–15 minutes until nearly tender. Transfer to a plate.","Heat the remaining 10 ml oil, sizzle cumin and soften onion for 7 minutes. Add turmeric, coriander powder and chilli briefly, then tomato.","Cook tomato for 6–8 minutes until pulpy. Return okra and cook uncovered for 5 minutes until fully tender.","Add salt and turn off the heat. Fold in lemon juice and coriander.","Serve hot; avoid covering the finished okra or adding water, which makes the texture sticky."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bhindi Masala","src":"/photos/bhindi-masala-1200.webp","small":"/photos/bhindi-masala-600.webp","width":1200,"height":1200,"alt":"Bhindi Masala served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Bhindi_Masala.jpg","title":"File:Bhindi Masala.jpg","author":"Monali.mishra","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1280,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tindora-nu-shaak','{"id":"tindora-nu-shaak","name":"Tindora nu Shaak","baseServings":4,"batchSize":50,"ingredients":[{"name":"ivy gourd","qty":750,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash the ivy gourds, trim both ends and cut lengthwise into thin wedges.","Measure the spices and keep a wide, heavy pan ready so the vegetables can cook without piling too deeply.","Heat oil over medium heat and let cumin sizzle for 20–30 seconds. Add any listed mustard seeds and allow them to pop.","Reduce the heat and add turmeric, coriander powder and chilli powder briefly; immediately begin the vegetable-cooking sequence in the next step so the spices do not scorch.","Cook covered over medium-low heat for 15 minutes, stirring occasionally, then uncover and cook another 6–8 minutes until tender with lightly browned edges.","Check tenderness with a knife and add salt to taste. Turn off the heat, add lemon juice and chopped coriander, and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tindora nu Shaak","src":"/photos/tindora-nu-shaak-1200.webp","small":"/photos/tindora-nu-shaak-600.webp","width":1200,"height":900,"alt":"Tindora nu Shaak served ready to eat","kind":"generated","title":"Tindora nu Shaak","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gawar-phali','{"id":"gawar-phali","name":"Gawar Phali","baseServings":4,"batchSize":50,"ingredients":[{"name":"cluster beans","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"gram flour","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Trim and string the cluster beans, cut into short pieces and blanch in boiling water for 8–10 minutes; drain.","Measure the spices and keep a wide, heavy pan ready so the vegetables can cook without piling too deeply.","Heat oil over medium heat and let cumin sizzle for 20–30 seconds. Add any listed mustard seeds and allow them to pop.","Reduce the heat and add turmeric, coriander powder and chilli powder briefly; immediately begin the vegetable-cooking sequence in the next step so the spices do not scorch.","Toss the beans in the spice oil for 5 minutes. Sprinkle gram flour gradually, stirring well, and cook uncovered for 6–8 minutes until the flour smells nutty rather than raw.","Check tenderness with a knife and add salt to taste. Turn off the heat, add lemon juice and chopped coriander, and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chorchori','{"id":"chorchori","name":"Chorchori","baseServings":4,"batchSize":50,"ingredients":[{"name":"pumpkin","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"potato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"brinjal","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut the pumpkin, potato and brinjal into similar bite-size pieces.","Measure the spices and keep a wide, heavy pan ready so the vegetables can cook without piling too deeply.","Heat oil over medium heat and let cumin sizzle for 20–30 seconds. Add any listed mustard seeds and allow them to pop.","Reduce the heat and add turmeric, coriander powder and chilli powder briefly; immediately begin the vegetable-cooking sequence in the next step so the spices do not scorch.","Add vegetables and 120 ml water, cover and simmer for 18–22 minutes until tender. Uncover and cook off excess moisture without mashing all the vegetables.","Check tenderness with a knife and add salt to taste. Turn off the heat, add lemon juice and chopped coriander, and serve hot."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chorchori","src":"/photos/chorchori-1200.webp","small":"/photos/chorchori-600.webp","width":1200,"height":900,"alt":"Chorchori — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sojne_dantar_chorchori_DSCN2852.jpg","title":"File:Sojne dantar chorchori DSCN2852.jpg","author":"Atudu","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4608,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('baingan-bharta','{"id":"baingan-bharta","name":"Baingan Bharta","baseServings":4,"batchSize":50,"ingredients":[{"name":"brinjal","qty":900,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash and dry the whole brinjals and prick them several times. Roast at 220°C for 35–45 minutes, turning once, until the skin collapses and the flesh is completely soft.","Cool until safe to handle, peel off the dark skin and mash the flesh. Discard any hard or undercooked sections.","Heat oil in a wide pan, sizzle cumin and cook chopped onion for 7–8 minutes until golden. Add minced ginger and garlic for 1 minute.","Add chopped tomato, turmeric, chilli powder and salt. Cook for 8–10 minutes until the tomato becomes a thick masala.","Fold in the mashed roasted brinjal and cook over medium-low heat for 8–10 minutes, stirring to evaporate excess moisture.","Finish with chopped coriander, taste and serve hot with roti. For a smokier result, use a suitable grill following its instructions."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Baingan Bharta","src":"/photos/baingan-bharta-1200.webp","small":"/photos/baingan-bharta-600.webp","width":1200,"height":821,"alt":"Baingan Bharta served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Baingan_Ka_Bharta.JPG","title":"File:Baingan Ka Bharta.JPG","author":"Zeel Patel","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":876,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bharli-vangi','{"id":"bharli-vangi","name":"Bharli Vangi","baseServings":4,"batchSize":50,"ingredients":[{"name":"small brinjal","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"roasted peanuts","qty":80,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"grated coconut","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"goda masala","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash the small brinjals and cut a cross into each from the base, keeping the stem end intact so they can hold stuffing.","Grind roasted peanuts and coconut coarsely. Mix with finely chopped onion, tamarind, jaggery, goda masala, turmeric and salt.","Gently fill each brinjal with the mixture, reserving the excess stuffing.","Heat oil in a wide pan and arrange the brinjals in one layer. Cook for 4 minutes, turning carefully.","Add reserved stuffing and measured water around them. Cover and simmer on low heat for 25–30 minutes, turning occasionally and adding a splash of hot water if dry.","Check that a knife passes easily through the flesh to the stem end. Rest covered for 5 minutes and serve with the thick peanut gravy."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bharli Vangi","src":"/photos/bharli-vangi-1200.webp","small":"/photos/bharli-vangi-600.webp","width":1200,"height":900,"alt":"Bharli Vangi served ready to eat","kind":"generated","title":"Bharli Vangi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lasaniya-bataka','{"id":"lasaniya-bataka","name":"Lasaniya Bataka","baseServings":4,"batchSize":50,"ingredients":[{"name":"small potatoes","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":45,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil the potatoes until just tender, about 15–20 minutes depending on size. Cool slightly, peel and prick with a fork.","Crush the garlic to a coarse paste and puree the tomato. Measure the spices.","Heat oil, sizzle cumin and cook garlic over medium-low heat for 1–2 minutes without burning it.","Add tomato, chilli, turmeric and coriander powder. Cook for 8–10 minutes until thick and fragrant.","Add potatoes, salt and water. Cover and simmer for 12–15 minutes, turning occasionally until the garlic masala clings to the potatoes.","Finish with chopped coriander and serve. Start with less chilli if serving people who prefer a milder curry."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Lasaniya Bataka","src":"/photos/lasaniya-bataka-1200.webp","small":"/photos/lasaniya-bataka-600.webp","width":1200,"height":900,"alt":"Lasaniya Bataka served ready to eat","kind":"generated","title":"Lasaniya Bataka","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-malai-matar','{"id":"methi-malai-matar","name":"Methi Malai Matar","baseServings":4,"batchSize":50,"ingredients":[{"name":"fenugreek leaves","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cashew","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"cream","qty":120,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"milk","qty":150,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick and wash fenugreek leaves, then chop finely. Soak cashews in hot water for 20 minutes and blend smooth with the measured water.","Heat oil, sizzle cumin and soften finely chopped onion over medium-low heat for 7 minutes without deeply browning it. Add grated ginger for 1 minute.","Add fenugreek and cook uncovered for 5–6 minutes until wilted and excess moisture has evaporated.","Stir in peas, cashew paste and milk. Simmer gently for 8–10 minutes until the peas are tender, stirring the base.","Lower the heat and add cream, salt and garam masala. Warm for 2–3 minutes without a vigorous boil.","Adjust thickness with a little hot water and serve while the sauce is creamy and pourable."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chana-saag','{"id":"chana-saag","name":"Chana Saag","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked chickpeas","qty":700,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"spinach","qty":450,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash spinach in several changes of water and chop finely. Drain and rinse fully cooked chickpeas.","Heat oil, sizzle cumin and soften chopped onion for 7 minutes. Add minced ginger and garlic and cook for 1 minute.","Add chopped tomato, coriander powder and turmeric; cook for 8 minutes until pulpy.","Add spinach in handfuls, stirring until wilted. Cook uncovered for 5 minutes.","Add chickpeas, salt and water and simmer for 12–15 minutes. Mash a few chickpeas to thicken the greens.","Check seasoning and serve hot; the sauce should cling to the chickpeas rather than remain watery."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chana Saag","src":"/photos/chana-saag-1200.webp","small":"/photos/chana-saag-600.webp","width":1200,"height":900,"alt":"Chana Saag served ready to eat","kind":"generated","title":"Chana Saag","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('matki-usal','{"id":"matki-usal","name":"Matki Usal","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked moth beans","qty":700,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"grated coconut","qty":50,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"goda masala","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use soaked moth beans or moth-bean sprouts already simmered until fully tender. Drain, reserving some cooking liquid if desired.","Toast the coconut in a dry pan until lightly golden and set aside.","Heat oil, sizzle cumin and cook chopped onion for 7 minutes. Add tomato and cook for another 7–8 minutes until pulpy.","Add turmeric, chilli and goda masala, then the cooked moth beans, toasted coconut and measured water.","Simmer gently for 12–15 minutes, stirring occasionally, until the beans have absorbed the masala.","Add salt, finish with coriander and serve hot. Cook sprouts thoroughly rather than adding them raw at the end."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Matki Usal","src":"/photos/matki-usal-1200.webp","small":"/photos/matki-usal-600.webp","width":1200,"height":900,"alt":"Matki Usal served ready to eat","kind":"generated","title":"Matki Usal","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ker-sangri','{"id":"ker-sangri","name":"Ker Sangri","baseServings":4,"batchSize":50,"ingredients":[{"name":"dried sangri","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"dried ker","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dried mango powder","qty":4,"unit":"g","group":"Fruits","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the dried ker and sangri separately and soak in plenty of water overnight. Change the ker soaking water to reduce bitterness; trim any tough sangri ends.","Drain and boil in fresh water for 20–30 minutes, or until tender. Drain thoroughly and discard the boiling water.","Whisk curd with turmeric, coriander powder and chilli powder. Heat oil in a heavy pan and let cumin sizzle.","Lower the heat and add the curd mixture gradually, stirring continuously until it comes to a gentle simmer.","Add the cooked ker and sangri, salt and measured water. Cover and cook on low heat for 15 minutes, stirring occasionally.","Uncover, add dried mango powder and reduce until the masala coats the vegetables. Taste before adding more salt or souring."],"tips":["Overnight soaking is additional. The dried vegetables must be tender before the final masala cooking."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Ker Sangri","src":"/photos/ker-sangri-1200.webp","small":"/photos/ker-sangri-600.webp","width":1200,"height":900,"alt":"Ker Sangri served ready to eat","kind":"generated","title":"Ker Sangri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhuga-chawal','{"id":"bhuga-chawal","name":"Bhuga Chawal","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"onion","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice until the water runs less cloudy. Soak for 20 minutes, drain and measure fresh cooking water.","Heat oil in a heavy saucepan, sizzle cumin and prepare the flavour base.","Brown sliced onion slowly in the oil for 15–20 minutes until deep golden but not black; this supplies the rice’s characteristic colour.","Add drained rice, cumin if not yet used, salt and measured water. Bring to a boil, cover tightly and simmer over low heat for 12–15 minutes until the liquid is absorbed.","Switch off the heat and rest covered for 10 minutes without stirring. If the grains are still firm, sprinkle in a little boiling water and steam for another 3 minutes.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bhuga Chawal","src":"/photos/bhuga-chawal-1200.webp","small":"/photos/bhuga-chawal-600.webp","width":1200,"height":900,"alt":"Bhuga Chawal served ready to eat","kind":"generated","title":"Bhuga Chawal","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-rice','{"id":"coconut-rice","name":"Coconut Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"grated coconut","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice until the water runs less cloudy. Soak for 20 minutes, drain and measure fresh cooking water.","Cook the drained rice with 650 ml of the water and salt: bring to a boil, cover on low heat for 12–15 minutes, then rest off the heat for 10 minutes. Spread out gently so steam can escape. Heat the oil separately and sizzle cumin before making the tempering.","Sizzle mustard seeds and curry leaves, toast cashews until golden, then stir in coconut for 1 minute without browning it.","Fold the cooked rice gently into the prepared tempering or paste, keeping the grains separate. Warm over low heat for 2–3 minutes.","Taste and adjust the salt. Rest for 5 minutes so the seasoning distributes through the grains.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Coconut Rice","src":"/photos/coconut-rice-1200.webp","small":"/photos/coconut-rice-600.webp","width":1200,"height":900,"alt":"Coconut Rice served ready to eat","kind":"generated","title":"Coconut Rice","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('spinach-rice','{"id":"spinach-rice","name":"Spinach Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"spinach","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice until the water runs less cloudy. Soak for 20 minutes, drain and measure fresh cooking water.","Heat oil in a heavy saucepan, sizzle cumin and prepare the flavour base.","Wash and finely chop spinach. Wilt it in the spice oil for 3 minutes, then add peas before adding rice.","Add drained rice, cumin if not yet used, salt and measured water. Bring to a boil, cover tightly and simmer over low heat for 12–15 minutes until the liquid is absorbed.","Switch off the heat and rest covered for 10 minutes without stirring. If the grains are still firm, sprinkle in a little boiling water and steam for another 3 minutes.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-tehri','{"id":"vegetable-tehri","name":"Vegetable Tehri","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice until the water runs less cloudy. Soak for 20 minutes, drain and measure fresh cooking water.","Heat oil in a heavy saucepan, sizzle cumin and prepare the flavour base.","Dice potato and carrot. Toss vegetables and turmeric in the spice oil for 4 minutes before adding rice.","Add drained rice, cumin if not yet used, salt and measured water. Bring to a boil, cover tightly and simmer over low heat for 12–15 minutes until the liquid is absorbed.","Switch off the heat and rest covered for 10 minutes without stirring. If the grains are still firm, sprinkle in a little boiling water and steam for another 3 minutes.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Tehri","src":"/photos/vegetable-tehri-1200.webp","small":"/photos/vegetable-tehri-600.webp","width":1200,"height":900,"alt":"Vegetable Tehri served ready to eat","kind":"generated","title":"Vegetable Tehri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('millet-vegetable-pulao','{"id":"millet-vegetable-pulao","name":"Millet Vegetable Pulao","baseServings":4,"batchSize":50,"ingredients":[{"name":"millet","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse and soak the millet as described below. Prepare all vegetables before heating the pan.","Heat oil in a heavy saucepan, sizzle cumin and prepare the flavour base.","Rinse the millet and soak for 20 minutes, then drain. Dice vegetables and sauté in the spice oil for 3 minutes.","Add drained millet, cumin if not yet used, salt and measured water. Bring to a boil, cover tightly and simmer over low heat for 18–20 minutes until the liquid is absorbed.","Switch off the heat and rest covered for 10 minutes without stirring. If the grains are still firm, sprinkle in a little boiling water and steam for another 3 minutes.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Millet Vegetable Pulao","src":"/photos/millet-vegetable-pulao-1200.webp","small":"/photos/millet-vegetable-pulao-600.webp","width":1200,"height":900,"alt":"Millet Vegetable Pulao served ready to eat","kind":"generated","title":"Millet Vegetable Pulao","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tamarind-rice','{"id":"tamarind-rice","name":"Tamarind Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"tamarind paste","qty":40,"unit":"g","group":"Other","scale":"linear"},{"name":"peanuts","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.18},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"jaggery","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice until the water runs less cloudy. Soak for 20 minutes, drain and measure fresh cooking water.","Cook the drained rice with 570 ml of the water and salt: bring to a boil, cover on low heat for 12–15 minutes, then rest off the heat for 10 minutes. Spread out gently so steam can escape. Heat the oil separately and sizzle cumin before making the tempering.","Sizzle mustard and curry leaves, toast peanuts, then add tamarind, jaggery and turmeric with 80 ml water. Simmer for 5 minutes to make a thick tangy paste.","Fold the cooked rice gently into the prepared tempering or paste, keeping the grains separate. Warm over low heat for 2–3 minutes.","Taste and adjust the salt. Rest for 5 minutes so the seasoning distributes through the grains.","Fluff gently with a fork and serve hot. Cool any rice intended for later use promptly and refrigerate rather than leaving it warm on the counter."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tamarind Rice","src":"/photos/tamarind-rice-1200.webp","small":"/photos/tamarind-rice-600.webp","width":1200,"height":900,"alt":"Tamarind Rice served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Tamarind_rice,.jpg","title":"File:Tamarind rice,.jpg","author":"Devika","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-khichdi','{"id":"masala-khichdi","name":"Masala Khichdi","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"moong dal","qty":140,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over and rinse the grains and any lentils, then drain. Measure the fresh cooking water.","Wash and dice the listed vegetables into small even pieces. Peel potato or carrot where used and thaw frozen peas if necessary.","Heat ghee in a deep saucepan, sizzle cumin and add turmeric on low heat. Add the prepared vegetables and cook for 3 minutes. Add the prepared grains and any lentils and stir for 1 minute.","Add measured water and salt, bring to a boil, then cover loosely and simmer on low heat for 25–35 minutes, stirring occasionally.","Add any reserved spinach near the end. Check that the grains and lentils are completely soft; if firm or dry, add boiling water and continue cooking.","Stir to the desired soft, spoonable consistency, rest covered for 5 minutes and serve hot. The mixture thickens as it stands."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Masala Khichdi","src":"/photos/masala-khichdi-1200.webp","small":"/photos/masala-khichdi-600.webp","width":1200,"height":900,"alt":"Masala Khichdi served ready to eat","kind":"generated","title":"Masala Khichdi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('palak-khichdi','{"id":"palak-khichdi","name":"Palak Khichdi","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"moong dal","qty":140,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"spinach","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over and rinse the grains and any lentils, then drain. Measure the fresh cooking water.","Wash spinach thoroughly, chop it and reserve for the final 8 minutes of cooking.","Heat ghee in a deep saucepan, sizzle cumin and add turmeric on low heat. Keep the spinach aside for later. Add the prepared grains and any lentils and stir for 1 minute.","Add measured water and salt, bring to a boil, then cover loosely and simmer on low heat for 25–35 minutes, stirring occasionally.","Add any reserved spinach near the end. Check that the grains and lentils are completely soft; if firm or dry, add boiling water and continue cooking.","Stir to the desired soft, spoonable consistency, rest covered for 5 minutes and serve hot. The mixture thickens as it stands."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Palak Khichdi","src":"/photos/palak-khichdi-1200.webp","small":"/photos/palak-khichdi-600.webp","width":900,"height":1200,"alt":"Palak Khichdi — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Palak-khichdi_With_Dahi_and_Tamarind_Chuttney.jpg","title":"File:Palak-khichdi With Dahi and Tamarind Chuttney.jpg","author":"Saumendra","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3120,"sourceHeight":4160,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
