insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-dalia','{"id":"vegetable-dalia","name":"Vegetable Dalia","baseServings":4,"batchSize":50,"ingredients":[{"name":"broken wheat","qty":260,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over the clean packaged broken wheat and dry-roast it for 4 minutes, stirring; set aside. Measure the water.","Wash and dice the listed vegetables into small even pieces. Peel potato or carrot where used and thaw frozen peas if necessary.","Heat ghee in a deep saucepan, sizzle cumin and add turmeric on low heat. Add the prepared vegetables and cook for 3 minutes. Add the prepared grains and any lentils and stir for 1 minute.","Add measured water and salt, bring to a boil, then cover loosely and simmer on low heat for 25–35 minutes, stirring occasionally.","Add any reserved spinach near the end. Check that the grains and lentils are completely soft; if firm or dry, add boiling water and continue cooking.","Stir to the desired soft, spoonable consistency, rest covered for 5 minutes and serve hot. The mixture thickens as it stands."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sama-rice-khichdi','{"id":"sama-rice-khichdi","name":"Sama Rice Khichdi","baseServings":4,"batchSize":50,"ingredients":[{"name":"barnyard millet","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over and rinse the grains and any lentils, then drain. Measure the fresh cooking water.","Wash and dice the listed vegetables into small even pieces. Peel potato or carrot where used and thaw frozen peas if necessary.","Heat ghee in a deep saucepan, sizzle cumin and add turmeric on low heat. Add the prepared vegetables and cook for 3 minutes. Add the prepared grains and any lentils and stir for 1 minute.","Add measured water and salt, bring to a boil, then cover loosely and simmer on low heat for 25–35 minutes, stirring occasionally.","Add any reserved spinach near the end. Check that the grains and lentils are completely soft; if firm or dry, add boiling water and continue cooking.","Stir to the desired soft, spoonable consistency, rest covered for 5 minutes and serve hot. The mixture thickens as it stands."],"tips":["Taste at the end and adjust salt, heat and consistency before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) 