insert into public.kkk_recipes(dish_id,recipe,published) values('adai','{"id":"adai","name":"Adai","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"toor dal","qty":70,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"chana dal","qty":70,"unit":"g","group":"Pulses","scale":"linear"},{"name":"urad dal","qty":30,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dried red chilli","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Soak the rice and lentils together for 4 hours, then drain. Grind with cumin, chilli and about 250 ml fresh water to a slightly coarse, thick pouring batter.","Stir in finely chopped onion and curry leaves. No fermentation is needed.","Mix in salt. Reserve unused measured water for adjusting the batter; soaking water is discarded and is additional.","Heat a flat non-stick or well-seasoned tawa over medium heat. Brush lightly with some of the measured oil; the batter should sizzle gently on contact.","Spread into 15 cm pancakes slightly thicker than dosa; cook for 3–4 minutes, flip and cook for 2 minutes until the lentils are cooked through. Drizzle a little oil around each pancake as it cooks.","Repeat with the remaining batter, stirring it between batches. Serve hot; any chutney or accompaniment is additional to these quantities."],"tips":["Soaking or resting is additional to the cooking time. Keep the tawa at steady medium heat so the middle cooks before the outside burns."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Adai","src":"/photos/adai-1200.webp","small":"/photos/adai-600.webp","width":1200,"height":900,"alt":"Adai served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Adai_Dosai_with_Chutney_01.jpg","title":"File:Adai Dosai with Chutney 01.jpg","author":"Sudhan Ram","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('moong-dal-chilla','{"id":"moong-dal-chilla","name":"Moong Dal Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"moong dal","qty":300,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Soak rinsed moong dal for 4 hours, drain and blend with ginger, cumin and 200 ml fresh water to a smooth batter.","Stir in chopped coriander and enough extra water to make the batter spreadable.","Mix in salt. Reserve unused measured water for adjusting the batter; soaking water is discarded and is additional.","Heat a flat non-stick or well-seasoned tawa over medium heat. Brush lightly with some of the measured oil; the batter should sizzle gently on contact.","Spread thinly from the centre; cook for 2–3 minutes until the top sets, then flip for 1–2 minutes. Drizzle a little oil around each pancake as it cooks.","Repeat with the remaining batter, stirring it between batches. Serve hot; any chutney or accompaniment is additional to these quantities."],"tips":["Soaking or resting is additional to the cooking time. Keep the tawa at steady medium heat so the middle cooks before the outside burns."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Moong Dal Chilla","src":"/photos/moong-dal-chilla-1200.webp","small":"/photos/moong-dal-chilla-600.webp","width":1200,"height":900,"alt":"Moong Dal Chilla served ready to eat","kind":"generated","title":"Moong Dal Chilla","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pesarattu','{"id":"pesarattu","name":"Pesarattu","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole green moong","qty":280,"unit":"g","group":"Other","scale":"linear"},{"name":"rice","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Soak moong and rice for 6–8 hours, drain and blend with ginger, cumin and 250 ml fresh water until fine.","Keep chopped onion separate to scatter over the wet pancakes. This batter does not need fermentation.","Mix in salt. Reserve unused measured water for adjusting the batter; soaking water is discarded and is additional.","Heat a flat non-stick or well-seasoned tawa over medium heat. Brush lightly with some of the measured oil; the batter should sizzle gently on contact.","Spread thinly, scatter onion and press lightly. Cook for 3 minutes until crisp at the edges, flip for 1 minute and fold. Drizzle a little oil around each pancake as it cooks.","Repeat with the remaining batter, stirring it between batches. Serve hot; any chutney or accompaniment is additional to these quantities."],"tips":["Soaking or resting is additional to the cooking time. Keep the tawa at steady medium heat so the middle cooks before the outside burns."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragi-dosa','{"id":"ragi-dosa","name":"Ragi Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"ragi flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":100,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Whisk flours, semolina, cumin and curd with 650 ml water to make a thin, lump-free batter.","Rest for 20 minutes. Stir before every dosa because the flour settles; thin with water if it no longer pours freely.","Mix in salt. Reserve unused measured water for adjusting the batter; soaking water is discarded and is additional.","Heat a flat non-stick or well-seasoned tawa over medium heat. Brush lightly with some of the measured oil; the batter should sizzle gently on contact.","Pour from the outside towards the centre, leaving small holes. Cook for 3–4 minutes until crisp and releasing easily; flip briefly if the centre is still soft. Drizzle a little oil around each pancake as it cooks.","Repeat with the remaining batter, stirring it between batches. Serve hot; any chutney or accompaniment is additional to these quantities."],"tips":["Soaking or resting is additional to the cooking time. Keep the tawa at steady medium heat so the middle cooks before the outside burns."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kuttu-chilla','{"id":"kuttu-chilla","name":"Kuttu Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"buckwheat flour","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Boil the potato until tender, peel and mash smoothly. Mix with buckwheat flour, cumin and about 350 ml water.","Add chopped coriander and beat to a smooth thick batter. If making this for a fast, choose salt and ingredients permitted by your practice.","Mix in salt. Reserve unused measured water for adjusting the batter; soaking water is discarded and is additional.","Heat a flat non-stick or well-seasoned tawa over medium heat. Brush lightly with some of the measured oil; the batter should sizzle gently on contact.","Spread into small 12 cm pancakes that will be easy to turn. Cook for 3 minutes on each side until firm and lightly browned. Drizzle a little oil around each pancake as it cooks.","Repeat with the remaining batter, stirring it between batches. Serve hot; any chutney or accompaniment is additional to these quantities."],"tips":["Soaking or resting is additional to the cooking time. Keep the tawa at steady medium heat so the middle cooks before the outside burns."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kuttu Chilla","src":"/photos/kuttu-chilla-1200.webp","small":"/photos/kuttu-chilla-600.webp","width":1200,"height":900,"alt":"Kuttu Chilla served ready to eat","kind":"generated","title":"Kuttu Chilla","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('akki-roti','{"id":"akki-roti","name":"Akki Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":260,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Mix the flour with very finely chopped onion, grated carrot, coriander and cumin. Add warm water gradually to make a soft, pliable dough.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat a ball into a thin 15 cm round on lightly oiled baking parchment. Invert onto a warm tawa and carefully peel away the parchment before increasing the heat.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Akki Roti","src":"/photos/akki-roti-1200.webp","small":"/photos/akki-roti-600.webp","width":1200,"height":900,"alt":"Akki Roti served ready to eat","kind":"generated","title":"Akki Roti","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('thalipeeth','{"id":"thalipeeth","name":"Thalipeeth","baseServings":4,"batchSize":20,"ingredients":[{"name":"jowar flour","qty":120,"unit":"g","group":"Grains","scale":"linear"},{"name":"whole wheat flour","qty":100,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"gram flour","qty":100,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Mix flours, finely chopped onion, cumin and coriander. Add water gradually to form a soft dough.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat into thin rounds on oiled parchment, making a small hole in the centre. Transfer to a warm tawa and remove the parchment.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Thalipeeth","src":"/photos/thalipeeth-1200.webp","small":"/photos/thalipeeth-600.webp","width":1200,"height":1200,"alt":"Thalipeeth — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Thalipeeth_(Indian_Pancake).jpg","title":"File:Thalipeeth (Indian Pancake).jpg","author":"BhargavVora","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2176,"sourceHeight":2176,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bajra-roti','{"id":"bajra-roti","name":"Bajra Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"bajra flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":280,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Add hot water gradually to the flour using a spoon, then knead once cool enough to handle. Make a soft dough and use immediately.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat each ball between palms or roll gently between sheets of parchment into a 15 cm round; handle carefully because millet dough has no gluten.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bajra Roti","src":"/photos/bajra-roti-1200.webp","small":"/photos/bajra-roti-600.webp","width":1200,"height":800,"alt":"Bajra Roti — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Bajra_Roti_and_Dal.JPG","title":"File:Bajra Roti and Dal.JPG","author":"Jay87.mehta","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jowar-bhakri','{"id":"jowar-bhakri","name":"Jowar Bhakri","baseServings":4,"batchSize":20,"ingredients":[{"name":"jowar flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":280,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Stir hot water gradually into the flour and knead when cool enough to handle until smooth and soft.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat out small rounds on a floured board or between parchment. Lift gently onto the tawa without tearing.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('makki-roti','{"id":"makki-roti","name":"Makki Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"maize flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":280,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Use fine maize flour, not white cornflour starch. Add warm water gradually and knead into a soft dough.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat each ball between parchment into a 14 cm round; peel away the paper carefully while transferring to the tawa.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Makki Roti","src":"/photos/makki-roti-1200.webp","small":"/photos/makki-roti-600.webp","width":1200,"height":900,"alt":"Makki Roti served ready to eat","kind":"generated","title":"Makki Roti","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-thepla','{"id":"methi-thepla","name":"Methi Thepla","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":260,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"gram flour","qty":60,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"fenugreek leaves","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":130,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Wash, dry and finely chop fenugreek. Mix with the flours, curd, turmeric and cumin; add water gradually and knead to a soft dough.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Rest covered for 15 minutes, divide into 12 balls and roll thinly on a lightly floured surface.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('stuffed-paratha','{"id":"stuffed-paratha","name":"Stuffed Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"boiled potato","qty":500,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dried mango powder","qty":4,"unit":"g","group":"Fruits","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"whole wheat flour","qty":360,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mix whole wheat flour with half the salt and 10 ml oil. Add most of the water gradually and knead to a soft dough; cover and rest for 20 minutes.","Mash the peeled cooked potatoes completely. Mix with cumin, dried mango powder, chopped coriander and half the salt; let the filling cool.","Divide dough and filling into 8 equal portions. Roll one dough ball to 10 cm, put filling in the middle, gather the edges and pinch tightly closed.","Flatten gently and roll seam-side down to about 16 cm, using light pressure so the filling stays inside.","Cook on a medium-hot tawa for 1 minute per side to set, then brush with the remaining oil and cook for another 1–2 minutes per side until browned and fully cooked.","Repeat with the remaining portions. Serve hot, cutting one open to check that there is no raw dough around the filling."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Stuffed Paratha","src":"/photos/stuffed-paratha-1200.webp","small":"/photos/stuffed-paratha-600.webp","width":1200,"height":1008,"alt":"Stuffed Paratha — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Stuffed_paratha.jpg","title":"File:Stuffed paratha.jpg","author":"Dhanwanthkurup","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4055,"sourceHeight":3404,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sattu-paratha','{"id":"sattu-paratha","name":"Sattu Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"roasted gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"whole wheat flour","qty":360,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mix whole wheat flour with half the salt and 10 ml oil. Add most of the water gradually and knead to a soft dough; cover and rest for 20 minutes.","Mix roasted gram flour with finely chopped onion, lemon juice, cumin, coriander, half the salt and 20 ml of the oil. Sprinkle in a little water so the filling holds together when squeezed but is not wet.","Divide dough and filling into 8 equal portions. Roll one dough ball to 10 cm, put filling in the middle, gather the edges and pinch tightly closed.","Flatten gently and roll seam-side down to about 16 cm, using light pressure so the filling stays inside.","Cook on a medium-hot tawa for 1 minute per side to set, then brush with the remaining oil and cook for another 1–2 minutes per side until browned and fully cooked.","Repeat with the remaining portions. Serve hot, cutting one open to check that there is no raw dough around the filling."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sattu Paratha","src":"/photos/sattu-paratha-1200.webp","small":"/photos/sattu-paratha-600.webp","width":1200,"height":674,"alt":"Sattu Paratha — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sattu_Paratha.jpg","title":"File:Sattu Paratha.jpg","author":"Samar Fatma","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2592,"sourceHeight":1456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-paratha','{"id":"dal-paratha","name":"Dal Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked chana dal","qty":400,"unit":"g","group":"Pulses","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"whole wheat flour","qty":360,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mix whole wheat flour with half the salt and 10 ml oil. Add most of the water gradually and knead to a soft dough; cover and rest for 20 minutes.","Drain the cooked chana dal thoroughly and mash. Cook in a dry non-stick pan for 3–4 minutes if wet, then cool and mix with cumin, coriander and half the salt.","Divide dough and filling into 8 equal portions. Roll one dough ball to 10 cm, put filling in the middle, gather the edges and pinch tightly closed.","Flatten gently and roll seam-side down to about 16 cm, using light pressure so the filling stays inside.","Cook on a medium-hot tawa for 1 minute per side to set, then brush with the remaining oil and cook for another 1–2 minutes per side until browned and fully cooked.","Repeat with the remaining portions. Serve hot, cutting one open to check that there is no raw dough around the filling."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Paratha","src":"/photos/dal-paratha-1200.webp","small":"/photos/dal-paratha-600.webp","width":1200,"height":900,"alt":"Dal Paratha — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Moong_Dal_paratha.jpg","title":"File:Moong Dal paratha.jpg","author":"Ravi Dwivedi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4000,"sourceHeight":3000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lachha-paratha','{"id":"lachha-paratha","name":"Lachha Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":360,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":230,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":55,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mix flour and salt, reserving a little flour for dusting. Add 15 ml oil and water gradually; knead to a smooth soft dough.","Cover and rest for 25 minutes, then divide into 8 equal balls.","Roll a ball thinly, brush with a little oil and dust lightly with flour. Fold back and forth into narrow pleats like a paper fan.","Coil the pleated strip into a spiral, tuck the end underneath and rest for 5 minutes. Roll gently to 15 cm without pressing out all the layers.","Cook on a medium-hot tawa, turning and brushing with the remaining oil, for 4–5 minutes total until golden and cooked through.","Press the cooked paratha gently between your palms using a cloth to separate the layers. Serve warm."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Lachha Paratha","src":"/photos/lachha-paratha-1200.webp","small":"/photos/lachha-paratha-600.webp","width":1200,"height":900,"alt":"Lachha Paratha served ready to eat","kind":"generated","title":"Lachha Paratha","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-naan','{"id":"eggless-naan","name":"Eggless Naan","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":360,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"milk","qty":130,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"baking powder","qty":6,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"butter","qty":20,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Mix flour, baking powder, sugar and salt. Stir in curd, oil and most of the milk, adding the rest as needed for a soft slightly tacky dough.","Knead for 5 minutes, cover and rest for 45 minutes. This quick naan uses baking powder and does not need yeast.","Divide into 8 balls and roll each into an oval about 4 mm thick, using minimal extra flour.","Heat a heavy skillet over medium-high heat. Cook one naan for 1–2 minutes until bubbles rise and the underside has brown spots.","Turn and cook for 1–2 minutes more; lower heat if the outside browns before the centre cooks. Repeat with the remaining dough.","Brush with melted butter and keep covered in a clean cloth until serving."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Naan","src":"/photos/eggless-naan-1200.webp","small":"/photos/eggless-naan-600.webp","width":1200,"height":900,"alt":"Eggless Naan served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Naan_baked_in_Tandoor.jpg","title":"File:Naan baked in Tandoor.jpg","author":"Ravi Dwivedi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-upma','{"id":"vegetable-upma","name":"Vegetable Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":260,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":850,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Dry-roast semolina over medium-low heat for 5 minutes, stirring until aromatic but not brown; transfer to a bowl.","Prepare the vegetables: finely chop onion and tomato if listed; dice or grate carrot and potato into small pieces for even cooking.","Heat oil in a deep pan. Let mustard seeds pop, add curry leaves carefully, and toast any listed peanuts until golden. Add onion and cook for 4 minutes.","Add turmeric and the remaining listed vegetables. Cook for 5–8 minutes, covering briefly with a splash of the measured water if needed, until potato or carrot is tender.","Add measured water and salt and bring to a rolling boil.","Add the semolina gradually in a steady stream while stirring continuously to prevent lumps. Cover and cook on low heat for 5–7 minutes.","Turn off the heat, add lemon juice and rest for 2 minutes before serving. Keep the texture soft but not wet."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Upma","src":"/photos/vegetable-upma-1200.webp","small":"/photos/vegetable-upma-600.webp","width":1200,"height":900,"alt":"Vegetable Upma — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Upma..JPG","title":"File:Upma..JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4896,"sourceHeight":3672,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-sevai-upma','{"id":"vegetable-sevai-upma","name":"Vegetable Sevai Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"wheat vermicelli","qty":280,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["If the vermicelli is not pre-roasted, toast it in a dry pan for 3–4 minutes until light golden. Break into manageable lengths.","Prepare the vegetables: finely chop onion and tomato if listed; dice or grate carrot and potato into small pieces for even cooking.","Heat oil in a deep pan. Let mustard seeds pop, add curry leaves carefully, and toast any listed peanuts until golden. Add onion and cook for 4 minutes.","Add turmeric and the remaining listed vegetables. Cook for 5–8 minutes, covering briefly with a splash of the measured water if needed, until potato or carrot is tender.","Add measured water and salt and bring to a rolling boil.","Add vermicelli, stir once and cover on low heat for 6–8 minutes or until tender and the water is absorbed; follow packet water guidance if it differs.","Turn off the heat, add lemon juice and rest for 2 minutes before serving. Keep the texture soft but not wet."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bread-upma','{"id":"bread-upma","name":"Bread Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless bread","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cut bread into 2 cm cubes. Slightly dry bread holds its shape better; discard any bread with mould.","Prepare the vegetables: finely chop onion and tomato if listed; dice or grate carrot and potato into small pieces for even cooking.","Heat oil in a deep pan. Let mustard seeds pop, add curry leaves carefully, and toast any listed peanuts until golden. Add onion and cook for 4 minutes.","Add turmeric and the remaining listed vegetables. Cook for 5–8 minutes, covering briefly with a splash of the measured water if needed, until potato or carrot is tender.","Add salt and the measured water; let the tomato base simmer for 2 minutes.","Add bread cubes and toss gently for 3–4 minutes so the tomato seasoning coats them without turning them into paste.","Turn off the heat, add lemon juice and rest for 2 minutes before serving. Keep the texture soft but not wet."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bread Upma","src":"/photos/bread-upma-1200.webp","small":"/photos/bread-upma-600.webp","width":1200,"height":1600,"alt":"Bread Upma served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Upma_India.jpg","title":"File:Upma India.jpg","author":"Divya Kudua","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1707,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('idli-upma','{"id":"idli-upma","name":"Idli Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked idli","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Crumble chilled, safely refrigerated idlis by hand into small uneven pieces. Grate the carrot.","Prepare the vegetables: finely chop onion and tomato if listed; dice or grate carrot and potato into small pieces for even cooking.","Heat oil in a deep pan. Let mustard seeds pop, add curry leaves carefully, and toast any listed peanuts until golden. Add onion and cook for 4 minutes.","Add turmeric and the remaining listed vegetables. Cook for 5–8 minutes, covering briefly with a splash of the measured water if needed, until potato or carrot is tender.","Add salt and a small sprinkle of water if the vegetables look dry.","Add the crumbled idli, sprinkle with measured water and stir for 4–5 minutes until heated through.","Turn off the heat, add lemon juice and rest for 2 minutes before serving. Keep the texture soft but not wet."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Idli Upma","src":"/photos/idli-upma-1200.webp","small":"/photos/idli-upma-600.webp","width":1200,"height":800,"alt":"Idli Upma served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Idly_upma_02.jpg","title":"File:Idly upma 02.jpg","author":"Nandhinikandhasamy","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('poha','{"id":"poha","name":"Poha","baseServings":4,"batchSize":50,"ingredients":[{"name":"thick poha","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peanuts","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.18},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse thick poha gently in a sieve, drain and rest for 10 minutes. It should soften without turning mushy. Peel and cut potato into small cubes.","Prepare the vegetables: finely chop onion and tomato if listed; dice or grate carrot and potato into small pieces for even cooking.","Heat oil in a deep pan. Let mustard seeds pop, add curry leaves carefully, and toast any listed peanuts until golden. Add onion and cook for 4 minutes.","Add turmeric and the remaining listed vegetables. Cook for 5–8 minutes, covering briefly with a splash of the measured water if needed, until potato or carrot is tender.","Add salt and a small sprinkle of water if the vegetables look dry.","Add softened poha and toss gently. Cover over low heat for 3–4 minutes until hot, adding only a sprinkle of water if it seems dry.","Turn off the heat, add lemon juice and rest for 2 minutes before serving. Keep the texture soft but not wet."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sabudana-khichdi','{"id":"sabudana-khichdi","name":"Sabudana Khichdi","baseServings":4,"batchSize":50,"ingredients":[{"name":"sabudana","qty":280,"unit":"g","group":"Other","scale":"linear"},{"name":"potato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"roasted peanuts","qty":90,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse sabudana until the water is clearer. Add just enough of the measured water to reach its surface and soak 4–6 hours or overnight, depending on pearl size.","Check a pearl: it must crush easily with no hard centre. Drain any excess water thoroughly; wet pearls turn sticky.","Crush roasted peanuts coarsely and mix with the drained pearls and salt. Peel and dice potato into small cubes.","Heat ghee, sizzle cumin and cook potato over medium-low heat for 10–12 minutes, covering briefly, until completely tender.","Add the sabudana mixture and fold gently over low-medium heat for 5–7 minutes until the pearls look translucent. Do not keep stirring or overcook.","Turn off the heat and finish with lemon juice and coriander. Serve immediately; soaking time is additional."],"tips":["Cook one small test portion first and adjust the consistency and heat before cooking the rest."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chickpea-cucumber-salad','{"id":"chickpea-cucumber-salad","name":"Chickpea Cucumber Salad","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked chickpeas","qty":600,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"cucumber","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"parsley","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"lemon juice","qty":35,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Rinse and drain fully cooked chickpeas. Dice cucumber and tomato and finely chop onion and parsley.","Whisk olive oil, lemon juice, salt and pepper until combined.","Toss chickpeas, vegetables and parsley with the dressing. Rest for 10 minutes so the chickpeas absorb the seasoning.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chickpea Cucumber Salad","src":"/photos/chickpea-cucumber-salad-1200.webp","small":"/photos/chickpea-cucumber-salad-600.webp","width":1200,"height":900,"alt":"Chickpea Cucumber Salad served ready to eat","kind":"generated","title":"Chickpea Cucumber Salad","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kosambari','{"id":"kosambari","name":"Kosambari","baseServings":4,"batchSize":20,"ingredients":[{"name":"moong dal","qty":160,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"cucumber","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"grated coconut","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":4,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Rinse moong dal and soak for 2 hours, then drain thoroughly. Dice cucumber and grate carrot. For a cooked version, simmer soaked dal for 5–8 minutes until just tender, then drain and cool.","Heat oil and let mustard seeds pop, add curry leaves carefully, then cool the tempering for a minute.","Mix dal, vegetables, coconut and coriander. Add cooled tempering, lemon juice and salt immediately before serving.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sprouted-moong-salad','{"id":"sprouted-moong-salad","name":"Sprouted Moong Salad","baseServings":4,"batchSize":20,"ingredients":[{"name":"moong sprouts","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":35,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"olive oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Rinse sprouts and simmer in fresh boiling water for 8–10 minutes until fully cooked. Drain and cool promptly. Dice cucumber and tomato; finely chop onion.","Whisk lemon juice, oil, cumin and salt.","Combine the cooked sprouts and prepared vegetables, add the dressing and fold gently. Scatter coriander over the top.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sprouted Moong Salad","src":"/photos/sprouted-moong-salad-1200.webp","small":"/photos/sprouted-moong-salad-600.webp","width":1200,"height":1200,"alt":"Sprouted Moong Salad — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sprouted_Moong_Salad.JPG","title":"File:Sprouted Moong Salad.JPG","author":"Abhijit Patil","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2448,"sourceHeight":2448,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tabbouleh','{"id":"tabbouleh","name":"Tabbouleh","baseServings":4,"batchSize":20,"ingredients":[{"name":"fine bulgur","qty":140,"unit":"g","group":"Grains","scale":"linear"},{"name":"parsley","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"mint","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"olive oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"lemon juice","qty":60,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Cover fine bulgur with the measured boiling water, cover for 15–20 minutes until tender and fluff. Drain any excess and cool. Finely chop the herbs, tomatoes, cucumber and spring onion.","Whisk oil, lemon juice, salt and pepper.","Fold the cooled bulgur, vegetables and herbs together. Toss with dressing and rest for 15 minutes; the herbs should remain the main ingredient.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tabbouleh","src":"/photos/tabbouleh-1200.webp","small":"/photos/tabbouleh-600.webp","width":1200,"height":900,"alt":"Tabbouleh — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Flickr_-_cyclonebill_-_Tabbouleh.jpg","title":"File:Flickr - cyclonebill - Tabbouleh.jpg","author":"cyclonebill","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3264,"sourceHeight":2448,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('panzanella','{"id":"panzanella","name":"Panzanella","baseServings":4,"batchSize":20,"ingredients":[{"name":"stale eggless bread","qty":280,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":600,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"olive oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"red wine vinegar","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Cube the bread and toast at 180°C for 8–10 minutes until dry at the edges. Chop tomatoes and cucumber, thinly slice onion and tear basil.","Whisk oil, vinegar, salt and pepper with any juices collected from the chopped tomatoes.","Toss bread with tomatoes, cucumber, onion and dressing. Rest for 15–20 minutes so the bread softens slightly, then fold in basil.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Panzanella","src":"/photos/panzanella-1200.webp","small":"/photos/panzanella-600.webp","width":900,"height":1200,"alt":"Panzanella — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Panzanella_con_pomodori_a_grappolo.jpg","title":"File:Panzanella con pomodori a grappolo.jpg","author":"Albarubescens","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3334,"sourceHeight":4445,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('watermelon-feta-salad','{"id":"watermelon-feta-salad","name":"Watermelon Feta Salad","baseServings":4,"batchSize":20,"ingredients":[{"name":"watermelon","qty":900,"unit":"g","group":"Fruits","scale":"linear"},{"name":"vegetarian feta cheese","qty":160,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"mint","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"lime juice","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Remove watermelon rind and seeds and cut the flesh into cubes. Dice cucumber, pat it dry and crumble feta labelled suitable for vegetarians.","Whisk oil, lime juice and pepper. Taste the feta before adding any salt because it can be quite salty.","Arrange chilled watermelon and cucumber, scatter feta and torn mint, and drizzle with dressing just before serving.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Watermelon Feta Salad","src":"/photos/watermelon-feta-salad-1200.webp","small":"/photos/watermelon-feta-salad-600.webp","width":1200,"height":800,"alt":"Watermelon Feta Salad — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Watermelon_%26_Feta_Salad.jpg","title":"File:Watermelon & Feta Salad.jpg","author":"Shoshanah","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fruit-chaat','{"id":"fruit-chaat","name":"Fruit Chaat","baseServings":4,"batchSize":20,"ingredients":[{"name":"apple","qty":250,"unit":"g","group":"Fruits","scale":"linear"},{"name":"banana","qty":250,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"orange","qty":250,"unit":"g","group":"Fruits","scale":"linear"},{"name":"pomegranate arils","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"grapes","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"chaat masala","qty":3,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash fresh produce under running water and use a clean board. Measure the ingredients for four servings.","Wash fruit, core the apple, peel banana and orange, and remove any seeds. Cut into bite-size pieces; halve grapes.","Mix lemon juice, cumin, black salt and chaat masala in a large bowl.","Add the fruit and toss gently without crushing the banana. Taste before adding any more seasoning.","Taste a portion containing both the main ingredients and dressing, then adjust acidity or salt if needed.","Serve promptly. Refrigerate prepared components if holding them for later; add delicate herbs and dressing near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Fruit Chaat","src":"/photos/fruit-chaat-1200.webp","small":"/photos/fruit-chaat-600.webp","width":1200,"height":900,"alt":"Fruit Chaat served ready to eat","kind":"generated","title":"Fruit Chaat","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('avocado-toast','{"id":"avocado-toast","name":"Avocado Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless wholegrain bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"avocado flesh","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"olive oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Measure the ingredients and wash and dry any vegetables or herbs before cutting.","Mash avocado with lemon juice, salt and pepper, leaving a little texture.","Toast the bread until crisp and golden; brush lightly with olive oil.","Spread avocado generously over the warm toast and serve immediately.","Let very hot toasted sandwiches stand for 1 minute before slicing; serve open toasts immediately.","Make only the portions needed for serving now. Keep any remaining filling covered and refrigerated."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Avocado Toast","src":"/photos/avocado-toast-1200.webp","small":"/photos/avocado-toast-600.webp","width":1080,"height":1080,"alt":"Avocado Toast — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Avocado_toast_with_sesame_seeds.jpg","title":"File:Avocado toast with sesame seeds.jpg","author":"Jami430","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1080,"sourceHeight":1080,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bruschetta','{"id":"bruschetta","name":"Bruschetta","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless baguette","qty":320,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"balsamic vinegar","qty":15,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Measure the ingredients and wash and dry any vegetables or herbs before cutting.","Dice tomatoes and drain excess liquid. Toss with torn basil, half the oil, vinegar, salt and pepper.","Slice bread diagonally and brush with the remaining oil. Toast at 200°C for 6–8 minutes, then rub one side lightly with a cut garlic clove.","Spoon the tomato mixture over the toast just before eating so the bread stays crisp.","Let very hot toasted sandwiches stand for 1 minute before slicing; serve open toasts immediately.","Make only the portions needed for serving now. Keep any remaining filling covered and refrigerated."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bruschetta","src":"/photos/bruschetta-1200.webp","small":"/photos/bruschetta-600.webp","width":900,"height":1200,"alt":"Bruschetta — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Bruschetta.jpg","title":"File:Bruschetta.jpg","author":"Popo le Chien","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3120,"sourceHeight":4160,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-sandwich','{"id":"vegetable-sandwich","name":"Vegetable Sandwich","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless bread","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mint chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Measure the ingredients and wash and dry any vegetables or herbs before cutting.","Thinly slice cucumber, tomato and peeled boiled potato. Pat vegetables dry and check that the chutney ingredients suit your dietary restrictions.","Spread bread thinly with butter and mint chutney, keeping a small border.","Layer potato, cucumber and tomato, season lightly with salt and pepper, close and cut into triangles.","Let very hot toasted sandwiches stand for 1 minute before slicing; serve open toasts immediately.","Make only the portions needed for serving now. Keep any remaining filling covered and refrigerated."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-grilled-sandwich','{"id":"paneer-grilled-sandwich","name":"Paneer Grilled Sandwich","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless bread","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"paneer","qty":300,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"vegetarian cheese","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Measure the ingredients and wash and dry any vegetables or herbs before cutting.","Crumble paneer, finely dice capsicum and onion, and mix with grated vegetarian cheese, cumin, salt and pepper.","Butter the outside faces of the bread lightly. Divide filling between four sandwiches, keeping the edges clear.","Cook in a sandwich press for 4–6 minutes, or on a covered skillet for 3–4 minutes per side, until the centre is hot and bread is golden.","Let very hot toasted sandwiches stand for 1 minute before slicing; serve open toasts immediately.","Make only the portions needed for serving now. Keep any remaining filling covered and refrigerated."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('overnight-oats','{"id":"overnight-oats","name":"Overnight Oats","baseServings":4,"batchSize":20,"ingredients":[{"name":"rolled oats","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"chia seeds","qty":30,"unit":"g","group":"Other","scale":"linear"},{"name":"banana","qty":240,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"dates","qty":60,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3},{"name":"cinnamon powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Use rolled oats rather than coarse steel-cut oats. Finely chop pitted dates and measure the remaining ingredients.","Mix oats, milk, curd, chia seeds, dates and cinnamon until no dry clumps remain.","Divide between four covered jars, leaving room for the oats to expand.","Refrigerate for at least 6 hours or overnight; do not leave the milk mixture at room temperature.","Stir in the morning and loosen with a splash of milk if needed. Peel and slice the banana immediately before serving.","Top each jar with banana and serve cold. Keep unused portions refrigerated."],"tips":["The hands-on preparation takes 10 minutes; allow at least 6 hours in the refrigerator."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chia-pudding','{"id":"chia-pudding","name":"Chia Pudding","baseServings":4,"batchSize":20,"ingredients":[{"name":"chia seeds","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"milk","qty":700,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"maple syrup","qty":45,"unit":"ml","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"strawberry","qty":250,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Whisk milk, maple syrup and vanilla together in a bowl.","Sprinkle in chia seeds while whisking so they do not clump at the bottom.","Rest for 10 minutes and whisk again, breaking up any clusters.","Divide into four covered jars and refrigerate for at least 4 hours until thick and spoonable.","Wash, hull and slice strawberries shortly before serving. Stir the puddings and add a splash of milk if too firm.","Top with strawberries and serve chilled."],"tips":["Allow at least 4 hours chilling in addition to hands-on preparation."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chia Pudding","src":"/photos/chia-pudding-1200.webp","small":"/photos/chia-pudding-600.webp","width":1200,"height":900,"alt":"Chia Pudding served ready to eat","kind":"generated","title":"Chia Pudding","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('corn-chaat','{"id":"corn-chaat","name":"Corn Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked sweet corn","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Measure ingredients and wash fresh vegetables and coriander.","Drain hot cooked sweet corn thoroughly; finely chop tomato and onion.","Mix lemon juice, chaat masala, cumin and salt in a large bowl. Begin with less salt because chaat masala already contains some.","Toss warm corn with tomato and onion.","Pour over the dressing and toss gently. Add finely chopped coriander.","Taste and serve while fresh. If preparing ahead, chill cooked ingredients promptly and add raw vegetables and lemon near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Corn Chaat","src":"/photos/corn-chaat-1200.webp","small":"/photos/corn-chaat-600.webp","width":1200,"height":900,"alt":"Corn Chaat — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Cheesy_Corn_Chaat_a_5_minute_recipe_-_Gujarat_-_SHAILI_012.jpg","title":"File:Cheesy Corn Chaat a 5 minute recipe - Gujarat - SHAILI 012.jpg","author":"Shaili Sharma","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4096,"sourceHeight":3072,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('peanut-chaat','{"id":"peanut-chaat","name":"Peanut Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"raw peanuts","qty":300,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Measure ingredients and wash fresh vegetables and coriander.","Boil peanuts in plenty of water for 25–35 minutes until tender, then drain. Dice tomato and cucumber and finely chop onion.","Mix lemon juice, chaat masala, cumin and salt in a large bowl. Begin with less salt because chaat masala already contains some.","Toss the warm drained peanuts with the vegetables.","Pour over the dressing and toss gently. Add finely chopped coriander.","Taste and serve while fresh. If preparing ahead, chill cooked ingredients promptly and add raw vegetables and lemon near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Peanut Chaat","src":"/photos/peanut-chaat-1200.webp","small":"/photos/peanut-chaat-600.webp","width":1200,"height":1600,"alt":"Peanut Chaat served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Peanut_Salad.jpg","title":"File:Peanut Salad.jpg","author":"Bhavika1990","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1707,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sprouts-chaat','{"id":"sprouts-chaat","name":"Sprouts Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"moong sprouts","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Measure ingredients and wash fresh vegetables and coriander.","Simmer rinsed sprouts in boiling water for 8–10 minutes until fully cooked, then drain. Dice peeled boiled potato and tomato; chop onion.","Mix lemon juice, chaat masala, cumin and salt in a large bowl. Begin with less salt because chaat masala already contains some.","Mix the cooked sprouts and potato with tomato and onion.","Pour over the dressing and toss gently. Add finely chopped coriander.","Taste and serve while fresh. If preparing ahead, chill cooked ingredients promptly and add raw vegetables and lemon near serving time."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhel-puri','{"id":"bhel-puri","name":"Bhel Puri","baseServings":4,"batchSize":50,"ingredients":[{"name":"puffed rice","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"papdi","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use ready-made vegetarian, eggless shells or papdi and chutneys; check their ingredient labels for allergens and exclusions.","Dry-toast puffed rice for 2 minutes if needed and cool completely. Dice potato and tomato and finely chop onion.","Set out both chutneys in separate bowls so you can control sweetness and heat.","Mix puffed rice with vegetables and broken papdi. Add both chutneys and toss quickly; finish with sev.","Sprinkle evenly with chaat masala and chopped coriander. Start with less masala and taste before adding more.","Serve immediately before the crisp base softens. Keep extra dry components separate from chutneys and curd."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bhel Puri","src":"/photos/bhel-puri-1200.webp","small":"/photos/bhel-puri-600.webp","width":1200,"height":900,"alt":"Bhel Puri served ready to eat","kind":"generated","title":"Bhel Puri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sev-puri','{"id":"sev-puri","name":"Sev Puri","baseServings":4,"batchSize":50,"ingredients":[{"name":"papdi","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":300,"unit":"g","group":"Packaged","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sev","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use ready-made vegetarian, eggless shells or papdi and chutneys; check their ingredient labels for allergens and exclusions.","Dice the potato and finely chop onion. Arrange papdi in a single layer on four plates.","Set out both chutneys in separate bowls so you can control sweetness and heat.","Top each papdi with potato and onion, drizzle both chutneys and finish with sev.","Sprinkle evenly with chaat masala and chopped coriander. Start with less masala and taste before adding more.","Serve immediately before the crisp base softens. Keep extra dry components separate from chutneys and curd."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sev Puri","src":"/photos/sev-puri-1200.webp","small":"/photos/sev-puri-600.webp","width":1200,"height":677,"alt":"Sev Puri — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sev_puri_with_sweet_curd.JPG","title":"File:Sev puri with sweet curd.JPG","author":"Dheerajk88","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4288,"sourceHeight":2418,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('papdi-chaat','{"id":"papdi-chaat","name":"Papdi Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"papdi","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cooked chickpeas","qty":250,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"curd","qty":350,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sev","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use ready-made vegetarian, eggless shells or papdi and chutneys; check their ingredient labels for allergens and exclusions.","Dice potato, drain cooked chickpeas and whisk curd smooth. Arrange papdi on serving plates.","Set out both chutneys in separate bowls so you can control sweetness and heat.","Spoon potato and chickpeas over papdi, add curd, drizzle chutneys and finish with sev.","Sprinkle evenly with chaat masala and chopped coriander. Start with less masala and taste before adding more.","Serve immediately before the crisp base softens. Keep extra dry components separate from chutneys and curd."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dahi-puri','{"id":"dahi-puri","name":"Dahi Puri","baseServings":4,"batchSize":50,"ingredients":[{"name":"ready-made puri shells","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":300,"unit":"g","group":"Packaged","scale":"linear"},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use ready-made vegetarian, eggless shells or papdi and chutneys; check their ingredient labels for allergens and exclusions.","Dice potato and whisk curd until smooth. Gently crack a small opening in the top of each puri shell.","Set out both chutneys in separate bowls so you can control sweetness and heat.","Fill each shell with potato, a little of each chutney and curd. Sprinkle sev over the top and serve at once.","Sprinkle evenly with chaat masala and chopped coriander. Start with less masala and taste before adding more.","Serve immediately before the crisp base softens. Keep extra dry components separate from chutneys and curd."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dahi Puri","src":"/photos/dahi-puri-1200.webp","small":"/photos/dahi-puri-600.webp","width":1200,"height":900,"alt":"Dahi Puri served ready to eat","kind":"generated","title":"Dahi Puri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pani-puri','{"id":"pani-puri","name":"Pani Puri","baseServings":4,"batchSize":50,"ingredients":[{"name":"ready-made puri shells","qty":140,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":350,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cooked chickpeas","qty":250,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"mint","qty":40,"unit":"g","group":"Spices","scale":"linear"},{"name":"coriander","qty":40,"unit":"g","group":"Spices","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"tamarind paste","qty":35,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"jaggery","qty":35,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash mint and coriander thoroughly. Blend them with ginger, tamarind, lemon juice, cumin, black salt, jaggery and 150 ml of the drinking water.","Stir the paste into the remaining chilled drinking water. Strain if desired, then taste and adjust the sour-sweet balance.","Refrigerate the pani for 30 minutes while preparing the filling.","Dice the boiled potato and mix with drained, fully cooked chickpeas. Check that purchased puri shells are vegetarian and eggless.","Crack a small hole in each shell, add a spoonful of filling and dip or spoon in the chilled pani.","Eat immediately, assembling one puri at a time so it stays crisp. Keep unused pani refrigerated."],"tips":["Chilling time is additional; use safe drinking water for pani."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pani Puri","src":"/photos/pani-puri-1200.webp","small":"/photos/pani-puri-600.webp","width":1200,"height":795,"alt":"Pani Puri — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Pani_Puri1.JPG","title":"File:Pani Puri1.JPG","author":"Sruthi612","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4928,"sourceHeight":3264,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('nachos-with-salsa','{"id":"nachos-with-salsa","name":"Nachos with Salsa","baseServings":4,"batchSize":20,"ingredients":[{"name":"corn tortilla chips","qty":250,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":400,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lime juice","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"vegetarian cheese","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cooked black beans","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Preheat the oven to 190°C. Dice tomatoes and onion finely and chop coriander.","Mix tomato, onion, coriander, lime juice and salt for the salsa. Drain excess watery tomato juice so it does not soak the chips.","Rinse and drain cooked black beans, then warm with cumin and a splash of water for 3–4 minutes.","Spread chips on a baking tray, scatter beans and grated cheese labelled suitable for vegetarians over them.","Bake for 5–7 minutes, just until the cheese melts. Watch carefully because thin chips scorch quickly.","Serve immediately with salsa on the side or spooned on at the last moment."],"tips":["Prepare components ahead, but combine wet dressings and crisp ingredients just before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Nachos with Salsa","src":"/photos/nachos-with-salsa-1200.webp","small":"/photos/nachos-with-salsa-600.webp","width":1200,"height":888,"alt":"Nachos with Salsa served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Home_made_salsa_dip_with_nachos.jpg","title":"File:Home made salsa dip with nachos.jpg","author":"Shreya13jain","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":947,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pumpkin-soup','{"id":"pumpkin-soup","name":"Pumpkin Soup","baseServings":4,"batchSize":50,"ingredients":[{"name":"pumpkin","qty":900,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cream","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Peel and deseed pumpkin and cut into 2 cm cubes. Dice onion and mince garlic.","Heat oil in a deep saucepan and soften onion for 6–8 minutes without browning. Add garlic and cook for 1 minute.","Add pumpkin, water and salt. Bring to a boil, lower the heat and simmer partly covered for 20–25 minutes until the pumpkin breaks easily with a spoon.","Remove from the heat and blend smooth with an immersion blender. If using a jug blender, cool first and follow its hot-liquid instructions.","Return to low heat and stir in cream and pepper. Warm for 2–3 minutes, thinning with a little hot water if needed.","Taste, adjust seasoning and serve hot in four bowls."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sweet-corn-soup','{"id":"sweet-corn-soup","name":"Sweet Corn Soup","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet corn","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cornflour starch","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"white pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"soy sauce","qty":10,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Blend half the corn with 200 ml of the water into a coarse puree. Finely dice carrot and beans and slice spring onion, keeping the green tops separate.","Heat oil and soften the white spring onion parts, carrot and beans for 3 minutes.","Add corn puree, remaining whole corn and 800 ml water. Bring to a boil and simmer for 10–12 minutes until the vegetables are tender.","Mix cornflour starch with the remaining 100 ml cold water until smooth. Stir the simmering soup and pour in the slurry slowly.","Simmer for 3 minutes until lightly thickened and the starch is cooked. Add soy sauce, pepper and salt to taste.","Scatter the reserved spring onion tops over the soup and serve hot."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tomato-rasam','{"id":"tomato-rasam","name":"Tomato Rasam","baseServings":4,"batchSize":50,"ingredients":[{"name":"tomato","qty":450,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black pepper","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Chop tomatoes and lightly crush cumin, pepper and garlic together. Dilute tamarind paste with the measured water.","Put tomato, tamarind water, turmeric and salt in a saucepan. Simmer for 10–12 minutes until the tomato is soft.","Add crushed cumin, pepper and garlic and simmer gently for 4–5 minutes until fragrant.","Heat oil in a small pan, let mustard seeds pop and add curry leaves carefully. Pour this tempering into the rasam.","Heat until foam appears around the edges, then turn off the heat; avoid prolonged boiling after tempering.","Add chopped coriander, cover for 5 minutes and serve hot as a soup or rice accompaniment."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mulligatawny-soup','{"id":"mulligatawny-soup","name":"Mulligatawny Soup","baseServings":4,"batchSize":50,"ingredients":[{"name":"masoor dal","qty":160,"unit":"g","group":"Pulses","scale":"linear"},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"apple","qty":150,"unit":"g","group":"Fruits","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"curry powder","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut milk","qty":250,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Rinse red lentils. Peel and dice carrot and apple, chop onion and tomato, and mince ginger and garlic.","Heat oil and soften onion and carrot for 6 minutes. Add ginger and garlic for 1 minute, then stir curry powder in for 20 seconds.","Add lentils, apple, tomato, water and salt. Bring to a boil, skim foam and simmer partly covered for 25–30 minutes until the lentils and carrot are soft.","Blend part or all of the soup with an immersion blender off the heat, depending on the texture you prefer.","Stir in coconut milk and warm gently for 4 minutes. Thin with hot water if the soup is too thick.","Turn off the heat, add lemon juice, taste and serve hot."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mulligatawny Soup","src":"/photos/mulligatawny-soup-1200.webp","small":"/photos/mulligatawny-soup-600.webp","width":1200,"height":900,"alt":"Mulligatawny Soup served ready to eat","kind":"generated","title":"Mulligatawny Soup","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-minestrone','{"id":"vegetable-minestrone","name":"Vegetable Minestrone","baseServings":4,"batchSize":50,"ingredients":[{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"celery","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"zucchini","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":400,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cooked white beans","qty":400,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"eggless small pasta","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"water","qty":1400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"dried oregano","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"basil","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Dice onion, carrot, celery and zucchini into small even pieces. Chop tomatoes, mince garlic and drain fully cooked beans.","Heat oil in a large saucepan and soften onion, carrot and celery for 8 minutes. Add garlic and oregano for 1 minute.","Add tomatoes, water, salt and pepper. Simmer for 15 minutes until the carrot is nearly tender.","Add zucchini and pasta and simmer for the pasta packet cooking time, usually 8–12 minutes, stirring so it does not stick.","Add cooked beans for the final 5 minutes. Check the pasta is tender and adjust the liquid because it absorbs soup as it stands.","Finish with torn basil and serve hot. For making ahead, cook and store the pasta separately, then combine on reheating."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-stew','{"id":"vegetable-stew","name":"Vegetable Stew","baseServings":4,"batchSize":50,"ingredients":[{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coconut oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Peel and cube potato and carrot, trim beans into short lengths, slice onion and cut ginger into thin strips.","Heat coconut oil and add cinnamon, lightly crushed cardamom and curry leaves. Soften onion and ginger for 4 minutes without browning.","Add potato, carrot, beans, water and salt. Cover and simmer for 12–15 minutes until the vegetables are nearly tender.","Add peas and half the coconut milk. Simmer gently for 5–6 minutes until all vegetables are cooked.","Lower the heat and stir in the remaining coconut milk and pepper. Heat through for 2 minutes without a vigorous boil.","Taste, rest covered for 5 minutes and serve. Remove whole cinnamon and cardamom before eating."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('avial','{"id":"avial","name":"Avial","baseServings":4,"batchSize":50,"ingredients":[{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"pumpkin","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"raw banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"grated coconut","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coconut oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Peel vegetables as needed and cut into similar finger-length batons. Blend coconut, cumin and chilli coarsely with 60 ml of the water.","Put carrot, beans and raw banana in a wide pan with the remaining water, turmeric and salt. Cover and simmer for 8 minutes.","Add pumpkin and cook another 7–10 minutes until all vegetables are tender but retain their shape.","Fold in the coconut paste gently and cook on low heat for 4 minutes. The mixture should be moist with very little free liquid.","Turn off the heat and let the pan cool for 2 minutes. Fold in smooth whisked curd without boiling it.","Drizzle coconut oil and add torn curry leaves. Cover for 5 minutes before serving."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Avial","src":"/photos/avial-1200.webp","small":"/photos/avial-600.webp","width":1200,"height":900,"alt":"Avial served ready to eat","kind":"generated","title":"Avial","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('haak-saag','{"id":"haak-saag","name":"Haak Saag","baseServings":4,"batchSize":50,"ingredients":[{"name":"collard greens","qty":800,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard oil","qty":25,"unit":"ml","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"asafoetida","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash collard greens thoroughly in several changes of water. Strip away tough thick stems and cut large leaves into manageable pieces.","Heat mustard oil according to its cooking instructions, then reduce to medium heat. Add asafoetida and slit green chillies briefly.","Add the measured water carefully and bring it to a boil with salt.","Add greens in batches, pressing them into the boiling liquid until wilted.","Simmer partly covered for 20–25 minutes until the leaves are tender; add a little hot water if they begin to dry out.","Taste and serve the greens with their light cooking broth. Avoid reducing the liquid to a dry masala."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Haak Saag","src":"/photos/haak-saag-1200.webp","small":"/photos/haak-saag-600.webp","width":1200,"height":900,"alt":"Haak Saag served ready to eat","kind":"generated","title":"Haak Saag","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('nadur-yakhni','{"id":"nadur-yakhni","name":"Nadur Yakhni","baseServings":4,"batchSize":50,"ingredients":[{"name":"lotus stem","qty":650,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"fennel powder","qty":6,"unit":"g","group":"Other","scale":"linear"},{"name":"dry ginger powder","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Peel lotus stems, slice into 1 cm rounds and wash thoroughly through the holes to remove mud.","Simmer in 500 ml of the water for 25–35 minutes, adding more boiling water if needed, until a knife enters easily. Drain, reserving some liquid.","Whisk curd completely smooth with fennel powder, ginger powder and the remaining 200 ml water.","Heat ghee, sizzle cumin, cinnamon and lightly crushed cardamom. Lower the heat and add the curd mixture gradually, stirring continuously.","Once the sauce is gently steaming, add cooked lotus stem and salt. Simmer very gently for 10 minutes, stirring; do not boil hard.","Adjust to a pourable sauce using reserved cooking liquid and serve hot. Remove whole spices before eating."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Nadur Yakhni","src":"/photos/nadur-yakhni-1200.webp","small":"/photos/nadur-yakhni-600.webp","width":1200,"height":900,"alt":"Nadur Yakhni served ready to eat","kind":"generated","title":"Nadur Yakhni","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ratatouille','{"id":"ratatouille","name":"Ratatouille","baseServings":4,"batchSize":50,"ingredients":[{"name":"brinjal","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"zucchini","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"dried thyme","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Cut brinjal, zucchini and capsicum into 2 cm pieces. Dice onion and tomato and mince garlic.","Use half the oil to brown brinjal and zucchini in batches in a wide pan, about 5 minutes per batch. Transfer to a bowl.","Add the remaining oil, soften onion and capsicum for 8 minutes, then add garlic and thyme for 1 minute.","Add tomato, salt and pepper. Simmer uncovered for 10 minutes until the tomato breaks down.","Return brinjal and zucchini to the pan, cover loosely and simmer for 15–20 minutes until tender, stirring gently.","Uncover and reduce excess liquid if necessary. Finish with basil and serve hot or warm with bread or rice separately."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-tagine','{"id":"vegetable-tagine","name":"Vegetable Tagine","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked chickpeas","qty":400,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"carrot","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"pumpkin","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"zucchini","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"dried apricot","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut carrot, pumpkin and zucchini into chunky pieces, chop onion and tomato, and halve the dried apricots.","Heat oil in a heavy lidded saucepan and soften onion for 7 minutes. Add cumin, cinnamon and paprika for 20 seconds.","Add tomato, carrot, pumpkin, apricots, water and salt. Bring to a simmer, cover and cook on low heat for 20 minutes.","Add zucchini and drained cooked chickpeas. Cover and cook for another 12–15 minutes until the vegetables are tender.","Uncover and simmer briefly if the sauce is watery; stir carefully to keep the pumpkin pieces intact.","Turn off the heat, add lemon juice and coriander, and serve. Remove the cinnamon stick if used whole."],"tips":["Cut vegetables evenly and check tenderness before serving; add hot water gradually when adjusting thickness."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Tagine","src":"/photos/vegetable-tagine-1200.webp","small":"/photos/vegetable-tagine-600.webp","width":1200,"height":900,"alt":"Vegetable Tagine — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Vegetable_Tagine.jpg","title":"File:Vegetable Tagine.jpg","author":"Turajski","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3201,"sourceHeight":2400,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-sambar','{"id":"vegetable-sambar","name":"Vegetable Sambar","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":120,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"pumpkin","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"sambar powder","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse toor dal and simmer with 550 ml water and turmeric for 35–45 minutes until completely soft, topping up with boiling water if necessary. Mash gently.","Meanwhile, dice carrot, pumpkin and tomato. Simmer with the remaining 350 ml water for 12–15 minutes until tender.","Add tamarind paste and sambar powder to the vegetables and simmer for 5 minutes. Stir in cooked dal and salt and simmer for another 5–8 minutes.","Heat the oil separately, let mustard seeds pop, add curry leaves carefully, then pour the tempering into the sambar. Thin with hot water if needed.","Check that lentils and vegetables are fully soft and taste for salt and sourness.","Rest covered for 5 minutes and serve hot with a separately prepared accompaniment."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('idli-sambar','{"id":"idli-sambar","name":"Idli Sambar","baseServings":4,"batchSize":50,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":1450,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"toor dal","qty":120,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"pumpkin","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"sambar powder","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["For the idlis, reserve 550 ml of the listed water, 5 g salt and 15 ml oil. Keep the other 900 ml water, 4 g salt and 15 ml oil for the sambar. Water for soaking and steaming is additional.","Rinse rice and urad dal separately. Soak rice in plenty of water for 5 hours; soak urad with fenugreek for the same time, then drain both.","Grind urad with about 200 ml fresh measured water until light and fluffy. Grind rice separately with 250 ml water until fine but faintly grainy. Reserve the remaining water for consistency.","Mix both batters in a large bowl with room to rise. Cover loosely and ferment in a warm place for 8–12 hours, or until risen and pleasantly sour; refrigerate after fermentation if not cooking immediately.","Fold in salt gently. The batter should fall in thick ribbons; add reserved water a spoonful at a time only if needed.","Bring water to a boil in a steamer. Grease idli moulds with the measured oil, fill three-quarters full and steam covered for 12–15 minutes without opening early.","Check that a skewer comes out clean. Rest the moulds for 3 minutes, loosen idlis with a wet spoon and repeat with remaining batter.","Rinse toor dal and simmer with 550 ml water and turmeric for 35–45 minutes until completely soft, topping up with boiling water if necessary. Mash gently.","Meanwhile, dice carrot, pumpkin and tomato. Simmer with the remaining 350 ml water for 12–15 minutes until tender.","Add tamarind paste and sambar powder to the vegetables and simmer for 5 minutes. Stir in cooked dal and salt and simmer for another 5–8 minutes.","Heat the oil separately, let mustard seeds pop, add curry leaves carefully, then pour the tempering into the sambar. Thin with hot water if needed.","Serve warm idlis with the hot sambar. Start soaking and fermenting the batter the day before."],"tips":["Soaking and fermentation take about 13–17 hours in addition to cooking; fermentation depends on room temperature."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Idli Sambar","src":"/photos/idli-sambar-1200.webp","small":"/photos/idli-sambar-600.webp","width":1200,"height":800,"alt":"Idli Sambar — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Idli_Sambar(South_Indian).jpg","title":"File:Idli Sambar(South Indian).jpg","author":"Faruq Sayyed","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":6000,"sourceHeight":4000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kanchipuram-idli','{"id":"kanchipuram-idli","name":"Kanchipuram Idli","baseServings":4,"batchSize":50,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black pepper","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dry ginger powder","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9}],"steps":["Rinse rice and urad dal separately. Soak rice in plenty of water for 5 hours; soak urad with fenugreek for the same time, then drain both.","Grind urad with about 200 ml fresh measured water until light and fluffy. Grind rice separately with 250 ml water until fine but faintly grainy. Reserve the remaining water for consistency.","Mix both batters in a large bowl with room to rise. Cover loosely and ferment in a warm place for 8–12 hours, or until risen and pleasantly sour; refrigerate after fermentation if not cooking immediately.","Fold in salt gently. The batter should fall in thick ribbons; add reserved water a spoonful at a time only if needed.","Heat ghee, toast cashews until golden and add cumin, coarsely crushed pepper and curry leaves for 20 seconds. Cool slightly and fold into the batter with dry ginger powder.","Grease small heatproof bowls or idli moulds. Fill only three-quarters full and place above simmering water in a preheated steamer.","Steam for 15–20 minutes for small moulds, or 25–30 minutes for deeper bowls, until a skewer inserted in the centre comes out clean.","Rest for 5 minutes, loosen the edges and unmould. Serve warm; soaking and fermentation are additional."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kanchipuram Idli","src":"/photos/kanchipuram-idli-1200.webp","small":"/photos/kanchipuram-idli-600.webp","width":1200,"height":900,"alt":"Kanchipuram Idli served ready to eat","kind":"generated","title":"Kanchipuram Idli","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('uttapam','{"id":"uttapam","name":"Uttapam","baseServings":4,"batchSize":20,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse rice and urad dal separately. Soak rice in plenty of water for 5 hours; soak urad with fenugreek for the same time, then drain both.","Grind urad with about 200 ml fresh measured water until light and fluffy. Grind rice separately with 250 ml water until fine but faintly grainy. Reserve the remaining water for consistency.","Mix both batters in a large bowl with room to rise. Cover loosely and ferment in a warm place for 8–12 hours, or until risen and pleasantly sour; refrigerate after fermentation if not cooking immediately.","Fold in salt gently. The batter should fall in thick ribbons; add reserved water a spoonful at a time only if needed.","Finely chop onion, tomato and coriander and grate carrot. Heat a lightly oiled tawa over medium heat.","Pour a ladle of batter and spread gently into a thick 12 cm pancake. Scatter vegetables over the wet top and press lightly.","Drizzle oil around the edge, cover for 2–3 minutes, then flip carefully and cook the vegetable side for 2 minutes until the centre is set.","Repeat with remaining batter and serve hot. Lower the heat if the base browns before the thick centre cooks."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-appe','{"id":"vegetable-appe","name":"Vegetable Appe","baseServings":4,"batchSize":20,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse rice and urad dal separately. Soak rice in plenty of water for 5 hours; soak urad with fenugreek for the same time, then drain both.","Grind urad with about 200 ml fresh measured water until light and fluffy. Grind rice separately with 250 ml water until fine but faintly grainy. Reserve the remaining water for consistency.","Mix both batters in a large bowl with room to rise. Cover loosely and ferment in a warm place for 8–12 hours, or until risen and pleasantly sour; refrigerate after fermentation if not cooking immediately.","Fold in salt gently. The batter should fall in thick ribbons; add reserved water a spoonful at a time only if needed.","Finely chop onion and curry leaves and grate carrot. Heat half the oil, pop mustard seeds, soften onion and carrot for 3 minutes and cool.","Fold the cooled vegetables and coriander into the batter. Heat an appe pan over medium-low heat and grease each cavity lightly with remaining oil.","Fill cavities three-quarters full, cover and cook for 3–4 minutes until the bottoms are golden and the edges set.","Turn each appe with a skewer and cook uncovered for another 3 minutes. Break one open to check that no wet batter remains; repeat and serve hot."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-dosa','{"id":"masala-dosa","name":"Masala Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"potato","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["For the dosa batter and cooking, reserve 5 g salt and 15 ml oil. The remaining 4 g salt and 30 ml oil are for the potato filling. Water for soaking and boiling potatoes is additional.","Rinse rice and urad dal separately. Soak rice in plenty of water for 5 hours; soak urad with fenugreek for the same time, then drain both.","Grind urad with about 200 ml fresh measured water until light and fluffy. Grind rice separately with 250 ml water until fine but faintly grainy. Reserve the remaining water for consistency.","Mix both batters in a large bowl with room to rise. Cover loosely and ferment in a warm place for 8–12 hours, or until risen and pleasantly sour; refrigerate after fermentation if not cooking immediately.","Fold in salt gently. The batter should fall in thick ribbons; add reserved water a spoonful at a time only if needed.","Boil potatoes until tender, peel and roughly mash. Heat the extra 30 ml oil, pop mustard seeds, add curry leaves and sliced onion, and cook for 6 minutes.","Add turmeric, potatoes and the extra salt. Sprinkle in a little water and cook for 4–5 minutes to make a soft but dry filling; keep warm.","Thin the fermented batter slightly so it spreads easily. Heat a lightly oiled tawa over medium-high heat, pour a ladle in the centre and spread outwards in circles.","Drizzle a little of the batter recipe oil around the edge and cook for 2–3 minutes until the underside is golden and the top has no wet batter.","Place potato filling on one side, fold the dosa over it and serve immediately. Repeat, letting an overheated tawa cool slightly between dosas."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Masala Dosa","src":"/photos/masala-dosa-1200.webp","small":"/photos/masala-dosa-600.webp","width":900,"height":1200,"alt":"Masala Dosa — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Masala_Dosa_from_Kerala_3.jpg","title":"File:Masala Dosa from Kerala 3.jpg","author":"Ganesh Mohan T","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":12240,"sourceHeight":16320,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-idli','{"id":"rava-idli","name":"Rava Idli","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"curd","qty":280,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"plain fruit salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Heat oil, toast cashews until golden, pop mustard seeds and add chopped curry leaves. Add semolina and roast on medium-low heat for 4–5 minutes; cool completely.","Mix cooled semolina with curd, grated carrot, salt and most of the water. Rest for 20 minutes to hydrate.","Bring water to a boil in a steamer and grease idli moulds. Adjust the rested batter with reserved water to a thick spoonable consistency.","Just before steaming, fold fruit salt gently into the batter; do not beat out the bubbles. Fill moulds three-quarters full immediately.","Steam for 12–15 minutes until a skewer comes out clean. If cooking in batches, divide batter and fruit salt proportionally and activate each batch just before steaming.","Rest for 3 minutes, loosen with a wet spoon and serve warm."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rava Idli","src":"/photos/rava-idli-1200.webp","small":"/photos/rava-idli-600.webp","width":1200,"height":900,"alt":"Rava Idli — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Rava_Idli.jpg","title":"File:Rava Idli.jpg","author":"Amanrvet","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4000,"sourceHeight":3000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('khaman-dhokla','{"id":"khaman-dhokla","name":"Khaman Dhokla","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":240,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"plain fruit salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Whisk gram flour, water, curd, sugar, turmeric and salt into a smooth thick pouring batter. Rest for 15 minutes.","Grease a 20 cm shallow steaming tin with a little oil. Bring water to a boil in a steamer; the water must remain below the tin.","Fold fruit salt into the batter immediately before steaming. Transfer to the tin, filling no deeper than about 3 cm, and place in the hot steamer.","Steam covered for 18–22 minutes without opening during the first 15 minutes. A skewer inserted in the centre should come out clean.","Cool for 10 minutes and cut into squares. Heat remaining oil, pop mustard seeds and add curry leaves; take off the heat and carefully mix in lemon juice and 60 ml drinking water.","Spoon the tempering evenly over the cut dhokla and let it absorb for 5 minutes. Finish with chopped coriander and serve."],"tips":["For moong dal dhokla allow 4 hours soaking separately. Activate fruit salt only when the steamer is ready."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dhokla-bites','{"id":"dhokla-bites","name":"Dhokla Bites","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":240,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"plain fruit salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Whisk gram flour with water, curd, sugar, turmeric and salt until smooth. Rest for 15 minutes; the finished khaman will be cut into small bite-size cubes.","Grease a 20 cm shallow steaming tin with a little oil. Bring water to a boil in a steamer; the water must remain below the tin.","Fold fruit salt into the batter immediately before steaming. Transfer to the tin, filling no deeper than about 3 cm, and place in the hot steamer.","Steam covered for 18–22 minutes without opening during the first 15 minutes. A skewer inserted in the centre should come out clean.","Cool for 10 minutes and cut into squares. Heat remaining oil, pop mustard seeds and add curry leaves; take off the heat and carefully mix in lemon juice and 60 ml drinking water.","Spoon the tempering evenly over the cut dhokla and let it absorb for 5 minutes. Finish with chopped coriander and serve."],"tips":["For moong dal dhokla allow 4 hours soaking separately. Activate fruit salt only when the steamer is ready."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dhokla Bites","src":"/photos/dhokla-bites-1200.webp","small":"/photos/dhokla-bites-600.webp","width":1100,"height":429,"alt":"Dhokla Bites served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Khaman_dhokla_(cropped).jpg","title":"File:Khaman dhokla (cropped).jpg","author":"Vasantdave","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1100,"sourceHeight":429,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('moong-dal-dhokla','{"id":"moong-dal-dhokla","name":"Moong Dal Dhokla","baseServings":4,"batchSize":50,"ingredients":[{"name":"moong dal","qty":260,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"plain fruit salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak moong dal for 4 hours, drain and blend with the measured water until smooth. Mix in curd, sugar, turmeric and salt.","Grease a 20 cm shallow steaming tin with a little oil. Bring water to a boil in a steamer; the water must remain below the tin.","Fold fruit salt into the batter immediately before steaming. Transfer to the tin, filling no deeper than about 3 cm, and place in the hot steamer.","Steam covered for 18–22 minutes without opening during the first 15 minutes. A skewer inserted in the centre should come out clean.","Cool for 10 minutes and cut into squares. Heat remaining oil, pop mustard seeds and add curry leaves; take off the heat and carefully mix in lemon juice and 60 ml drinking water.","Spoon the tempering evenly over the cut dhokla and let it absorb for 5 minutes. Finish with chopped coriander and serve."],"tips":["For moong dal dhokla allow 4 hours soaking separately. Activate fruit salt only when the steamer is ready."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Moong Dal Dhokla","src":"/photos/moong-dal-dhokla-1200.webp","small":"/photos/moong-dal-dhokla-600.webp","width":1200,"height":900,"alt":"Moong Dal Dhokla served ready to eat","kind":"generated","title":"Moong Dal Dhokla","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('khandvi','{"id":"khandvi","name":"Khandvi","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":120,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"curd","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":360,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sesame seeds","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":4,"unit":"g","group":"Spices","scale":"linear"},{"name":"grated coconut","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Grease the backs of two large steel trays very lightly. Whisk gram flour, curd, water, turmeric and salt until completely smooth and strain out lumps.","Pour into a heavy non-stick pan and cook over medium-low heat, stirring and scraping continuously for 8–12 minutes as it thickens.","Spread a teaspoon on a tray, cool for a minute and try rolling it. If it tears or stays sticky, cook the batter for another minute and test again.","As soon as the test rolls cleanly, work quickly: spread the hot batter very thinly over the prepared trays with a flat spatula.","Cool for 8–10 minutes, cut into 4 cm strips and roll each strip gently from one end. Arrange seam-side down.","Heat oil, pop mustard seeds, add sesame and curry leaves briefly, then spoon over the rolls. Scatter coconut and coriander and serve."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Khandvi","src":"/photos/khandvi-1200.webp","small":"/photos/khandvi-600.webp","width":806,"height":1200,"alt":"Khandvi — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Khandvii.jpg","title":"File:Khandvii.jpg","author":"Devmanoj","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3592,"sourceHeight":5349,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-muthiya','{"id":"methi-muthiya","name":"Methi Muthiya","baseServings":4,"batchSize":50,"ingredients":[{"name":"fenugreek leaves","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"whole wheat flour","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"gram flour","qty":120,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sesame seeds","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash, dry and finely chop fenugreek leaves. Mix with flours, curd, half the oil, lemon juice, sugar, turmeric and salt.","Add water little by little only as needed to make a soft dough; the leaves release moisture as you mix.","With oiled hands shape four logs about 3 cm thick. Place on a greased tray in a preheated steamer.","Steam for 20–25 minutes until a skewer comes out clean. Cool for 10 minutes, then slice into 1.5 cm rounds.","Heat the remaining oil, pop mustard seeds and add sesame and curry leaves. Add sliced muthiya in a single layer.","Toss over medium heat for 5–7 minutes until lightly golden around the edges. Serve warm."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Methi Muthiya","src":"/photos/methi-muthiya-1200.webp","small":"/photos/methi-muthiya-600.webp","width":833,"height":1200,"alt":"Methi Muthiya — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Methi_Muthiya_(_fried_).jpg","title":"File:Methi Muthiya ( fried ).jpg","author":"Sushant savla","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":888,"sourceHeight":1280,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('patra','{"id":"patra","name":"Patra","baseServings":4,"batchSize":50,"ingredients":[{"name":"edible colocasia leaves","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"gram flour","qty":200,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"tamarind paste","qty":35,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sesame seeds","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use edible colocasia leaves sold for cooking. Wash, pat dry and carefully shave thick veins without tearing the leaves; never taste the leaves raw.","Dissolve tamarind and jaggery in water. Whisk with gram flour, cumin, turmeric and salt into a thick spreadable paste.","Place a large leaf vein-side up, spread paste thinly over it and layer another leaf on top. Repeat with 3–4 leaves, fold the sides inward and roll tightly from the broad end.","Make the remaining rolls and place seam-side down in a preheated steamer. Steam for 30–35 minutes until the centre is firm and fully cooked.","Cool completely before slicing into 1 cm rounds so the layers hold together.","Heat oil, pop mustard seeds and add sesame and curry leaves. Pan-toast the slices for 3–4 minutes per side and serve warm."],"tips":["Use a preheated steamer and check the centre for doneness before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sev-khamani','{"id":"sev-khamani","name":"Sev Khamani","baseServings":4,"batchSize":50,"ingredients":[{"name":"chana dal","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"plain fruit salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sesame seeds","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"pomegranate arils","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse chana dal and soak for 4–6 hours. Drain and grind with the measured water to a fine but slightly grainy paste.","Mix with curd, turmeric, sugar and salt. Prepare a greased shallow tray and a steamer with boiling water.","Fold in fruit salt, spread batter in the tray and steam for 20–25 minutes until a skewer comes out clean.","Cool for 10 minutes and crumble the cooked cake into coarse pieces.","Heat oil, pop mustard seeds and add sesame briefly. Toss in the crumbled cake, sprinkle with lemon juice and 60 ml water and stir for 3 minutes.","Serve topped with sev, pomegranate and coriander. Add sev at the last moment to keep it crisp."],"tips":["Allow 4–6 hours soaking in addition to cooking."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sev Khamani","src":"/photos/sev-khamani-1200.webp","small":"/photos/sev-khamani-600.webp","width":1200,"height":1004,"alt":"Sev Khamani — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sev_khamani.jpg","title":"File:Sev khamani.jpg","author":"Nilesh0355","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2905,"sourceHeight":2431,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rasgulla','{"id":"rasgulla","name":"Rasgulla","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":2000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"lemon juice","qty":50,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":400,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":1600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Bring the milk to a boil, turn off the heat and wait 1 minute. Add lemon juice diluted with an equal amount of water gradually, stirring until the curds separate from clear yellow-green whey.","Pour through muslin in a sieve. Rinse the curds briefly with cool drinking water to remove lemon flavour, gather the cloth and drain for 30–40 minutes. The chenna should be moist but not dripping.","Knead the drained chenna on a clean plate for 8–10 minutes until smooth, stopping before it becomes oily. Divide into 16 pieces and roll into smooth, crack-free balls.","Dissolve sugar in the measured water in a wide deep saucepan. Add lightly crushed cardamom and bring to a rolling boil.","Lower the balls gently into the boiling syrup, leaving room to double in size. Cover and boil steadily for 15–18 minutes; avoid crowding and cook in batches if necessary.","Add a little boiling water if the syrup becomes thick. A finished rasgulla springs back gently when pressed and should have no dense raw centre.","Turn off the heat, cool the rasgullas in their syrup and refrigerate for at least 3 hours before serving four per portion."],"tips":["Draining and chilling are additional. Use regular milk rather than UHT milk where possible for softer chenna."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rasgulla","src":"/photos/rasgulla-1200.webp","small":"/photos/rasgulla-600.webp","width":1200,"height":732,"alt":"Rasgulla — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Rasgulla_With_Rabdi.jpg","title":"File:Rasgulla With Rabdi.jpg","author":"Prakrutim","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3114,"sourceHeight":1900,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sandesh','{"id":"sandesh","name":"Sandesh","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":2000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"lemon juice","qty":50,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"powdered sugar","qty":110,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"pistachio","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Bring the milk to a boil, turn off the heat and wait 1 minute. Add lemon juice diluted with an equal amount of water gradually, stirring until the curds separate from clear yellow-green whey.","Pour through muslin in a sieve. Rinse the curds briefly with cool drinking water to remove lemon flavour, gather the cloth and drain for 30–40 minutes. The chenna should be moist but not dripping.","Knead the drained chenna for 6–8 minutes until smooth. Mix in powdered sugar and cardamom.","Transfer to a heavy non-stick pan and stir on very low heat for 5–7 minutes, just until the mixture gathers and loses excess moisture. Do not cook until dry or crumbly.","Cool until comfortably warm, then knead lightly and divide into 12 portions.","Press into small discs or moulds and garnish with chopped pistachio. Refrigerate until firm and serve chilled."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sandesh","src":"/photos/sandesh-1200.webp","small":"/photos/sandesh-600.webp","width":1200,"height":900,"alt":"Sandesh served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Gupo_Sandesh_Panihati_(2).jpg","title":"File:Gupo Sandesh Panihati (2).jpg","author":"Sumitsurai","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rasmalai','{"id":"rasmalai","name":"Rasmalai","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":2800,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"lemon juice","qty":50,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":350,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":1500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"almond","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"pistachio","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Set aside 800 ml milk for the sweetened milk sauce. Bring the remaining 2 litres to a boil, turn off heat for 1 minute, then add diluted lemon juice gradually until the curds separate.","Strain into muslin, rinse briefly and drain for 30–40 minutes until moist but not dripping. Knead for 8–10 minutes until smooth, divide into 12 balls and flatten gently into crack-free discs.","Boil 250 g sugar with the measured water in a wide pan. Add the discs with room to expand, cover and boil steadily for 15–18 minutes until spongy and cooked through.","In another pan, simmer the reserved 800 ml milk for 20 minutes, stirring, until reduced to about 600 ml. Add remaining sugar, saffron, cardamom and finely sliced nuts and simmer for 5 minutes.","Let the cooked discs cool slightly in syrup. Gently press each between spoons to remove excess syrup without breaking it, then place into warm sweetened milk.","Cool promptly and refrigerate for at least 4 hours to absorb the milk. Serve three small pieces per portion."],"tips":["Draining and chilling time are additional."],"substitutions":[],"status":"complete","prepTime":100,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mishti-doi','{"id":"mishti-doi","name":"Mishti Doi","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":1200,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":160,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"plain live-culture curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":30,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Simmer milk in a heavy pan for 25–30 minutes until reduced to about 900 ml, stirring frequently.","In a separate saucepan, heat sugar with the measured water. Let it turn amber without stirring vigorously; remove from heat before it darkens too far.","Carefully add a ladle of hot milk to the caramel because it will bubble, stir until dissolved, then mix into the remaining milk.","Cool the sweet milk to about 40–43°C: warm, not hot. Whisk the live-culture curd smooth and mix it into the milk.","Divide into four clean pots, cover and leave undisturbed in a warm place for 6–10 hours until set, depending on room temperature.","Refrigerate for at least 3 hours before serving. Use fresh starter curd and refrigerate as soon as the yoghurt sets."],"tips":["Allow 6–10 hours culturing plus chilling."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mishti Doi","src":"/photos/mishti-doi-1200.webp","small":"/photos/mishti-doi-600.webp","width":904,"height":733,"alt":"Mishti Doi — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Mishti_Doi.jpg","title":"File:Mishti Doi.jpg","author":"Kirti Poddar","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":904,"sourceHeight":733,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gulab-jamun','{"id":"gulab-jamun","name":"Gulab Jamun","baseServings":4,"batchSize":50,"ingredients":[{"name":"full-fat milk powder","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"plain flour","qty":40,"unit":"g","group":"Grains","scale":"linear"},{"name":"baking powder","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"milk","qty":90,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":350,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"rose water","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Simmer sugar, water and lightly crushed cardamom for 5 minutes until the sugar is dissolved and syrup is slightly sticky but not thick. Turn off heat and add food-grade rose water.","Mix milk powder, flour and baking powder. Rub in ghee, then add milk gradually to form a soft dough; do not knead heavily. Rest for 5 minutes.","Divide into 16 small portions and roll smoothly with greased palms. If cracks persist, work in a few drops of milk.","Heat oil in a deep, stable pan to about 150–160°C, keeping the pan less than half full. Fry a few balls at a time, moving gently, for 6–8 minutes until evenly deep golden.","Drain for 1 minute, then place in warm syrup. The syrup should not be boiling; keep the balls submerged gently.","Soak for at least 2 hours before serving. Four small jamuns make one generous dessert portion; frying oil is a working quantity, not the amount absorbed."],"tips":["Allow at least 2 hours soaking after cooking."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('malpua','{"id":"malpua","name":"Malpua","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"milk","qty":280,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":180,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"fennel seeds","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee for frying","qty":180,"unit":"g","group":"Packaged","scale":"linear"}],"steps":["Whisk flour, semolina, fennel and milk into a smooth pouring batter. Rest for 30 minutes, then stir and thin with a little milk if needed.","Simmer sugar and water for 5–6 minutes until lightly sticky. Add cardamom and keep the syrup warm off the heat.","Heat a shallow layer of ghee in a heavy pan over medium heat. Test a teaspoon of batter: it should spread gently and bubble at the edges.","Pour small ladlefuls to form 8–10 cm pancakes. Fry for 2–3 minutes per side until golden with crisp edges and a cooked centre.","Drain briefly, dip each pancake in warm syrup for 20–30 seconds, turn once and lift out.","Serve warm. Fry in small batches so pancakes do not overlap; the frying ghee quantity includes what remains in the pan."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Malpua","src":"/photos/malpua-1200.webp","small":"/photos/malpua-600.webp","width":1200,"height":900,"alt":"Malpua served ready to eat","kind":"generated","title":"Malpua","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jalebi','{"id":"jalebi","name":"Jalebi","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"cornflour starch","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"baking powder","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":300,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"lemon juice","qty":10,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["For this quick version, whisk flour, starch, curd, turmeric and 120 ml of the water to a smooth batter that flows in a thick continuous ribbon. Rest for 15 minutes.","Simmer sugar with the remaining 180 ml water and lemon juice until lightly sticky, about 6–8 minutes; add cardamom and keep warm.","Heat oil to about 170°C in a stable pan less than half full. Stir baking powder into the batter immediately before frying and transfer to a piping bag or food squeeze bottle.","Pipe small spirals close to the oil surface, working carefully to avoid splashes. Fry for 1–2 minutes per side until crisp, keeping them pale golden.","Drain briefly, dip into warm syrup for 20–30 seconds and lift onto a rack or plate.","Serve immediately for the crispest texture. This is an instant batter version; frying oil is a working quantity, not all consumed."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Jalebi","src":"/photos/jalebi-1200.webp","small":"/photos/jalebi-600.webp","width":1200,"height":902,"alt":"Jalebi — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Jalebi_2.jpg","title":"File:Jalebi 2.jpg","author":"Haroldandkumar at English Wikipedia","license":"Public domain","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2832,"sourceHeight":2128,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ghevar','{"id":"ghevar","name":"Ghevar","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":45,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"milk","qty":60,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"ice-cold water","qty":400,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":220,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water for syrup","qty":150,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon juice","qty":5,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"pistachio","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Beat cool ghee until creamy, then beat in milk and flour with ice-cold water gradually to make a very thin, smooth batter. Keep chilled while preparing the syrup.","Simmer sugar with syrup water and lemon juice for 6–8 minutes until lightly sticky. Add cardamom and keep warm.","Use a stable deep saucepan with a narrow 14–16 cm base and ample headroom. Add enough oil for about 4 cm depth but keep it below one-third of the pan height; heat to 175–180°C.","Pour a tablespoon of batter in a thin stream into the centre from a safe short distance. Wait for the vigorous bubbling to subside, then repeat several times, maintaining a small central opening with a skewer.","Build a lacy disc rather than a solid pancake. Cook until the edges are golden and the centre is firm; carefully lift with a skewer and slotted spoon and drain completely. Repeat for four small ghevar.","Spoon warm syrup over each drained ghevar and scatter pistachios. Let excess syrup drain and serve soon; the frying oil is not all consumed."],"tips":["This is an advanced frying recipe: use small batter additions and stop pouring whenever foaming approaches the top of the pan."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Ghevar","src":"/photos/ghevar-1200.webp","small":"/photos/ghevar-600.webp","width":1200,"height":800,"alt":"Ghevar — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Ghevar_-_Rajasthan%27s_melting_Magic.JPG","title":"File:Ghevar - Rajasthan''s melting Magic.JPG","author":"Su30solomon","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mohanthal','{"id":"mohanthal","name":"Mohanthal","baseServings":4,"batchSize":50,"ingredients":[{"name":"coarse gram flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"milk","qty":40,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":200,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":130,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"almond","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85}],"steps":["Rub 30 g of the ghee and the milk into gram flour to make damp coarse crumbs. Rest for 20 minutes, then rub through a coarse sieve.","Melt remaining ghee in a heavy pan, add the crumbs and roast over low heat for 20–25 minutes until deep golden and fragrant, stirring continuously.","In another pan, dissolve sugar in water and simmer to one-thread consistency: a cooled drop stretches into one fine thread between damp fingertips. Do not touch hot syrup.","Take the roasted flour off the heat, wait 2 minutes, then mix in warm syrup and cardamom carefully. Stir until the mixture thickens and holds together.","Spread into a lightly greased 18 cm square tin, level without pressing hard and scatter sliced almonds.","Let set for 3–4 hours, then cut into small squares. Portion as a rich sweet rather than a main dish."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mohanthal","src":"/photos/mohanthal-1200.webp","small":"/photos/mohanthal-600.webp","width":1200,"height":800,"alt":"Mohanthal — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Mohanthal1.jpg","title":"File:Mohanthal1.jpg","author":"Dkgohil","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mysore-pak','{"id":"mysore-pak","name":"Mysore Pak","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":150,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"sugar","qty":300,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":200,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Sift gram flour and dry-toast on low heat for 3 minutes without browning. Grease a small deep tray and keep it ready.","Warm ghee and oil together in a separate pan; keep hot but not smoking.","Dissolve sugar in water in a heavy pan and simmer to a light one-thread syrup, testing only a cooled drop.","Reduce heat and add sifted gram flour in portions, stirring vigorously to remove lumps.","Add the hot ghee mixture a small ladle at a time, stirring continuously. Cook for 8–12 minutes until the mixture becomes airy, porous and begins leaving the sides; stop before it turns dry and crumbly.","Pour promptly into the prepared tray without compressing the bubbles. Cool for 10 minutes, score pieces while warm and separate once fully set."],"tips":["Hot sugar and fat bubble strongly; use a deep heavy pan and add hot fat in small portions."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mysore Pak","src":"/photos/mysore-pak-1200.webp","small":"/photos/mysore-pak-600.webp","width":1200,"height":800,"alt":"Mysore Pak — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Mysore_pak.jpg","title":"File:Mysore pak.jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4368,"sourceHeight":2912,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('falooda','{"id":"falooda","name":"Falooda","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"rose syrup","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"basil seeds","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"falooda sev","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"eggless vanilla ice cream","qty":240,"unit":"g","group":"Dairy","scale":"linear"},{"name":"pistachio","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Soak basil seeds in 250 ml water for 20 minutes until each seed has a swollen translucent coating, then drain any excess.","Cook falooda sev in boiling water following the packet instructions, usually 3–5 minutes. Drain, rinse cool and drain again.","Chill milk, rose syrup, cooked sev and soaked seeds before assembling.","Spoon rose syrup into four tall glasses, then add seeds and cooked sev.","Pour milk slowly down the side of each glass and top with a scoop of eggless vanilla ice cream.","Scatter chopped pistachios and serve immediately with a spoon and wide straw."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Falooda","src":"/photos/falooda-1200.webp","small":"/photos/falooda-600.webp","width":988,"height":1200,"alt":"Falooda — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Rose_Falooda.jpg","title":"File:Rose Falooda.jpg","author":"Celestial Pari","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2755,"sourceHeight":3344,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fruit-trifle','{"id":"fruit-trifle","name":"Fruit Trifle","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless sponge cake","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"cornflour starch","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"sugar","qty":70,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"strawberry","qty":250,"unit":"g","group":"Fruits","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"whipping cream","qty":200,"unit":"ml","group":"Dairy","scale":"linear"}],"steps":["Whisk cornflour with 100 ml cold milk. Heat remaining milk with 50 g sugar, stir in slurry and simmer for 3 minutes until thick. Add vanilla and cool promptly, then chill.","Cut the eggless cake into cubes. Wash and hull strawberries and slice banana shortly before assembling.","Whip cold cream with remaining sugar to soft peaks.","Layer cake, fruit and cold custard in four glasses, repeating once if the glasses allow.","Spoon whipped cream on top, cover and refrigerate for 1–2 hours so the cake softens slightly.","Serve chilled. The layers in this version are eggless custard, cream, fruit and cake; no jelly is needed."],"tips":["Allow time to cool the custard and 1–2 hours chilling after assembly."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Fruit Trifle","src":"/photos/fruit-trifle-1200.webp","small":"/photos/fruit-trifle-600.webp","width":1200,"height":900,"alt":"Fruit Trifle served ready to eat","kind":"generated","title":"Fruit Trifle","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rice-pudding','{"id":"rice-pudding","name":"Rice Pudding","baseServings":4,"batchSize":50,"ingredients":[{"name":"short grain rice","qty":100,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":90,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"cinnamon powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse the rice and drain.","Use a heavy saucepan with plenty of room. Bring the measured milk just to a simmer, stirring the bottom so it does not catch.","Add rice to the hot milk and simmer very gently for 30–40 minutes, stirring often, until the grains are soft and the milk is creamy.","Add sugar, vanilla and cinnamon and simmer for 5 minutes.","Turn off the heat when slightly looser than your desired final texture; it thickens during cooling.","Serve warm, or cool promptly and refrigerate for a chilled dessert. Stir before portioning into four bowls."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('seviyan-kheer','{"id":"seviyan-kheer","name":"Seviyan Kheer","baseServings":4,"batchSize":50,"ingredients":[{"name":"wheat vermicelli","qty":90,"unit":"g","group":"Other","scale":"linear"},{"name":"milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":90,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cashew","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"raisins","qty":25,"unit":"g","group":"Other","scale":"linear"}],"steps":["Heat ghee, toast cashews and raisins briefly and set aside. Toast vermicelli in the same pan until lightly golden.","Use a heavy saucepan with plenty of room. Bring the measured milk just to a simmer, stirring the bottom so it does not catch.","Add the toasted vermicelli to hot milk and simmer for 8–12 minutes, stirring, until tender.","Stir in sugar and cardamom and simmer for 3 minutes; return toasted nuts and raisins.","Turn off the heat when slightly looser than your desired final texture; it thickens during cooling.","Serve warm, or cool promptly and refrigerate for a chilled dessert. Stir before portioning into four bowls."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('payasam','{"id":"payasam","name":"Payasam","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":90,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":100,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"raisins","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse rice and drain. Heat ghee separately and toast cashews and raisins until golden; reserve.","Use a heavy saucepan with plenty of room. Bring the measured milk just to a simmer, stirring the bottom so it does not catch.","Add rice to hot milk and simmer gently for 35–45 minutes until very soft, scraping the base and sides regularly.","Stir in sugar, cardamom and the toasted cashews and raisins; simmer for 5 minutes.","Turn off the heat when slightly looser than your desired final texture; it thickens during cooling.","Serve warm, or cool promptly and refrigerate for a chilled dessert. Stir before portioning into four bowls."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Payasam","src":"/photos/payasam-1200.webp","small":"/photos/payasam-600.webp","width":1200,"height":900,"alt":"Payasam — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Paal_payasam.JPG","title":"File:Paal payasam.JPG","author":"Ross thres","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1600,"sourceHeight":1200,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('basundi','{"id":"basundi","name":"Basundi","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":1500,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":100,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"almond","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"pistachio","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Slice almonds and pistachios finely. Soak saffron in a spoonful of warm milk taken from the measured amount.","Use a heavy saucepan with plenty of room. Bring the measured milk just to a simmer, stirring the bottom so it does not catch.","Simmer milk in a wide heavy pan for 40–50 minutes until reduced by about one-third, stirring and returning the thin cream layers from the sides to the milk.","Add sugar, cardamom, saffron milk and sliced nuts and simmer for 5 minutes.","Turn off the heat when slightly looser than your desired final texture; it thickens during cooling.","Serve warm, or cool promptly and refrigerate for a chilled dessert. Stir before portioning into four bowls."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Basundi","src":"/photos/basundi-1200.webp","small":"/photos/basundi-600.webp","width":1200,"height":900,"alt":"Basundi served ready to eat","kind":"generated","title":"Basundi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-payasam','{"id":"coconut-payasam","name":"Coconut Payasam","baseServings":4,"batchSize":50,"ingredients":[{"name":"grated coconut","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"jaggery","qty":150,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"rice flour","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"coconut oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Dissolve jaggery in 250 ml warm water and strain if gritty. Mix rice flour with the remaining 200 ml cool water.","Put grated coconut and strained jaggery liquid in a saucepan and simmer for 8 minutes.","Stir in the rice-flour slurry and simmer for 4–5 minutes, stirring continuously until lightly thickened.","Lower the heat, add coconut milk and cardamom and warm gently for 3 minutes without a hard boil.","Toast cashews in coconut oil until golden and pour over the payasam.","Serve warm in small bowls; the dessert becomes thicker as it cools."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Coconut Payasam","src":"/photos/coconut-payasam-1200.webp","small":"/photos/coconut-payasam-600.webp","width":1200,"height":900,"alt":"Coconut Payasam served ready to eat","kind":"generated","title":"Coconut Payasam","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gajar-halwa','{"id":"gajar-halwa","name":"Gajar Halwa","baseServings":4,"batchSize":50,"ingredients":[{"name":"carrot","qty":900,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ghee","qty":70,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"raisins","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash, peel and grate carrots using medium holes.","Measure all ingredients and use a long-handled spatula and a heavy pan; the mixture needs frequent stirring.","Put carrot and milk in a heavy pan. Simmer for 25–35 minutes, stirring, until the carrot is soft and most milk has evaporated.","Add ghee and cook for 8–10 minutes, then add sugar and cook another 8 minutes until the moisture released by the sugar evaporates.","Stir in cardamom and any listed cashews and raisins, reserving a few for garnish. Cook gently for another 2 minutes.","Rest for 5 minutes and portion into four small bowls. Serve warm; soak time, where required, is additional."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Gajar Halwa","src":"/photos/gajar-halwa-1200.webp","small":"/photos/gajar-halwa-600.webp","width":1200,"height":900,"alt":"Gajar Halwa served ready to eat","kind":"generated","title":"Gajar Halwa","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('badam-halwa','{"id":"badam-halwa","name":"Badam Halwa","baseServings":4,"batchSize":50,"ingredients":[{"name":"almond","qty":220,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"milk","qty":180,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":180,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ghee","qty":90,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Soak almonds in hot water for 1 hour, peel and blend with milk to a fine, slightly textured paste. Soak saffron in a spoonful of the milk first.","Measure all ingredients and use a long-handled spatula and a heavy pan; the mixture needs frequent stirring.","Heat half the ghee in a heavy pan, add almond paste and stir on low heat for 8–10 minutes until the raw aroma fades.","Add sugar and saffron milk. Cook for 10–15 minutes, stirring continuously and adding remaining ghee a little at a time until the mixture becomes glossy and leaves the sides.","Stir in cardamom and any listed cashews and raisins, reserving a few for garnish. Cook gently for another 2 minutes.","Rest for 5 minutes and portion into four small bowls. Serve warm; soak time, where required, is additional."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Badam Halwa","src":"/photos/badam-halwa-1200.webp","small":"/photos/badam-halwa-600.webp","width":1200,"height":900,"alt":"Badam Halwa served ready to eat","kind":"generated","title":"Badam Halwa","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('moong-dal-halwa','{"id":"moong-dal-halwa","name":"Moong Dal Halwa","baseServings":4,"batchSize":50,"ingredients":[{"name":"moong dal","qty":220,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"milk","qty":350,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"sugar","qty":180,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ghee","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cashew","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse and soak moong dal for 4 hours, drain extremely well and grind to a coarse paste using as little water as possible.","Measure all ingredients and use a long-handled spatula and a heavy pan; the mixture needs frequent stirring.","Heat ghee in a heavy non-stick pan, add dal paste and stir over medium-low heat for 25–35 minutes until golden, crumbly and nutty-smelling. Do not rush this roasting.","Heat milk and water separately. Add carefully to the hot roasted dal in small additions, stirring against splashes. Cook until absorbed, then add sugar and cook for 8–10 minutes until glossy.","Stir in cardamom and any listed cashews and raisins, reserving a few for garnish. Cook gently for another 2 minutes.","Rest for 5 minutes and portion into four small bowls. Serve warm; soak time, where required, is additional."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('besan-ladoo','{"id":"besan-ladoo","name":"Besan Ladoo","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":250,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"ghee","qty":120,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"powdered sugar","qty":160,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"almond","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85}],"steps":["Sift gram flour to remove lumps and chop almonds finely.","Melt ghee in a heavy pan on low heat. Add gram flour and stir continuously for 20–25 minutes until deeper golden and fragrant; keep the heat low so the inside does not remain raw.","Take off the heat and transfer to a bowl. Cool until just warm to the touch; hot flour will melt the sugar.","Mix in powdered sugar, cardamom and chopped almonds until evenly combined.","Squeeze a small portion firmly in your palm, then roll into a smooth ball. Make 12 small ladoos, about three per serving.","Let set at room temperature for 1 hour before storing in an airtight container."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Besan Ladoo","src":"/photos/besan-ladoo-1200.webp","small":"/photos/besan-ladoo-600.webp","width":1200,"height":900,"alt":"Besan Ladoo — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Pistachio_Besan_Ladoo.JPG","title":"File:Pistachio Besan Ladoo.JPG","author":"Saind147","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2816,"sourceHeight":2112,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-ladoo','{"id":"coconut-ladoo","name":"Coconut Ladoo","baseServings":4,"batchSize":50,"ingredients":[{"name":"desiccated coconut","qty":220,"unit":"g","group":"Other","scale":"linear"},{"name":"sweetened condensed milk","qty":250,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Reserve 30 g coconut for coating. Warm ghee in a non-stick pan over low heat.","Add the remaining coconut and stir for 1 minute without browning it.","Add condensed milk and milk and cook on low heat for 5–8 minutes, stirring constantly until the mixture holds together and leaves the sides.","Stir in cardamom, transfer to a plate and cool until safe to handle.","With lightly greased palms shape 12 small balls. Roll each in the reserved coconut.","Let firm up for 30 minutes. Refrigerate in an airtight container because this version contains milk."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Coconut Ladoo","src":"/photos/coconut-ladoo-1200.webp","small":"/photos/coconut-ladoo-600.webp","width":1200,"height":800,"alt":"Coconut Ladoo — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Coconut_ladoo_9-12-2026_(5_of_26).jpg","title":"File:Coconut ladoo 9-12-2026 (5 of 26).jpg","author":"Wheeler Cowperthwaite","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3888,"sourceHeight":2592,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kaju-katli','{"id":"kaju-katli","name":"Kaju Katli","baseServings":4,"batchSize":50,"ingredients":[{"name":"cashew","qty":250,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"sugar","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6}],"steps":["Pulse dry cashews in short bursts to a fine powder. Stop before they release oil; sieve out coarse pieces and pulse those separately.","Heat sugar and water in a non-stick pan, stirring only until dissolved. Simmer for 2–3 minutes to a light sticky syrup.","Lower the heat, add cashew powder and stir continuously for 6–8 minutes until it forms a soft mass leaving the sides.","Test a little cooled mixture: it should roll into a soft non-sticky ball. Stop cooking as soon as this happens to avoid a brittle katli.","Transfer to lightly greased parchment, cool until warm and knead gently with the ghee for 30 seconds. Roll between parchment sheets to about 4 mm thick.","While still slightly warm, cut into diamonds. Cool completely before separating and storing."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kaju Katli","src":"/photos/kaju-katli-1200.webp","small":"/photos/kaju-katli-600.webp","width":1200,"height":900,"alt":"Kaju Katli served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Kaju_katli_sweet.jpg","title":"File:Kaju katli sweet.jpg","author":"najeeb shaik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('shrikhand','{"id":"shrikhand","name":"Shrikhand","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain thick curd","qty":1000,"unit":"g","group":"Dairy","scale":"linear"},{"name":"powdered sugar","qty":120,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"milk","qty":20,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"pistachio","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Line a sieve with clean muslin, set over a bowl and add curd. Cover and drain in the refrigerator for 6–8 hours until thick; discard or separately save the whey.","Warm the milk slightly and steep saffron in it for 10 minutes.","Transfer drained curd to a bowl and whisk until smooth without adding water.","Fold in powdered sugar, cardamom and saffron milk. Taste and adjust sweetness if needed.","Chill for at least 1 hour so the flavours blend and the dessert firms up.","Divide into four bowls and scatter chopped pistachios on top."],"tips":["Allow 6–8 hours for draining and at least 1 hour chilling, in addition to preparation."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Shrikhand","src":"/photos/shrikhand-1200.webp","small":"/photos/shrikhand-600.webp","width":1200,"height":899,"alt":"Shrikhand — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Shrikhand.JPG","title":"File:Shrikhand.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4664,"sourceHeight":3496,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('agar-panna-cotta','{"id":"agar-panna-cotta","name":"Agar Panna Cotta","baseServings":4,"batchSize":50,"ingredients":[{"name":"cream","qty":400,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"milk","qty":300,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":90,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"agar agar powder","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"strawberry","qty":250,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Mix agar powder with the cold milk in a saucepan, whisking until evenly dispersed. Use powder rather than flakes; check the packet setting guidance as brands differ.","Bring the milk mixture to a full simmer while stirring, then simmer for 2 minutes to dissolve the agar completely.","Add cream and sugar, stir until dissolved and bring back just to a gentle simmer for 1 minute.","Take off the heat, add vanilla and pour promptly into four ramekins; agar begins setting as it cools.","Cool, cover and refrigerate for at least 3 hours. Wash and hull strawberries and mash half into a simple unsweetened sauce.","Serve in the ramekins or loosen carefully and unmould. Spoon strawberries and sauce over each portion."],"tips":["Setting and chilling take at least 3 hours. This version uses plant-derived agar."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Agar Panna Cotta","src":"/photos/agar-panna-cotta-1200.webp","small":"/photos/agar-panna-cotta-600.webp","width":1200,"height":900,"alt":"Agar Panna Cotta served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Panna_Cotta_with_cream_and_garnish.jpg","title":"File:Panna Cotta with cream and garnish.jpg","author":"hiro","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegan-chocolate-mousse','{"id":"vegan-chocolate-mousse","name":"Vegan Chocolate Mousse","baseServings":4,"batchSize":50,"ingredients":[{"name":"silken tofu","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"vegan dark chocolate","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"maple syrup","qty":45,"unit":"ml","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"cocoa powder","qty":15,"unit":"g","group":"Other","scale":"linear"}],"steps":["Drain silken tofu and let it lose its refrigerator chill for 10 minutes. Use silken tofu, not firm tofu, for a smooth texture.","Chop chocolate and melt gently in a heatproof bowl above barely simmering water, keeping the bowl clear of the water. Stir until smooth and cool slightly.","Blend tofu, maple syrup, vanilla and cocoa until completely smooth, scraping down the sides.","With the blender running slowly, add the melted chocolate and blend just until uniform. Taste and adjust sweetness if needed.","Divide between four dessert glasses, cover and refrigerate for at least 3 hours until set.","Serve chilled. Check chocolate is vegan and avoid adding dairy cream to this version."],"tips":["Allow at least 3 hours chilling after preparation."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegan Chocolate Mousse","src":"/photos/vegan-chocolate-mousse-1200.webp","small":"/photos/vegan-chocolate-mousse-600.webp","width":1200,"height":800,"alt":"Vegan Chocolate Mousse served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Chocolate_mousse_using_silken_tofu_and_soymilk_flickr_user_crystl.jpg","title":"File:Chocolate mousse using silken tofu and soymilk flickr user crystl.jpg","author":"Crystl","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mango-mousse','{"id":"mango-mousse","name":"Mango Mousse","baseServings":4,"batchSize":50,"ingredients":[{"name":"ripe mango flesh","qty":400,"unit":"g","group":"Fruits","scale":"linear"},{"name":"whipping cream","qty":300,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"powdered sugar","qty":50,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lime juice","qty":15,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Peel mango, remove the stone and weigh the flesh. Blend it completely smooth with lime juice.","Chill the mango puree and use cold whipping cream with enough fat to whip, following its label.","Whip cream and powdered sugar in a chilled bowl to soft peaks that gently curl over; avoid overbeating into butter.","Fold one-third of the whipped cream into the mango puree to lighten it, then gently fold in the rest.","Spoon into four glasses and refrigerate for at least 4 hours.","Serve in the glasses as a soft spoonable mousse. It has no setting agent and is not intended for unmoulding."],"tips":["Allow at least 4 hours chilling."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mango Mousse","src":"/photos/mango-mousse-1200.webp","small":"/photos/mango-mousse-600.webp","width":640,"height":480,"alt":"Mango Mousse served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Mango_mousse_by_rhosoi.jpg","title":"File:Mango mousse by rhosoi.jpg","author":"rhosoi","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":640,"sourceHeight":480,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fruit-custard-with-cornstarch','{"id":"fruit-custard-with-cornstarch","name":"Fruit Custard with Cornstarch","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":800,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"cornflour starch","qty":40,"unit":"g","group":"Grains","scale":"linear"},{"name":"sugar","qty":100,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"banana","qty":150,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"apple","qty":180,"unit":"g","group":"Fruits","scale":"linear"},{"name":"grapes","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"pomegranate arils","qty":100,"unit":"g","group":"Other","scale":"linear"}],"steps":["Mix cornflour starch with 150 ml cold milk until completely smooth.","Heat the remaining milk and sugar in a heavy saucepan until steaming. Stir in the starch mixture in a thin stream.","Bring to a gentle simmer and cook for 3–4 minutes, stirring continuously, until smooth and thick enough to coat a spoon.","Remove from heat, add vanilla and transfer to a clean bowl. Cool promptly, cover the surface and refrigerate until cold.","Wash fruit, core and dice apple, peel and slice banana and halve grapes. Fold the fruit and pomegranate into cold custard just before serving.","Divide into four bowls. Keep fruit and custard separately chilled if preparing ahead."],"tips":["Cooling and refrigeration are additional to cooking time."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Fruit Custard with Cornstarch","src":"/photos/fruit-custard-with-cornstarch-1200.webp","small":"/photos/fruit-custard-with-cornstarch-600.webp","width":1200,"height":900,"alt":"Fruit Custard with Cornstarch served ready to eat","kind":"generated","title":"Fruit Custard with Cornstarch","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cheesecake-cup','{"id":"cheesecake-cup","name":"Cheesecake Cup","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless digestive biscuits","qty":140,"unit":"g","group":"Other","scale":"linear"},{"name":"butter","qty":55,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cream cheese","qty":250,"unit":"g","group":"Dairy","scale":"linear"},{"name":"whipping cream","qty":200,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"powdered sugar","qty":70,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"strawberry","qty":200,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Crush biscuits finely and mix with melted butter. Divide between four glasses and press lightly into a base.","Beat cream cheese with sugar, lemon juice and vanilla until smooth and free of lumps.","In a separate chilled bowl, whip cold cream to soft peaks.","Fold whipped cream into the cream cheese mixture gently and spoon over the biscuit bases.","Cover and refrigerate for at least 4 hours. Wash, hull and slice strawberries.","Top with strawberries just before serving. This vegetarian, eggless cup dessert is spoonable and does not need baking or a setting agent."],"tips":["Allow at least 4 hours chilling."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Cheesecake Cup","src":"/photos/cheesecake-cup-1200.webp","small":"/photos/cheesecake-cup-600.webp","width":1200,"height":900,"alt":"Cheesecake Cup served ready to eat","kind":"generated","title":"Cheesecake Cup","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('brownie-sundae','{"id":"brownie-sundae","name":"Brownie Sundae","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless brownie","qty":320,"unit":"g","group":"Other","scale":"linear"},{"name":"eggless vanilla ice cream","qty":400,"unit":"g","group":"Dairy","scale":"linear"},{"name":"dark chocolate","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"milk","qty":60,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"almond","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85}],"steps":["Use ready-baked eggless brownies and ice cream labelled eggless. Cut the brownie into four portions.","Warm milk until steaming, take it off the heat and add finely chopped chocolate. Rest for 1 minute and stir into a smooth sauce.","Toast chopped almonds in a dry pan for 2–3 minutes and let cool.","Warm brownies briefly in an oven at 150°C for 5 minutes, or serve them at room temperature.","Place a brownie portion in each bowl, top with a scoop of ice cream and drizzle with chocolate sauce.","Scatter toasted almonds on top and serve immediately before the ice cream melts."],"tips":["Use gentle heat for milk and sugar mixtures, and scrape the base frequently to prevent scorching."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kulfi','{"id":"kulfi","name":"Kulfi","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":1200,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sweetened condensed milk","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"almond","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"pistachio","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Bring milk to a simmer in a heavy wide pan. Cook on low heat for 35–45 minutes, scraping the base and returning cream from the sides until reduced to about 750 ml.","Finely chop almonds and pistachios and steep saffron in a spoonful of the warm milk.","Add condensed milk, nuts, cardamom and saffron milk. Simmer for another 5 minutes, stirring.","Cool promptly, then refrigerate until cold. Stir the mixture so the nuts are evenly distributed.","Pour into four large kulfi moulds or smaller moulds as available, leaving expansion room, and freeze for at least 8 hours.","Dip moulds briefly in warm water to loosen and serve immediately."],"tips":["Cooling and at least 8 hours freezing are additional."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-hakka-noodles','{"id":"vegetable-hakka-noodles","name":"Vegetable Hakka Noodles","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless wheat noodles","qty":320,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":30,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"cabbage","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Boil noodles in plenty of water for the packet time, stopping while still slightly firm. Drain, rinse briefly and toss with 5 ml of the measured oil.","Cut carrot, cabbage and capsicum into thin strips. Slice spring onion, reserving green tops, and mince garlic and ginger.","Mix the listed sauces, vinegar, pepper or sugar in a small bowl before stir-frying.","Heat a large wok over medium-high heat. Add remaining oil, ginger, garlic and spring onion whites and stir for 30 seconds. Add carrot, cabbage and capsicum and toss for 3–4 minutes, keeping a slight crunch.","Add the prepared noodles or roti strips and the sauce mixture. Toss with two spatulas for 2–3 minutes until evenly coated and piping hot; work in batches if the pan is crowded.","Taste before adding salt because soy sauce is salty. Finish with spring onion greens and serve immediately."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-chow-mein','{"id":"vegetable-chow-mein","name":"Vegetable Chow Mein","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless wheat noodles","qty":320,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":30,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sesame oil","qty":10,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"cabbage","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Cook noodles just short of the packet time, drain very well and spread out for 5 minutes so excess steam escapes.","Cut carrot, cabbage and capsicum into thin strips. Slice spring onion, reserving green tops, and mince garlic and ginger.","Mix the listed sauces, vinegar, pepper or sugar in a small bowl before stir-frying.","Heat a large wok over medium-high heat. Add remaining oil, ginger, garlic and spring onion whites and stir for 30 seconds. Add carrot, cabbage and capsicum and toss for 3–4 minutes, keeping a slight crunch.","Add the prepared noodles or roti strips and the sauce mixture. Toss with two spatulas for 2–3 minutes until evenly coated and piping hot; work in batches if the pan is crowded.","Taste before adding salt because soy sauce is salty. Finish with spring onion greens and serve immediately."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Chow Mein","src":"/photos/vegetable-chow-mein-1200.webp","small":"/photos/vegetable-chow-mein-600.webp","width":1200,"height":798,"alt":"Vegetable Chow Mein — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Vegetable_Chow_Mein_-_Howrah_2014-03-23_9721.JPG","title":"File:Vegetable Chow Mein - Howrah 2014-03-23 9721.JPG","author":"Biswarup Ganguly","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":6016,"sourceHeight":4000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('roti-noodles','{"id":"roti-noodles","name":"Roti Noodles","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked roti","qty":450,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato ketchup","qty":35,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"rice vinegar","qty":15,"unit":"ml","group":"Grains","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"cabbage","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Stack fully cooked, safely refrigerated rotis and slice into thin strips. Separate the strips gently; do not boil them.","Cut carrot, cabbage and capsicum into thin strips. Slice spring onion, reserving green tops, and mince garlic and ginger.","Mix the listed sauces, vinegar, pepper or sugar in a small bowl before stir-frying.","Heat a large wok over medium-high heat. Add remaining oil, ginger, garlic and spring onion whites and stir for 30 seconds. Add carrot, cabbage and capsicum and toss for 3–4 minutes, keeping a slight crunch.","Add the prepared noodles or roti strips and the sauce mixture. Toss with two spatulas for 2–3 minutes until evenly coated and piping hot; work in batches if the pan is crowded.","Taste before adding salt because soy sauce is salty. Finish with spring onion greens and serve immediately."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sesame-tofu','{"id":"sesame-tofu","name":"Sesame Tofu","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"sesame seeds","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"maple syrup","qty":30,"unit":"ml","group":"Other","scale":"linear"},{"name":"cornflour starch","qty":15,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Drain tofu, wrap in a clean towel and press under a light plate for 15 minutes. Cut into 2 cm cubes; dice capsicum and slice spring onion.","Whisk soy sauce, vinegar, maple syrup, starch and water until smooth.","Heat half the oil in a wide non-stick pan and brown tofu for 8–10 minutes, turning gently. Transfer to a plate.","Add remaining oil, minced garlic, ginger and spring onion whites. Stir for 30 seconds, add capsicum and stir-fry for 3 minutes.","Pour sauce into the pan and stir for 2–3 minutes until glossy; fold in tofu and toasted sesame seeds.","Finish with spring onion greens and taste before adding any extra salt. Serve with separately prepared rice if desired."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sesame Tofu","src":"/photos/sesame-tofu-1200.webp","small":"/photos/sesame-tofu-600.webp","width":1200,"height":900,"alt":"Sesame Tofu served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Sesame_Tofu_(121493798).jpg","title":"File:Sesame Tofu (121493798).jpg","author":"Kari Sullivan from Austin, TX","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kung-pao-tofu','{"id":"kung-pao-tofu","name":"Kung Pao Tofu","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"roasted peanuts","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"dried red chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":25,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"cornflour starch","qty":15,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Drain tofu, wrap in a clean towel and press under a light plate for 15 minutes. Cut into 2 cm cubes; dice capsicum and slice spring onion.","Whisk soy sauce, vinegar, sugar, starch and water. Break dried chillies into pieces and shake out seeds for less heat.","Heat half the oil in a wide non-stick pan and brown tofu for 8–10 minutes, turning gently. Transfer to a plate.","Add remaining oil, minced garlic, ginger and spring onion whites. Stir for 30 seconds, add capsicum and stir-fry for 3 minutes.","Briefly stir-fry dried chillies with the vegetables, add sauce and simmer for 2–3 minutes until glossy. Return tofu and add peanuts.","Finish with spring onion greens and taste before adding any extra salt. Serve with separately prepared rice if desired."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kung Pao Tofu","src":"/photos/kung-pao-tofu-1200.webp","small":"/photos/kung-pao-tofu-600.webp","width":1200,"height":900,"alt":"Kung Pao Tofu served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Guilin_Chinese_Restaurant.jpg","title":"File:Guilin Chinese Restaurant.jpg","author":"https://www.flickr.com/photos/mlinksva/","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('thai-basil-tofu','{"id":"thai-basil-tofu","name":"Thai Basil Tofu","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"basil","qty":40,"unit":"g","group":"Spices","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"vegetarian mushroom stir-fry sauce","qty":30,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":70,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Drain tofu, wrap in a clean towel and press under a light plate for 15 minutes. Cut into 2 cm cubes; dice capsicum and slice spring onion.","Mix soy sauce, vegetarian mushroom sauce, sugar and water. Slice chilli finely and pick basil leaves.","Heat half the oil in a wide non-stick pan and brown tofu for 8–10 minutes, turning gently. Transfer to a plate.","Add remaining oil, minced garlic, ginger and spring onion whites. Stir for 30 seconds, add capsicum and stir-fry for 3 minutes.","Add chilli and sauce and bubble for 2 minutes; return tofu, toss, turn off the heat and fold in basil just until wilted.","Finish with spring onion greens and taste before adding any extra salt. Serve with separately prepared rice if desired."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-pad-thai','{"id":"vegetarian-pad-thai","name":"Vegetarian Pad Thai","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice noodles","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"firm tofu","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"bean sprouts","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"tamarind paste","qty":35,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":40,"unit":"ml","group":"Other","scale":"linear"},{"name":"jaggery","qty":35,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"roasted peanuts","qty":60,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"lime","qty":120,"unit":"g","group":"Other","scale":"linear"}],"steps":["Soak or cook rice noodles according to their packet until flexible but still firm, then drain. Press and cube tofu and slice spring onion.","Dissolve jaggery with water, tamarind and soy sauce in a small pan for 2 minutes, then set aside.","Heat half the oil and brown tofu for 8 minutes. Transfer to a plate; add remaining oil and minced garlic and stir for 30 seconds.","Add drained noodles and sauce and toss for 3–5 minutes until the noodles are tender and sauce mostly absorbed. Add a small splash of water if they remain firm.","Return tofu and add sprouts and spring onion. Toss for 3–4 minutes until sprouts are thoroughly cooked and everything is hot.","Serve with crushed peanuts and lime wedges. This recipe is eggless; check that every purchased sauce is labelled suitable for vegetarians."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-udon','{"id":"vegetable-udon","name":"Vegetable Udon","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless udon noodles","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"firm tofu","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"mushroom","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"bok choy","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":45,"unit":"ml","group":"Other","scale":"linear"},{"name":"sesame oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"dried shiitake","qty":15,"unit":"g","group":"Other","scale":"linear"}],"steps":["Soak dried shiitake in 300 ml hot water for 20 minutes. Slice rehydrated mushrooms and strain the soaking liquid through a fine sieve to remove grit.","Slice carrot thinly, quarter fresh mushrooms, separate bok choy stems and leaves and cube tofu.","Simmer ginger slices, shiitake, strained soaking liquid and remaining water for 10 minutes. Add soy sauce, carrot and fresh mushrooms for another 6–8 minutes.","Cook udon according to its packet in a separate pan, then drain and divide between four bowls.","Add tofu and bok choy stems to the broth for 3 minutes, then add the leaves for 2 minutes until wilted and tender.","Ladle broth and vegetables over noodles, drizzle sesame oil and add sliced spring onion. Use certified vegetarian broth ingredients and eggless noodles."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tofu-scramble','{"id":"tofu-scramble","name":"Tofu Scramble","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"spinach","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":60,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Drain tofu and crumble into bite-size pieces. Chop onion and tomato and wash and roughly chop spinach.","Heat oil in a wide skillet and soften onion for 6 minutes.","Add tomato, turmeric and cumin and cook for 4–5 minutes until pulpy.","Add crumbled tofu, salt, pepper and measured water. Cook for 5 minutes, stirring gently so some curds stay intact.","Fold in spinach and cook for 3–4 minutes until wilted and hot throughout.","Taste and serve while moist. Toast or roti can be prepared separately as an accompaniment."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tofu Scramble","src":"/photos/tofu-scramble-1200.webp","small":"/photos/tofu-scramble-600.webp","width":1200,"height":900,"alt":"Tofu Scramble — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Cinnamon_raisin_vegan_french_toast_and_curry_tofu_scramble_(3383908508).jpg","title":"File:Cinnamon raisin vegan french toast and curry tofu scramble (3383908508).jpg","author":"Kari Sullivan from Austin, TX","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4000,"sourceHeight":3000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tofu-fajitas','{"id":"tofu-fajitas","name":"Tofu Fajitas","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":400,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"lime juice","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Press tofu for 15 minutes and cut into thick strips. Slice capsicum and onion into similar strips.","Mix oil, lime juice, cumin, paprika and salt. Toss half with tofu and half with the vegetables.","Heat a large skillet and brown tofu for 8–10 minutes, turning gently; transfer to a warm plate.","Cook capsicum and onion in the same skillet for 6–8 minutes until lightly charred at the edges but still slightly crisp.","Warm tortillas briefly in a dry pan and keep wrapped in a cloth.","Divide tofu and vegetables among tortillas, add coriander and fold. Serve immediately."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Tofu Fajitas","src":"/photos/tofu-fajitas-1200.webp","small":"/photos/tofu-fajitas-600.webp","width":1200,"height":900,"alt":"Tofu Fajitas served ready to eat","kind":"generated","title":"Tofu Fajitas","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('black-bean-tacos','{"id":"black-bean-tacos","name":"Black Bean Tacos","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked black beans","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"corn tortillas","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"avocado flesh","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lime juice","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Drain and rinse cooked black beans. Finely chop onion and tomato, and slice avocado.","Reserve half the onion for salsa. Heat oil and soften the rest for 4 minutes, then stir in cumin and paprika for 20 seconds.","Add beans, water and half the salt. Simmer for 8 minutes, mashing a spoonful to bind the filling.","Mix tomato, reserved onion, coriander, lime juice and remaining salt into a fresh salsa.","Warm tortillas in a dry skillet for 20–30 seconds per side until flexible.","Fill with beans, salsa and avocado, then fold and serve promptly."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Black Bean Tacos","src":"/photos/black-bean-tacos-1200.webp","small":"/photos/black-bean-tacos-600.webp","width":1200,"height":800,"alt":"Black Bean Tacos served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Vegetables_and_Black_Bean_Tacos_(7212559656).jpg","title":"File:Vegetables and Black Bean Tacos (7212559656).jpg","author":"Jennifer from Vancouver, Canada","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pasta-arrabbiata','{"id":"pasta-arrabbiata","name":"Pasta Arrabbiata","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless penne","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":700,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"red chilli flakes","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"olive oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Bring a large saucepan of water to a boil and add half the salt. Measure the other ingredients and prepare the vegetables.","Warm oil over medium-low heat and cook sliced garlic and chilli flakes for 1 minute without browning. Add finely chopped tomato and half the salt and simmer for 18–20 minutes until thick.","Cook pasta for the packet time until tender with a slight bite. Reserve 200 ml pasta water before draining.","Add the cooked pasta or gnocchi to the sauce and toss gently over low heat for 1–2 minutes. Add a splash of cooking water if needed to make the sauce cling.","Turn off heat and add torn basil; add grated vegetarian hard cheese if listed.","Taste, divide among four bowls and serve hot. Choose cheese labelled suitable for vegetarians."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pasta Arrabbiata","src":"/photos/pasta-arrabbiata-1200.webp","small":"/photos/pasta-arrabbiata-600.webp","width":1200,"height":802,"alt":"Pasta Arrabbiata served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Pasta_all%C2%B4arrabbiata_(5864409158).jpg","title":"File:Pasta all´arrabbiata (5864409158).jpg","author":"Katrin Gilger","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":855,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pasta-primavera','{"id":"pasta-primavera","name":"Pasta Primavera","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless pasta","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"zucchini","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"capsicum","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"vegetarian hard cheese","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Bring a large saucepan of water to a boil and add half the salt. Measure the other ingredients and prepare the vegetables.","Cut vegetables into thin bite-size pieces. Heat oil, soften carrot for 3 minutes, then add garlic, zucchini, peas and capsicum for 5–6 minutes until tender-crisp. Add pepper and half the salt.","Cook pasta for the packet time until tender with a slight bite. Reserve 200 ml pasta water before draining.","Add the cooked pasta or gnocchi to the sauce and toss gently over low heat for 1–2 minutes. Add a splash of cooking water if needed to make the sauce cling.","Turn off heat and add lemon juice and grated vegetarian hard cheese.","Taste, divide among four bowls and serve hot. Choose cheese labelled suitable for vegetarians."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pasta Primavera","src":"/photos/pasta-primavera-1200.webp","small":"/photos/pasta-primavera-600.webp","width":1200,"height":900,"alt":"Pasta Primavera — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Pasta_primavera.jpg","title":"File:Pasta primavera.jpg","author":"Jeremy Keith","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1600,"sourceHeight":1200,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gnocchi-with-tomato-sauce','{"id":"gnocchi-with-tomato-sauce","name":"Gnocchi with Tomato Sauce","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless potato gnocchi","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":650,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"vegetarian hard cheese","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Bring a large saucepan of water to a boil and add half the salt. Measure the other ingredients and prepare the vegetables.","Check gnocchi is eggless. Heat oil, soften minced garlic for 30 seconds, add chopped tomato and half the salt, and simmer for 18–20 minutes until saucy.","Boil gnocchi according to its packet, usually until it floats plus 1 minute. Lift out gently with a slotted spoon.","Add the cooked pasta or gnocchi to the sauce and toss gently over low heat for 1–2 minutes. Add a splash of cooking water if needed to make the sauce cling.","Turn off heat and add torn basil; add grated vegetarian hard cheese if listed.","Taste, divide among four bowls and serve hot. Choose cheese labelled suitable for vegetarians."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Gnocchi with Tomato Sauce","src":"/photos/gnocchi-with-tomato-sauce-1200.webp","small":"/photos/gnocchi-with-tomato-sauce-600.webp","width":1200,"height":800,"alt":"Gnocchi with Tomato Sauce served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Gnocchi_al_Pomodoro_(2920979155).jpg","title":"File:Gnocchi al Pomodoro (2920979155).jpg","author":"Chi King","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-thai-green-curry','{"id":"vegetarian-thai-green-curry","name":"Vegetarian Thai Green Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"brinjal","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green beans","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coconut milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"vegetarian Thai green curry paste","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"soy sauce","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":12,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"basil","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"lime juice","qty":25,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Check that green curry paste is labelled suitable for vegetarians. Cube tofu and brinjal and trim beans into short lengths.","Heat oil in a saucepan and cook curry paste for 1–2 minutes over medium heat until fragrant.","Stir in 200 ml coconut milk and simmer for 3 minutes, then add remaining coconut milk and water.","Add brinjal and beans and simmer gently for 8 minutes. Add tofu and capsicum for another 6–8 minutes until vegetables are tender.","Season with soy sauce and sugar, tasting because curry pastes differ in salt and heat.","Turn off the heat, stir in basil and lime juice, and serve with separately cooked rice."],"tips":["Prepare and measure every component before heating the pan; serve promptly for the best texture."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-vanilla-cake','{"id":"eggless-vanilla-cake","name":"Eggless Vanilla Cake","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"sugar","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"milk","qty":220,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"vanilla extract","qty":8,"unit":"ml","group":"Other","scale":"linear"},{"name":"baking powder","qty":7,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat the oven to 180°C conventional heat. Grease and line a 20 cm round tin with baking parchment.","Sift flour, any cocoa or cinnamon, raising agents and salt together. Measure carefully; do not substitute baking soda and baking powder one-for-one.","Whisk milk with lemon juice and rest for 5 minutes, then whisk in sugar, oil and vanilla.","Add the dry mixture to the wet ingredients and fold gently until no dry flour remains. Avoid vigorous beating once flour is added.","Transfer immediately to the prepared tin and level. Bake for 30–35 minutes, checking the centre with a skewer. The skewer should come out clean and the centre should spring back lightly.","Cool in the tin for 15 minutes, then lift or turn out onto a rack. Cool fully before slicing; this makes four generous or eight smaller dessert portions."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Vanilla Cake","src":"/photos/eggless-vanilla-cake-1200.webp","small":"/photos/eggless-vanilla-cake-600.webp","width":1200,"height":900,"alt":"Eggless Vanilla Cake served ready to eat","kind":"generated","title":"Eggless Vanilla Cake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-chocolate-cake','{"id":"eggless-chocolate-cake","name":"Eggless Chocolate Cake","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":190,"unit":"g","group":"Grains","scale":"linear"},{"name":"cocoa powder","qty":35,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":170,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":80,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"vinegar","qty":15,"unit":"ml","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"baking soda","qty":5,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat the oven to 175°C conventional heat. Grease and line a 20 cm round tin with baking parchment.","Sift flour, any cocoa or cinnamon, raising agents and salt together. Measure carefully; do not substitute baking soda and baking powder one-for-one.","Whisk water, oil, vinegar and vanilla together. Mix sugar with the dry ingredients.","Add the dry mixture to the wet ingredients and fold gently until no dry flour remains. Avoid vigorous beating once flour is added.","Transfer immediately to the prepared tin and level. Bake for 30–35 minutes, checking the centre with a skewer. The skewer should come out clean and the centre should spring back lightly.","Cool in the tin for 15 minutes, then lift or turn out onto a rack. Cool fully before slicing; this makes four generous or eight smaller dessert portions."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Chocolate Cake","src":"/photos/eggless-chocolate-cake-1200.webp","small":"/photos/eggless-chocolate-cake-600.webp","width":768,"height":1024,"alt":"Eggless Chocolate Cake served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Chocolate_fudge_cake.jpg","title":"File:Chocolate fudge cake.jpg","author":"Tracy Hunter from Kabul,, Afghanistan","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":768,"sourceHeight":1024,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-banana-bread','{"id":"eggless-banana-bread","name":"Eggless Banana Bread","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":230,"unit":"g","group":"Grains","scale":"linear"},{"name":"ripe banana flesh","qty":320,"unit":"g","group":"Fruits","scale":"linear"},{"name":"sugar","qty":110,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"milk","qty":60,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"lemon juice","qty":10,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"baking powder","qty":6,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":2,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cinnamon powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat the oven to 175°C conventional heat. Grease and line a 22 × 12 cm loaf tin with baking parchment.","Sift flour, any cocoa or cinnamon, raising agents and salt together. Measure carefully; do not substitute baking soda and baking powder one-for-one.","Mash banana thoroughly, then whisk with sugar, oil, milk and lemon juice until combined.","Add the dry mixture to the wet ingredients and fold gently until no dry flour remains. Avoid vigorous beating once flour is added.","Transfer immediately to the prepared tin and level. Bake for 50–60 minutes, checking the centre with a skewer. The skewer should come out clean and the centre should spring back lightly.","Cool in the tin for 15 minutes, then lift or turn out onto a rack. Cool fully before slicing; this makes four generous or eight smaller dessert portions."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Banana Bread","src":"/photos/eggless-banana-bread-1200.webp","small":"/photos/eggless-banana-bread-600.webp","width":1200,"height":900,"alt":"Eggless Banana Bread served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Banana_bread_cut_into_slices.jpg","title":"File:Banana bread cut into slices.jpg","author":"Shisma","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-brownie','{"id":"eggless-brownie","name":"Eggless Brownie","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":130,"unit":"g","group":"Grains","scale":"linear"},{"name":"cocoa powder","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"dark chocolate","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"butter","qty":90,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":160,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"curd","qty":130,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"milk","qty":50,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"baking powder","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat the oven to 170°C conventional heat. Grease and line a 20 cm square tin with baking parchment.","Sift flour, any cocoa or cinnamon, raising agents and salt together. Measure carefully; do not substitute baking soda and baking powder one-for-one.","Melt butter and chocolate together gently and cool until warm. Whisk in sugar, room-temperature curd, milk and vanilla.","Add the dry mixture to the wet ingredients and fold gently until no dry flour remains. Avoid vigorous beating once flour is added.","Transfer immediately to the prepared tin and level. Bake for 25–30 minutes, checking the centre with a skewer. Moist crumbs are correct, but there should be no liquid batter.","Cool in the tin for 15 minutes, then lift or turn out onto a rack. Cool fully before slicing; this makes four generous or eight smaller dessert portions."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Brownie","src":"/photos/eggless-brownie-1200.webp","small":"/photos/eggless-brownie-600.webp","width":1200,"height":900,"alt":"Eggless Brownie served ready to eat","kind":"generated","title":"Eggless Brownie","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-oat-cookies','{"id":"eggless-oat-cookies","name":"Eggless Oat Cookies","baseServings":4,"batchSize":50,"ingredients":[{"name":"rolled oats","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain flour","qty":100,"unit":"g","group":"Grains","scale":"linear"},{"name":"butter","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"brown sugar","qty":100,"unit":"g","group":"Packaged","scale":"linear"},{"name":"milk","qty":35,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"baking powder","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat the oven to 175°C conventional heat and line two baking trays.","Beat softened butter and sugar together for 2 minutes until creamy, then mix in milk and vanilla.","Mix oats, flour, baking powder and salt in another bowl. Fold into the butter mixture to form a soft dough.","Divide into 16 balls and space well apart on the trays. Flatten each to about 1 cm thick.","Bake for 12–15 minutes until the edges are golden and the centres look set. Rotate the trays if the oven browns unevenly.","Leave on trays for 10 minutes to firm up, then cool on a rack. Serve four small cookies per portion."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('margherita-pizza','{"id":"margherita-pizza","name":"Margherita Pizza","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":360,"unit":"g","group":"Grains","scale":"linear"},{"name":"instant yeast","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":230,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"sugar","qty":5,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"tomato","qty":450,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"dried oregano","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"vegetarian mozzarella","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix flour, instant yeast, sugar and 4 g salt. Add lukewarm water and 15 ml oil, knead for 8 minutes and cover for 60–90 minutes until doubled.","Meanwhile heat remaining oil, soften minced garlic for 30 seconds, add chopped tomato, oregano and remaining salt, and simmer for 20 minutes until thick. Cool the sauce.","Preheat the oven and a heavy baking tray to 240°C for at least 20 minutes. Use mozzarella labelled suitable for vegetarians.","Divide dough into two balls and stretch each into a thin 26 cm round with a slightly thicker rim.","Spread a thin layer of sauce over the dough, leaving the edge clear, and scatter torn mozzarella evenly without overloading.","Transfer carefully to the hot tray and bake for 10–14 minutes until the crust is browned underneath and cheese bubbles. Finish with basil and serve hot."],"tips":["Allow 60–90 minutes dough rising in addition to preparation and baking."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Margherita Pizza","src":"/photos/margherita-pizza-1200.webp","small":"/photos/margherita-pizza-600.webp","width":1200,"height":900,"alt":"Margherita Pizza — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Margherita_Pizza_of_The_Point_Pizza_and_Point.jpg","title":"File:Margherita Pizza of The Point Pizza and Point.jpg","author":"Peachyeung316","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3712,"sourceHeight":2784,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mini-pizza','{"id":"mini-pizza","name":"Mini Pizza","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain flour","qty":360,"unit":"g","group":"Grains","scale":"linear"},{"name":"instant yeast","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":230,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"sugar","qty":5,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"tomato","qty":450,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"dried oregano","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"vegetarian mozzarella","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"basil","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix flour, instant yeast, sugar and 4 g salt. Add lukewarm water and 15 ml oil, knead for 8 minutes and cover for 60–90 minutes until doubled.","Meanwhile heat remaining oil, soften minced garlic for 30 seconds, add chopped tomato, oregano and remaining salt, and simmer for 20 minutes until thick. Cool the sauce.","Preheat the oven and a heavy baking tray to 240°C for at least 20 minutes. Use mozzarella labelled suitable for vegetarians.","Divide dough into eight balls and stretch each into a 10–12 cm round. Place on lightly floured baking parchment.","Spread a thin layer of sauce over the dough, leaving the edge clear, and scatter torn mozzarella evenly without overloading.","Transfer carefully to the hot tray and bake for 8–12 minutes until the crust is browned underneath and cheese bubbles. Finish with basil and serve hot."],"tips":["Allow 60–90 minutes dough rising in addition to preparation and baking."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mini Pizza","src":"/photos/mini-pizza-1200.webp","small":"/photos/mini-pizza-600.webp","width":1200,"height":900,"alt":"Mini Pizza served ready to eat","kind":"generated","title":"Mini Pizza","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-frittata-with-chickpea-flour','{"id":"vegetable-frittata-with-chickpea-flour","name":"Vegetable Frittata with Chickpea Flour","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"spinach","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"zucchini","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"baking powder","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Preheat oven to 190°C and grease a 22 cm shallow baking dish. Dice onion, capsicum and zucchini and chop washed spinach.","Heat 20 ml oil and soften onion, capsicum and zucchini for 7–8 minutes. Add spinach for 2 minutes, then cook off excess liquid.","Whisk gram flour, water, remaining oil, turmeric, salt and pepper until smooth. Rest for 10 minutes so the flour hydrates.","Whisk in baking powder, fold in the cooked vegetables and pour into the dish in an even layer.","Bake for 30–35 minutes until the centre is firm and a skewer comes out without wet batter. Cover loosely if the top browns early.","Rest for 10 minutes before cutting into wedges. This chickpea-flour version contains no eggs."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Frittata with Chickpea Flour","src":"/photos/vegetable-frittata-with-chickpea-flour-1200.webp","small":"/photos/vegetable-frittata-with-chickpea-flour-600.webp","width":1200,"height":800,"alt":"Vegetable Frittata with Chickpea Flour served ready to eat","kind":"generated","title":"Vegetable Frittata with Chickpea Flour","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1536,"sourceHeight":1024,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('stuffed-capsicum','{"id":"stuffed-capsicum","name":"Stuffed Capsicum","baseServings":4,"batchSize":50,"ingredients":[{"name":"capsicum","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cooked rice","qty":400,"unit":"g","group":"Grains","scale":"linear"},{"name":"cooked chickpeas","qty":300,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"tomato","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"vegetarian cheese","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Preheat oven to 190°C. Halve four large capsicums lengthwise, remove cores and seeds and place cut-side up in a baking dish.","Heat oil and soften chopped onion for 6 minutes. Add minced garlic and cumin for 30 seconds, then chopped tomatoes for 7–8 minutes.","Fold in cooked rice, drained cooked chickpeas, salt and pepper and heat through for 3 minutes.","Fill capsicum halves with the rice mixture and top with grated vegetarian cheese. Pour the measured water around, not over, the peppers.","Cover the dish with foil and bake for 25 minutes. Uncover and bake another 10–15 minutes until the peppers are tender and cheese is golden.","Rest for 5 minutes and serve two halves per portion."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gigantes-plaki','{"id":"gigantes-plaki","name":"Gigantes Plaki","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked butter beans","qty":850,"unit":"g","group":"Dairy","scale":"linear"},{"name":"tomato","qty":600,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"celery","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"dried oregano","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"parsley","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Preheat oven to 180°C. Drain fully cooked butter beans; if starting with dried beans, soak and cook separately until tender before measuring.","Dice onion, carrot and celery. Heat half the oil and soften for 8–10 minutes, then add minced garlic and oregano for 1 minute.","Add chopped tomatoes, water, salt and pepper and simmer for 12 minutes until slightly thickened.","Fold beans into the sauce and transfer to a baking dish. Drizzle remaining olive oil over the surface.","Bake uncovered for 35–45 minutes until the sauce thickens around the beans, stirring once gently if the edges dry out.","Rest for 10 minutes, scatter parsley and serve warm."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Gigantes Plaki","src":"/photos/gigantes-plaki-1200.webp","small":"/photos/gigantes-plaki-600.webp","width":1200,"height":900,"alt":"Gigantes Plaki served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Gigandes_plaki.jpg","title":"File:Gigandes plaki.jpg","author":"Hevesli","license":"Public domain","licenseUrl":"https://creativecommons.org/publicdomain/mark/1.0/","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('imam-bayildi','{"id":"imam-bayildi","name":"Imam Bayildi","baseServings":4,"batchSize":50,"ingredients":[{"name":"brinjal","qty":1000,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"parsley","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Preheat oven to 200°C. Halve four small-medium brinjals lengthwise and score the flesh without cutting through the skin.","Brush with 30 ml oil and half the salt. Roast cut-side up for 25 minutes until softened, then press the centres gently to form hollows.","Meanwhile heat remaining oil, soften thinly sliced onions for 15 minutes, add sliced garlic for 1 minute, then chopped tomatoes, sugar, remaining salt and pepper.","Simmer filling for 10 minutes until thick and fold in half the chopped parsley.","Fill brinjal halves, pour measured water around them, cover the dish and bake for 25 minutes until completely tender.","Uncover for a final 10 minutes if watery. Rest until warm and finish with remaining parsley."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Imam Bayildi","src":"/photos/imam-bayildi-1200.webp","small":"/photos/imam-bayildi-600.webp","width":1200,"height":900,"alt":"Imam Bayildi served ready to eat","kind":"generated","title":"Imam Bayildi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-enchiladas','{"id":"vegetarian-enchiladas","name":"Vegetarian Enchiladas","baseServings":4,"batchSize":50,"ingredients":[{"name":"corn tortillas","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cooked black beans","qty":600,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sweet corn","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"capsicum","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":650,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"vegetarian cheese","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat oven to 190°C. For sauce, heat half the oil, cook minced garlic for 30 seconds, add chopped tomatoes, water, half the cumin, paprika and salt, and simmer for 15 minutes. Blend smooth if desired.","Heat remaining oil and soften diced onion and capsicum for 6 minutes. Add drained beans, corn and the remaining seasonings and cook for 5 minutes.","Warm tortillas briefly in a dry skillet so they bend without cracking. Spread a thin layer of sauce in a baking dish.","Divide bean filling among tortillas, roll and arrange seam-side down in the dish.","Cover with remaining sauce and grated vegetarian cheese. Bake for 20–25 minutes until hot throughout and bubbling at the edges.","Rest for 5 minutes before lifting out portions with a wide spatula."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-lasagna','{"id":"vegetarian-lasagna","name":"Vegetarian Lasagna","baseServings":4,"batchSize":50,"ingredients":[{"name":"eggless lasagna sheets","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":800,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"mushroom","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"spinach","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"milk","qty":700,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"butter","qty":50,"unit":"g","group":"Dairy","scale":"linear"},{"name":"plain flour","qty":50,"unit":"g","group":"Grains","scale":"linear"},{"name":"vegetarian mozzarella","qty":220,"unit":"g","group":"Other","scale":"linear"},{"name":"dried oregano","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Preheat oven to 190°C. Cook or soak lasagna sheets only if their packet requires it. Slice mushrooms and chop washed spinach, onion and garlic.","Heat oil and soften onion for 6 minutes. Add garlic and mushrooms and cook for 8 minutes until excess moisture evaporates. Add tomato, oregano, half the salt and pepper and simmer for 20 minutes; wilt spinach into the sauce.","For white sauce, melt butter, stir in flour and cook for 2 minutes. Gradually whisk in milk and simmer for 5 minutes until smooth and thick; add remaining salt and pepper.","Spread a little vegetable sauce in a 20 × 28 cm baking dish. Layer sheets, vegetable sauce, white sauce and cheese; repeat, finishing with white sauce and cheese.","Cover with foil and bake for 30 minutes, then uncover for 15 minutes until bubbling and golden. A knife should pass easily through the pasta.","Rest for 15 minutes before slicing into four generous portions."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":90,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetarian Lasagna","src":"/photos/vegetarian-lasagna-1200.webp","small":"/photos/vegetarian-lasagna-600.webp","width":1200,"height":800,"alt":"Vegetarian Lasagna served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Vegetarian-lasagna_.jpg","title":"File:Vegetarian-lasagna .jpg","author":"FloGalsen","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-shepherd-s-pie','{"id":"vegetarian-shepherd-s-pie","name":"Vegetarian Shepherd''s Pie","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked brown lentils","qty":700,"unit":"g","group":"Pulses","scale":"linear"},{"name":"potato","qty":900,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato paste","qty":50,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"butter","qty":40,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":150,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"plain flour","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"dried thyme","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Peel and cube potatoes, boil for 18–20 minutes until very tender and drain. Mash with butter, warm milk and half the salt and pepper.","Preheat oven to 200°C. Heat oil and soften chopped onion and diced carrot for 8 minutes. Add garlic and thyme for 1 minute.","Stir in tomato paste and flour for 1 minute, gradually add water and simmer for 5 minutes.","Add cooked lentils, peas and remaining seasoning. Simmer for 8 minutes until thick, then spread in a baking dish.","Spoon mashed potato over the filling, spread to the edges and roughen with a fork.","Bake for 25–30 minutes until the top is golden and filling bubbles at the edges. Rest for 10 minutes before serving."],"tips":["Preheat fully, use the stated tin size and begin checking at the earlier time because ovens vary."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gatte-ki-sabzi','{"id":"gatte-ki-sabzi","name":"Gatte ki Sabzi","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix gram flour with 100 g curd, 20 ml oil, half the salt and half the cumin. Knead gently into a firm smooth dough, adding a spoonful of water only if needed.","Divide dough into four portions and roll into smooth logs about 2 cm thick.","Bring a deep saucepan of water to a boil. Lower in the dough pieces and simmer for 12–15 minutes until firm and cooked through. Lift out and cool; cut plain logs into 1 cm slices.","Whisk remaining curd with coriander powder, turmeric, chilli powder and measured water until smooth.","Heat remaining oil, sizzle remaining cumin, reduce heat and pour in the curd mixture gradually while stirring. Bring to a gentle simmer, continuing to stir so it does not split.","Add cooked gatta and remaining salt and simmer gently for 10 minutes. Finish with coriander and adjust with a little hot water if too thick."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Gatte ki Sabzi","src":"/photos/gatte-ki-sabzi-1200.webp","small":"/photos/gatte-ki-sabzi-600.webp","width":1200,"height":1599,"alt":"Gatte ki Sabzi served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Besan_Gatta_curry03.jpg","title":"File:Besan Gatta curry03.jpg","author":"EAT&ART TARO","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1706,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('govind-gatta-curry','{"id":"govind-gatta-curry","name":"Govind Gatta Curry","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"paneer","qty":120,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"raisins","qty":25,"unit":"g","group":"Other","scale":"linear"}],"steps":["Mix gram flour with 100 g curd, 20 ml oil, half the salt and half the cumin. Knead gently into a firm smooth dough, adding a spoonful of water only if needed.","Crumble paneer and chop raisins. Divide dough into 12 portions, flatten each, fill with a little paneer and raisins and seal into smooth oval dumplings.","Bring a deep saucepan of water to a boil. Lower in the dough pieces and simmer for 12–15 minutes until firm and cooked through. Lift out and cool; cut plain logs into 1 cm slices.","Whisk remaining curd with coriander powder, turmeric, chilli powder and measured water until smooth.","Heat remaining oil, sizzle remaining cumin, reduce heat and pour in the curd mixture gradually while stirring. Bring to a gentle simmer, continuing to stir so it does not split.","Add cooked gatta and remaining salt and simmer gently for 10 minutes. Finish with coriander and adjust with a little hot water if too thick."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Govind Gatta Curry","src":"/photos/govind-gatta-curry-1200.webp","small":"/photos/govind-gatta-curry-600.webp","width":1200,"height":900,"alt":"Govind Gatta Curry served ready to eat","kind":"generated","title":"Govind Gatta Curry","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('doi-begun','{"id":"doi-begun","name":"Doi Begun","baseServings":4,"batchSize":50,"ingredients":[{"name":"brinjal","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"curd","qty":350,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"mustard oil","qty":45,"unit":"ml","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cut brinjal into thick slices and pat dry. Rub with half the turmeric and salt.","Pan-fry brinjal in most of the oil for 5–6 minutes per side until golden and tender; remove to a plate.","Whisk curd with measured water and the listed ground spices until completely smooth.","Add cumin and any listed whole spices to the remaining oil over medium heat. Lower heat and add the curd mixture gradually, stirring continuously until gently simmering.","Add the remaining salt and sugar if listed. Simmer gently for 5 minutes, stirring the base; do not let the yoghurt sauce boil vigorously.","Return the fried brinjal to the sauce and simmer very gently for 5 minutes without breaking the slices."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kashmiri-dum-aloo','{"id":"kashmiri-dum-aloo","name":"Kashmiri Dum Aloo","baseServings":4,"batchSize":50,"ingredients":[{"name":"small potatoes","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"curd","qty":350,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"mustard oil","qty":45,"unit":"ml","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fennel powder","qty":6,"unit":"g","group":"Other","scale":"linear"},{"name":"dry ginger powder","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"Kashmiri chilli powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Boil small potatoes until just tender, about 15–20 minutes, then peel and prick all over with a fork.","Pan-fry potatoes in most of the oil for 10–12 minutes, turning until golden; lift out.","Whisk curd with measured water and the listed ground spices until completely smooth.","Add cumin and any listed whole spices to the remaining oil over medium heat. Lower heat and add the curd mixture gradually, stirring continuously until gently simmering.","Add the remaining salt and sugar if listed. Simmer gently for 5 minutes, stirring the base; do not let the yoghurt sauce boil vigorously.","Return potatoes to the sauce, cover and simmer over low heat for 20 minutes, turning occasionally until the sauce clings."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kashmiri Dum Aloo","src":"/photos/kashmiri-dum-aloo-1200.webp","small":"/photos/kashmiri-dum-aloo-600.webp","width":1200,"height":900,"alt":"Kashmiri Dum Aloo — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Kashmiri_Dum_aloo.jpeg","title":"File:Kashmiri Dum aloo.jpeg","author":"Maskaravivek","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4032,"sourceHeight":3024,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('papad-ki-sabzi','{"id":"papad-ki-sabzi","name":"Papad ki Sabzi","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain vegetarian papad","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":300,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Roast papad in a dry pan or microwave according to its packet until crisp. Break into large pieces and set aside.","Heat the oil in a saucepan and keep the papad separate until the gravy is ready.","Whisk curd with measured water and the listed ground spices until completely smooth.","Add cumin and any listed whole spices to the remaining oil over medium heat. Lower heat and add the curd mixture gradually, stirring continuously until gently simmering.","Add the remaining salt and sugar if listed. Simmer gently for 5 minutes, stirring the base; do not let the yoghurt sauce boil vigorously.","Add roasted papad to the sauce only for the last 2 minutes; it softens very quickly, so serve immediately."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('malai-kofta','{"id":"malai-kofta","name":"Malai Kofta","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":250,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"boiled potato","qty":300,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cornflour starch","qty":45,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cream","qty":70,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Grate paneer and mash peeled boiled potato completely. Mix with cornflour and 2 g salt, divide into 12 portions and shape into smooth balls.","Soak cashews in hot water for 20 minutes, then blend with 100 ml measured water. Chop onion and tomato and mince ginger and garlic.","Heat frying oil to about 170°C in a stable pan less than half full. Fry one test kofta; if it breaks, add a little more binding flour to the mixture. Fry the rest in small batches for 4–6 minutes until golden and cooked through, then drain.","For gravy, heat 25 ml oil, sizzle cumin and soften onion for 7 minutes. Add ginger and garlic for 1 minute, then tomato, coriander powder and turmeric; cook for 10 minutes until thick.","Cool slightly and blend the masala with cashew paste until smooth. Return to the pan, add remaining measured water and salt and simmer for 8 minutes.","Lower heat and add cream and garam masala. Warm for 2 minutes, then place koftas in serving bowls and spoon gravy over them just before serving so they do not disintegrate."],"tips":["Frying oil is the amount needed in the pan, not the amount absorbed. Add delicate koftas only when ready to serve."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Malai Kofta","src":"/photos/malai-kofta-1200.webp","small":"/photos/malai-kofta-600.webp","width":1200,"height":900,"alt":"Malai Kofta served ready to eat","kind":"generated","title":"Malai Kofta","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lauki-kofta','{"id":"lauki-kofta","name":"Lauki Kofta","baseServings":4,"batchSize":50,"ingredients":[{"name":"bottle gourd","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"gram flour","qty":100,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cream","qty":70,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Peel and grate bottle gourd, discarding it if bitter. Squeeze out excess liquid well and mix the flesh with gram flour and 2 g salt just before frying; shape small balls using damp hands.","Soak cashews in hot water for 20 minutes, then blend with 100 ml measured water. Chop onion and tomato and mince ginger and garlic.","Heat frying oil to about 170°C in a stable pan less than half full. Fry one test kofta; if it breaks, add a little more binding flour to the mixture. Fry the rest in small batches for 4–6 minutes until golden and cooked through, then drain.","For gravy, heat 25 ml oil, sizzle cumin and soften onion for 7 minutes. Add ginger and garlic for 1 minute, then tomato, coriander powder and turmeric; cook for 10 minutes until thick.","Cool slightly and blend the masala with cashew paste until smooth. Return to the pan, add remaining measured water and salt and simmer for 8 minutes.","Lower heat and add cream and garam masala. Warm for 2 minutes, then place koftas in serving bowls and spoon gravy over them just before serving so they do not disintegrate."],"tips":["Frying oil is the amount needed in the pan, not the amount absorbed. Add delicate koftas only when ready to serve."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Lauki Kofta","src":"/photos/lauki-kofta-1200.webp","small":"/photos/lauki-kofta-600.webp","width":1200,"height":800,"alt":"Lauki Kofta — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Lauki_Kofta.JPG","title":"File:Lauki Kofta.JPG","author":"Ravi Talwar","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3456,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sev-tamatar','{"id":"sev-tamatar","name":"Sev Tamatar","baseServings":4,"batchSize":50,"ingredients":[{"name":"tomato","qty":800,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"thick gram-flour sev","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"jaggery","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash and chop tomatoes into small pieces. Keep sev dry and separate until serving.","Heat oil, let mustard seeds pop and add cumin for 20 seconds.","Add tomato, turmeric, coriander powder, chilli and salt. Cook for 8–10 minutes until pulpy.","Add jaggery and water and simmer for 5 minutes to make a slightly loose sweet-sour gravy.","Taste and adjust seasoning, then add sev for only 30–60 seconds so it softens slightly without dissolving.","Finish with coriander and serve immediately. For later serving, store the gravy and sev separately."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sev Tamatar","src":"/photos/sev-tamatar-1200.webp","small":"/photos/sev-tamatar-600.webp","width":1200,"height":673,"alt":"Sev Tamatar — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sev_Tameta_Nu_Shaak.jpg","title":"File:Sev Tameta Nu Shaak.jpg","author":"UserWiki","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4224,"sourceHeight":2368,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-kurma','{"id":"vegetable-kurma","name":"Vegetable Kurma","baseServings":4,"batchSize":50,"ingredients":[{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"cauliflower","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"coconut","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"cashew","qty":35,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"fennel seeds","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut vegetables into even bite-size pieces. Soak cashews for 15 minutes, then blend with coconut, fennel and 150 ml measured water into a fine paste.","Heat oil, add cinnamon and lightly crushed cardamom, then soften chopped onion for 6 minutes. Add minced ginger and garlic for 1 minute.","Add chopped tomato and turmeric and cook for 5 minutes until pulpy.","Add potato, carrot, beans, cauliflower, salt and remaining water. Cover and simmer for 12–15 minutes until nearly tender.","Add peas and coconut-cashew paste and simmer gently for 8–10 minutes, stirring the base, until all vegetables are tender.","Adjust thickness with hot water, finish with coriander and remove whole spices before serving."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pav-bhaji','{"id":"pav-bhaji","name":"Pav Bhaji","baseServings":4,"batchSize":50,"ingredients":[{"name":"potato","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cauliflower","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":400,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"butter","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"pav bhaji masala","qty":18,"unit":"g","group":"Bakery","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"Kashmiri chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"lemon","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Peel and dice potatoes and cut cauliflower into florets. Simmer with peas and 400 ml water for 18–20 minutes until very soft, then mash with the cooking liquid.","Reserve 50 g finely chopped onion for serving. Melt 40 g butter and soften remaining onion for 7 minutes; add minced ginger and garlic for 1 minute.","Add finely chopped capsicum and tomato, turmeric, chilli and pav bhaji masala. Cook for 10 minutes until the vegetables soften into a thick base.","Add mashed vegetables, salt and remaining water. Mash together and simmer for 10–15 minutes, stirring until thick but spoonable.","Split pav and toast the cut sides in the remaining butter on a tawa until golden.","Serve bhaji with warm pav, reserved onion, coriander and lemon wedges. This is a lunch, dinner or street-food meal."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pav Bhaji","src":"/photos/pav-bhaji-1200.webp","small":"/photos/pav-bhaji-600.webp","width":1200,"height":900,"alt":"Pav Bhaji — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Pav_bhaji.jpg","title":"File:Pav bhaji.jpg","author":"Dforest","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2816,"sourceHeight":2112,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rajasthani-kadhi','{"id":"rajasthani-kadhi","name":"Rajasthani Kadhi","baseServings":4,"batchSize":50,"ingredients":[{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"gram flour","qty":70,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fenugreek seeds","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"dried red chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Whisk curd, gram flour, water, turmeric and salt until smooth with no flour lumps.","Heat half the ghee in a deep pan, sizzle cumin and fenugreek briefly, then lower the heat.","Pour in the curd mixture gradually while stirring. Bring to a gentle boil, stirring continuously so the flour does not settle.","Reduce heat and simmer for 25–30 minutes, stirring often, until the gram flour is cooked and the kadhi is smooth and pourable.","Heat remaining ghee, add dried chilli, turn off the heat and stir in chilli powder briefly. Pour this tempering over the kadhi.","Finish with coriander and serve hot. Add boiling water if it thickens excessively during simmering."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sindhi-kadhi','{"id":"sindhi-kadhi","name":"Sindhi Kadhi","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":100,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"okra","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"potato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":45,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fenugreek seeds","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cut potato and carrot into chunks and trim beans. Wash okra, dry completely and cut into short pieces.","Heat 20 ml oil and pan-fry okra for 8 minutes until nearly tender; reserve. In a deep pot heat remaining oil and add cumin, mustard, fenugreek and curry leaves.","Add gram flour and roast over low heat for 8–10 minutes, stirring until golden and nutty. Whisk in measured water gradually to avoid lumps.","Add turmeric, salt, potato, carrot, beans and chopped tomato. Bring to a simmer and cook for 20–25 minutes until the vegetables are tender.","Add tamarind and reserved okra and simmer for another 8 minutes, stirring the base regularly.","Taste for sourness and salt, adjust consistency with hot water and serve hot."],"tips":["Simmer gently, stir the base regularly and check the main ingredient is tender before finishing the gravy."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sindhi Kadhi","src":"/photos/sindhi-kadhi-1200.webp","small":"/photos/sindhi-kadhi-600.webp","width":1200,"height":900,"alt":"Sindhi Kadhi — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Sindhi_Kadhi.JPG","title":"File:Sindhi Kadhi.JPG","author":"Miansari66","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2816,"sourceHeight":2112,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jowar-roti-with-mixed-sabzi','{"id":"jowar-roti-with-mixed-sabzi","name":"Jowar Roti with Mixed Sabzi","baseServings":4,"batchSize":20,"ingredients":[{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":580,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"jowar flour","qty":320,"unit":"g","group":"Grains","scale":"linear"}],"steps":["For the vegetable curry, set aside these quantities from the combined ingredient list: 180 g carrot, 160 g green beans, 160 g peas, 150 g capsicum, 120 g onion, 280 g tomato, 10 g ginger, 10 g garlic, 25 ml oil, 3 g cumin, 1 g turmeric powder, 5 g coriander powder, 1 g red chilli powder, 2 g garam masala, 5 g salt, 300 ml water, 12 g coriander. Follow the next steps for this part of the meal.","Peel and dice carrots, trim beans into short lengths and cube capsicum. Keep the vegetables similar in size.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add carrots and beans first and simmer covered for 10 minutes; add peas and capsicum and cook another 7–8 minutes until all are tender.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot.","For the jowar bhakri, set aside these quantities from the combined ingredient list: 320 g jowar flour, 280 ml water, 4 g salt, 25 ml oil. Follow the next steps for this part of the meal.","Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Stir hot water gradually into the flour and knead when cool enough to handle until smooth and soft.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat out small rounds on a floured board or between parchment. Lift gently onto the tawa without tearing.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Cook the vegetable curry first and keep it hot while making the jowar rotis. Quantities include both components."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Jowar Roti with Mixed Sabzi","src":"/photos/jowar-roti-with-mixed-sabzi-1200.webp","small":"/photos/jowar-roti-with-mixed-sabzi-600.webp","width":1200,"height":900,"alt":"Jowar Roti with Mixed Sabzi served ready to eat","kind":"generated","title":"Jowar Roti with Mixed Sabzi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('misal-pav','{"id":"misal-pav","name":"Misal Pav","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked moth beans","qty":700,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"grated coconut","qty":50,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"goda masala","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"farsan","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon","qty":120,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["For the matki usal, set aside these quantities from the combined ingredient list: 700 g cooked moth beans, 150 g onion, 250 g tomato, 50 g grated coconut, 25 ml oil, 3 g cumin, 8 g goda masala, 1 g turmeric powder, 1 g red chilli powder, 5 g salt, 300 ml water, 12 g coriander. Follow the next steps for this part of the meal.","Use soaked moth beans or moth-bean sprouts already simmered until fully tender. Drain, reserving some cooking liquid if desired.","Toast the coconut in a dry pan until lightly golden and set aside.","Heat oil, sizzle cumin and cook chopped onion for 7 minutes. Add tomato and cook for another 7–8 minutes until pulpy.","Add turmeric, chilli and goda masala, then the cooked moth beans, toasted coconut and measured water.","Simmer gently for 12–15 minutes, stirring occasionally, until the beans have absorbed the masala.","Add salt, finish with coriander and serve hot. Cook sprouts thoroughly rather than adding them raw at the end.","For the pav and toppings, set aside these quantities from the combined ingredient list: 400 g eggless pav, 160 g farsan, 100 g onion, 120 g lemon, 250 ml water. Follow the next steps for this part of the meal.","Add the extra 250 ml water to the finished usal and simmer for 5 minutes to make a loose, spoonable gravy.","Warm pav in a dry pan and finely chop the extra onion. Cut lemon into wedges.","Divide hot usal into bowls. Top with farsan and onion only at serving time and serve with pav and lemon. Check the purchased farsan ingredients against your dietary restrictions."],"tips":["This regional breakfast can also be served as lunch. Keep farsan separate until eating so it stays crisp."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('appam-with-vegetable-stew','{"id":"appam-with-vegetable-stew","name":"Appam with Vegetable Stew","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":250,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"cooked rice","qty":70,"unit":"g","group":"Grains","scale":"linear"},{"name":"grated coconut","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"instant yeast","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"coconut milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"coconut oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["For the appam, set aside these quantities from the combined ingredient list: 250 g rice, 70 g cooked rice, 100 g grated coconut, 3 g instant yeast, 15 g sugar, 4 g salt, 400 ml water, 15 ml oil. Follow the next steps for this part of the meal.","Rinse raw rice and soak for 5 hours, then drain. Blend with cooked rice, coconut and 300 ml measured water until completely smooth.","Stir in instant yeast and sugar, cover loosely and leave in a warm place for 2–3 hours until bubbly and risen. Add salt and enough remaining water to make a thin pouring batter.","Lightly grease an appam pan and heat over medium heat. Pour in a small ladle of batter and swirl the pan so it coats the sides thinly while the centre remains thicker.","Cover and cook for 2–3 minutes until the centre is set and the edges lift easily. Do not flip. Repeat with the remaining batter and keep warm while preparing the stew.","For the vegetable stew, set aside these quantities from the combined ingredient list: 300 g potato, 200 g carrot, 150 g green beans, 120 g peas, 100 g onion, 12 g ginger, 500 ml coconut milk, 400 ml water, 20 ml coconut oil, 5 g curry leaves, 2 g cinnamon, 1 g cardamom, 5 g salt, 1 g black pepper. Follow the next steps for this part of the meal.","Peel and cube potato and carrot, trim beans into short lengths, slice onion and cut ginger into thin strips.","Heat coconut oil and add cinnamon, lightly crushed cardamom and curry leaves. Soften onion and ginger for 4 minutes without browning.","Add potato, carrot, beans, water and salt. Cover and simmer for 12–15 minutes until the vegetables are nearly tender.","Add peas and half the coconut milk. Simmer gently for 5–6 minutes until all vegetables are cooked.","Lower the heat and stir in the remaining coconut milk and pepper. Heat through for 2 minutes without a vigorous boil.","Taste, rest covered for 5 minutes and serve. Remove whole cinnamon and cardamom before eating."],"tips":["Allow 5 hours soaking plus 2–3 hours rising in addition to cooking. Prepare the stew while the batter rises."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Appam with Vegetable Stew","src":"/photos/appam-with-vegetable-stew-1200.webp","small":"/photos/appam-with-vegetable-stew-600.webp","width":1200,"height":1600,"alt":"Appam with Vegetable Stew served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Appam_and_stew.jpg","title":"File:Appam and stew.jpg","author":"Nithajay","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1707,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('neer-dosa-with-veg-curry','{"id":"neer-dosa-with-veg-curry","name":"Neer Dosa with Veg Curry","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":950,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":280,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["For the neer dosa, set aside these quantities from the combined ingredient list: 280 g rice, 650 ml water, 4 g salt, 20 ml oil. Follow the next steps for this part of the meal.","Rinse rice and soak for 4 hours. Drain and blend very smooth with 200 ml fresh water.","Stir in remaining measured water and salt to make a thin milk-like batter. This neer dosa batter does not require fermentation.","Heat a well-seasoned tawa over medium-high heat and grease lightly. Stir the batter each time before pouring a thin layer across the pan, tilting to fill gaps.","Cover for 1–2 minutes until the top is set. Lift carefully without flipping, fold loosely and repeat; let each dosa cool briefly before stacking so they do not stick.","For the vegetable curry, set aside these quantities from the combined ingredient list: 180 g carrot, 160 g green beans, 160 g peas, 150 g capsicum, 120 g onion, 280 g tomato, 10 g ginger, 10 g garlic, 25 ml oil, 3 g cumin, 1 g turmeric powder, 5 g coriander powder, 1 g red chilli powder, 2 g garam masala, 5 g salt, 300 ml water, 12 g coriander. Follow the next steps for this part of the meal.","Peel and dice carrots, trim beans into short lengths and cube capsicum. Keep the vegetables similar in size.","Finely chop the onion, mince ginger and garlic, and chop or puree the tomatoes. Measure the spices before heating the pan.","Heat oil in a heavy pan over medium heat. Add cumin and let it sizzle, then cook onion for 7–9 minutes until golden at the edges.","Stir in ginger and garlic for 1 minute. Lower the heat and add turmeric, coriander powder and chilli powder, followed immediately by tomato.","Cook the tomato masala for 8–10 minutes, stirring, until it thickens and no longer smells raw. Add the measured water and bring to a gentle simmer.","Add carrots and beans first and simmer covered for 10 minutes; add peas and capsicum and cook another 7–8 minutes until all are tender.","Add salt and garam masala, taste and adjust the sauce with a splash of hot water if needed. Finish with chopped coriander and serve hot."],"tips":["Allow 4 hours rice soaking separately. Start the vegetable curry before cooking the dosas so both can be served warm."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Neer Dosa with Veg Curry","src":"/photos/neer-dosa-with-veg-curry-1200.webp","small":"/photos/neer-dosa-with-veg-curry-600.webp","width":1200,"height":900,"alt":"Neer Dosa with Veg Curry served ready to eat","kind":"generated","title":"Neer Dosa with Veg Curry","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pithla-bhakri','{"id":"pithla-bhakri","name":"Pithla Bhakri","baseServings":4,"batchSize":50,"ingredients":[{"name":"gram flour","qty":150,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1030,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"jowar flour","qty":320,"unit":"g","group":"Grains","scale":"linear"}],"steps":["For the pithla, set aside these quantities from the combined ingredient list: 150 g gram flour, 120 g onion, 10 g garlic, 25 ml oil, 3 g mustard seeds, 3 g cumin, 1 g turmeric powder, 5 g salt, 750 ml water, 15 g coriander. Follow the next steps for this part of the meal.","Whisk gram flour with 300 ml water until smooth. Chop onion and mince garlic.","Heat oil, pop mustard seeds and sizzle cumin. Soften onion for 6 minutes, add garlic for 1 minute, then turmeric.","Add remaining 450 ml water and salt and bring to a boil. Pour in gram-flour slurry gradually while stirring continuously.","Cook over low heat for 10–12 minutes, scraping the base, until thick and smooth with no raw flour taste. Finish with coriander and keep warm while making bhakri.","For the jowar bhakri, set aside these quantities from the combined ingredient list: 320 g jowar flour, 280 ml water, 4 g salt, 25 ml oil. Follow the next steps for this part of the meal.","Measure the ingredients, reserving a little flour from the listed amount for dusting where needed. Mix the salt into the flour.","Stir hot water gradually into the flour and knead when cool enough to handle until smooth and soft.","Divide the dough into 8 portions, or 12 for thepla. Keep unused dough covered with a damp cloth to prevent cracking.","Pat out small rounds on a floured board or between parchment. Lift gently onto the tawa without tearing.","Cook on a medium-hot tawa for 1–2 minutes until the first side sets. Turn, brush lightly with oil, and cook the other side for 1–2 minutes. Turn again until brown spots form and there are no wet dough patches.","Keep cooked breads wrapped in a clean cloth while finishing the batch. Serve warm; oil and water needs vary slightly with flour freshness."],"tips":["Serve hot pithla with freshly cooked bhakri; both are included in the ingredient quantities."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pongal-with-sambar','{"id":"pongal-with-sambar","name":"Pongal with Sambar","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"moong dal","qty":100,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"water","qty":2100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":35,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black pepper","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":10,"unit":"g","group":"Spices","scale":"linear"},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"toor dal","qty":120,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"pumpkin","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":20,"unit":"g","group":"Other","scale":"linear"},{"name":"sambar powder","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["For the pongal, set aside these quantities from the combined ingredient list: 220 g rice, 100 g moong dal, 1200 ml water, 35 g ghee, 4 g cumin, 3 g black pepper, 12 g ginger, 5 g curry leaves, 40 g cashew, 5 g salt. Follow the next steps for this part of the meal.","Dry-toast moong dal for 2 minutes until aromatic, then rinse with rice and drain.","Add grains, measured water and salt to a deep pan. Bring to a boil, cover loosely and simmer for 30–35 minutes until very soft, stirring occasionally.","Mash lightly to a creamy consistency. Heat ghee separately, toast cashews, add cumin, coarsely crushed pepper, finely chopped ginger and curry leaves for 30 seconds.","Stir tempering into the soft rice and dal. Add hot water if too firm and keep warm while making sambar.","For the sambar, set aside these quantities from the combined ingredient list: 120 g toor dal, 120 g carrot, 150 g pumpkin, 150 g tomato, 20 g tamarind paste, 12 g sambar powder, 3 g mustard seeds, 5 g curry leaves, 15 ml oil, 1 g turmeric powder, 4 g salt, 900 ml water. Follow the next steps for this part of the meal.","Rinse toor dal and simmer with 550 ml water and turmeric for 35–45 minutes until completely soft, topping up with boiling water if necessary. Mash gently.","Meanwhile, dice carrot, pumpkin and tomato. Simmer with the remaining 350 ml water for 12–15 minutes until tender.","Add tamarind paste and sambar powder to the vegetables and simmer for 5 minutes. Stir in cooked dal and salt and simmer for another 5–8 minutes.","Heat the oil separately, let mustard seeds pop, add curry leaves carefully, then pour the tempering into the sambar. Thin with hot water if needed.","Check that lentils and vegetables are fully soft and taste for salt and sourness.","Rest covered for 5 minutes and serve hot with a separately prepared accompaniment."],"tips":["Cook the pongal and sambar in separate pans at the same time if your stove allows."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('shukto','{"id":"shukto","name":"Shukto","baseServings":4,"batchSize":50,"ingredients":[{"name":"bitter gourd","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"potato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"raw banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"brinjal","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fennel seeds","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard paste","qty":20,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"milk","qty":200,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Wash vegetables, peel potato and raw banana and cut all vegetables into similar batons. Slice bitter gourd into thin half-moons.","Heat half the oil and fry bitter gourd over medium heat for 5–6 minutes until lightly golden; remove and reserve.","Add remaining oil, sizzle mustard and fennel seeds, then add potato, raw banana and beans and stir for 3 minutes.","Add water and salt, cover and simmer for 10 minutes. Add brinjal and cook another 8–10 minutes until all vegetables are tender.","Whisk mustard paste with milk and pour into the pan. Add reserved bitter gourd and sugar and simmer very gently for 4 minutes.","Finish with ghee and serve warm as a mildly bitter vegetable course. Keep enough liquid for a light sauce rather than reducing it dry."],"tips":["Prepare the components in the order shown and check each for doneness before assembling the meal."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('handvo','{"id":"handvo","name":"Handvo","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"chana dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"moong dal","qty":60,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"urad dal","qty":40,"unit":"g","group":"Pulses","scale":"linear"},{"name":"curd","qty":150,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"bottle gourd","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sesame seeds","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"plain fruit salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse rice and lentils and soak for 5–6 hours. Drain and grind with curd and measured water into a thick, slightly coarse batter.","Cover loosely and ferment in a warm place for 6–8 hours until lightly sour and bubbly.","Preheat oven to 180°C and grease a 22 cm tin. Peel and grate bottle gourd, discarding it if bitter, and fold into batter with grated ginger, turmeric and salt.","Heat oil, pop mustard seeds and add sesame and curry leaves. Stir half the tempering into the batter and reserve the rest.","Fold fruit salt into the batter, transfer promptly to the tin and spread the remaining tempering on top.","Bake for 40–50 minutes until deeply golden and a skewer comes out clean. Rest for 15 minutes before slicing so the centre sets."],"tips":["Allow 5–6 hours soaking and 6–8 hours fermentation in addition to preparation and baking."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Handvo","src":"/photos/handvo-1200.webp","small":"/photos/handvo-600.webp","width":1200,"height":800,"alt":"Handvo served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Handavo.jpg","title":"File:Handavo.jpg","author":"Dkgohil","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('litti-chokha','{"id":"litti-chokha","name":"Litti Chokha","baseServings":4,"batchSize":50,"ingredients":[{"name":"whole wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"sattu roasted gram flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":50,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"mustard oil","qty":35,"unit":"ml","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"onion","qty":140,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"brinjal","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":350,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix wheat flour with 20 g ghee and half the salt. Add most of the water gradually and knead a soft dough; cover for 25 minutes.","Mix sattu with half the finely chopped onion, ginger, half the garlic, cumin, lemon juice, 20 ml mustard oil and a little salt. Add a spoonful of water only if needed so the filling holds together when squeezed.","Preheat oven to 210°C. Prick brinjal and roast with whole tomatoes for 35–45 minutes until soft; remove tomatoes earlier if done. Boil potato separately until tender.","Divide dough and filling into 8 portions. Flatten each dough ball, add filling, gather and seal completely, and roll gently into a ball.","Bake litti on a tray for 30–40 minutes, turning twice, until browned all around and the dough is fully cooked. Brush with remaining melted ghee.","Peel roasted brinjal and tomato and mash with peeled boiled potato, remaining onion, garlic, mustard oil, salt and coriander to make chokha. Serve with hot litti."],"tips":["Prepare the components in the order shown and check each for doneness before assembling the meal."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Litti Chokha","src":"/photos/litti-chokha-1200.webp","small":"/photos/litti-chokha-600.webp","width":626,"height":398,"alt":"Litti Chokha served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Litti_Chokha.jpg","title":"File:Litti Chokha.jpg","author":"Amrita Nityanand Singh","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":626,"sourceHeight":398,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-baati-churma','{"id":"dal-baati-churma","name":"Dal Baati Churma","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":60,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"moong dal","qty":50,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"chana dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"split urad dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"masoor dal","qty":50,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1340,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":140,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"whole wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"semolina","qty":60,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"curd","qty":80,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"powdered sugar","qty":70,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"almond","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85}],"steps":["For the panchmel dal, set aside these quantities from the combined ingredient list: 60 g toor dal, 50 g moong dal, 50 g chana dal, 50 g split urad dal, 50 g masoor dal, 1200 ml water, 1 g turmeric powder, 3 g cumin, 20 g ghee, 5 g salt, 12 g coriander, 200 g tomato, 5 g coriander powder. Follow the next steps for this part of the meal.","Pick over and rinse the toor dal and moong dal and chana dal and split urad dal and masoor dal. Soak for 1 hour, then drain to help the lentils cook evenly.","Put the lentils, measured water and turmeric in a deep saucepan. Bring to a boil, skim off foam, then reduce to a steady simmer with the lid partly open.","Cook for approximately 45–60 minutes, stirring occasionally and adding boiling water if the base becomes dry.  The lentils must crush easily between a spoon and the pan.","While they cook, chop the tomato. Heat ghee in a separate pan, let cumin sizzle, then cook tomato for 6–8 minutes until pulpy. Add any listed dry spices on low heat.","Check the chana dal in particular; it must crush easily before the combined lentils are considered cooked.","Stir the tempering into the cooked lentils with salt. Simmer gently for another 3–5 minutes, stirring the base, and adjust the thickness with hot water.","Finish with chopped coriander and serve hot. Soaking time is additional to the active preparation and cooking time.","For the baati and churma, set aside these quantities from the combined ingredient list: 320 g whole wheat flour, 60 g semolina, 120 g ghee, 80 g curd, 140 ml water, 4 g salt, 70 g powdered sugar, 1 g cardamom powder, 25 g almond. Follow the next steps for this part of the meal.","Preheat oven to 190°C. Mix flour, semolina and salt, rub in 60 g ghee, then add curd and water gradually to make a firm dough. Rest for 20 minutes.","Divide into 10 balls and make a shallow cross on each top. Bake for 35–45 minutes, turning halfway, until golden and cooked through; a cut baati should have no sticky raw dough.","Brush eight hot baatis with 30 g melted ghee and keep warm for serving.","Cool the remaining two baatis, break into pieces and pulse into coarse crumbs. Mix with remaining ghee, powdered sugar, cardamom and chopped almonds to make churma.","Serve two baatis per person with the prepared panchmel dal and a small portion of churma."],"tips":["Lentil soaking is additional; make the dal while the baati bake. The quantities include all three components."],"substitutions":[],"status":"complete","prepTime":110,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Baati Churma","src":"/photos/dal-baati-churma-1200.webp","small":"/photos/dal-baati-churma-600.webp","width":1200,"height":900,"alt":"Dal Baati Churma served ready to eat","kind":"generated","title":"Dal Baati Churma","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('undhiyu','{"id":"undhiyu","name":"Undhiyu","baseServings":4,"batchSize":50,"ingredients":[{"name":"surti papdi","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"small brinjal","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"small potatoes","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"purple yam","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"raw banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"coconut","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":60,"unit":"g","group":"Spices","scale":"linear"},{"name":"roasted peanuts","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"sesame seeds","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"jaggery","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cooked methi muthiya","qty":250,"unit":"g","group":"Other","scale":"linear"}],"steps":["String and split papdi. Peel and cube yam and raw banana. Slit small potatoes and brinjals in crosses while keeping them attached at the base.","Coarsely grind coconut, coriander, peanuts, sesame, ginger and garlic. Mix with coriander powder, turmeric, lemon juice, jaggery, half the oil and salt to make stuffing.","Fill potato and brinjal slits with some stuffing. Toss papdi, yam and banana with the remaining stuffing.","Heat remaining oil in a heavy pot and sizzle cumin. Layer papdi and yam at the bottom, then stuffed potatoes, brinjals and banana. Pour water around the edges.","Cover tightly and simmer on low heat for 30–40 minutes, gently turning occasionally and adding a little boiling water if dry, until potatoes and yam are fully tender.","Place fully cooked methi muthiya on top, cover and steam for 8–10 minutes. Mix gently without crushing and serve hot."],"tips":["This version uses prepared cooked methi muthiya; make the separate Methi Muthiya recipe in advance if needed."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Undhiyu","src":"/photos/undhiyu-1200.webp","small":"/photos/undhiyu-600.webp","width":1200,"height":900,"alt":"Undhiyu — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Undhiyu.jpg","title":"File:Undhiyu.jpg","author":"Jatan1992","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1728,"sourceHeight":1296,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('curd-rice','{"id":"curd-rice","name":"Curd Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":260,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":850,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":600,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"milk","qty":120,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"urad dal","qty":12,"unit":"g","group":"Pulses","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse rice and simmer with measured water for 20–25 minutes until very soft. Mash lightly while warm.","Spread in a shallow bowl and cool promptly until no longer hot; hot rice can split curd.","Whisk curd with milk and salt. Fold into cooled rice, loosening with a little drinking water if very thick.","Heat oil, pop mustard seeds, toast urad dal until golden and add finely chopped ginger and curry leaves for 30 seconds.","Let tempering cool for 1 minute, then fold into the rice with coriander.","Serve promptly or refrigerate. Never leave cooked rice and dairy sitting warm for an extended period."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Curd Rice","src":"/photos/curd-rice-1200.webp","small":"/photos/curd-rice-600.webp","width":1200,"height":900,"alt":"Curd Rice — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Curd_rice_in_ICH_Bhopal.jpg","title":"File:Curd rice in ICH Bhopal.jpg","author":"Suyash Dwivedi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4000,"sourceHeight":3000,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('peas-pulao-with-raita','{"id":"peas-pulao-with-raita","name":"Peas Pulao with Raita","baseServings":4,"batchSize":50,"ingredients":[{"name":"basmati rice","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.12},{"name":"peas","qty":220,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"roasted cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mint","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse rice, soak for 20 minutes and drain. Thinly slice onion, thaw peas if frozen and grate cucumber for raita.","Heat ghee, sizzle cumin and cinnamon and cook onion for 7 minutes until light golden.","Add peas and drained rice and stir gently for 1 minute. Add measured water and 4 g salt, bring to a boil, cover and simmer on low heat for 12–15 minutes.","Turn off heat and rest covered for 10 minutes before fluffing. Check grains are tender; add a little boiling water and steam longer if needed.","Whisk curd with roasted cumin and remaining salt. Squeeze excess liquid from cucumber and fold it in with chopped mint.","Serve hot pulao with chilled raita alongside. Remove cinnamon before eating."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('schezwan-fried-rice','{"id":"schezwan-fried-rice","name":"Schezwan Fried Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked chilled rice","qty":900,"unit":"g","group":"Grains","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"cabbage","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"capsicum","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"vegetarian schezwan sauce","qty":70,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":20,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":15,"unit":"ml","group":"Grains","scale":"linear"},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Use rice that was cooled promptly after cooking and refrigerated. Break up clumps gently before stir-frying.","Cut carrot, cabbage and capsicum into small pieces. Slice spring onion, keeping green tops separate, and mince garlic and ginger.","Heat a wide wok, add oil, garlic, ginger and spring onion whites and stir for 30 seconds.","Add carrot, cabbage and capsicum and stir-fry for 3–4 minutes until tender-crisp.","Add rice, schezwan sauce, soy sauce and vinegar. Toss over high heat for 4–5 minutes until the rice is steaming hot throughout, working in batches if needed.","Taste before adding salt, finish with spring onion greens and serve immediately. Check the sauce label for vegetarian ingredients."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Schezwan Fried Rice","src":"/photos/schezwan-fried-rice-1200.webp","small":"/photos/schezwan-fried-rice-600.webp","width":1200,"height":675,"alt":"Schezwan Fried Rice — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Schezwan_fried_rice.jpg","title":"File:Schezwan fried rice.jpg","author":"Thamizhpparithi Maari","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4208,"sourceHeight":2368,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-biryani','{"id":"vegetable-biryani","name":"Vegetable Biryani","baseServings":4,"batchSize":50,"ingredients":[{"name":"basmati rice","qty":320,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.12},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cauliflower","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"curd","qty":150,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":45,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cloves","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"biryani masala","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"mint","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"milk","qty":40,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse and soak rice for 30 minutes. Cut vegetables into small even pieces, thinly slice onions and steep saffron in warm milk.","Boil soaked rice in plenty of water with half the salt for 5–7 minutes until about three-quarters cooked: the centre should still feel firm. Drain immediately.","Heat ghee in a heavy pot, add whole spices and fry onions for 12–15 minutes until deep golden. Reserve one-third of the onions.","Add minced ginger and garlic for 1 minute, then tomato, turmeric and biryani masala for 5 minutes. Lower heat, stir in curd, vegetables, remaining salt and measured water, and cook covered for 10 minutes until nearly tender.","Spread drained rice over the vegetables without stirring. Scatter reserved onions, mint and coriander and drizzle saffron milk over the top.","Cover tightly and cook on the lowest heat for 20–25 minutes, using a heat diffuser if necessary. Rest off the heat for 10 minutes, then lift gently through the layers and serve."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Biryani","src":"/photos/vegetable-biryani-1200.webp","small":"/photos/vegetable-biryani-600.webp","width":1200,"height":675,"alt":"Vegetable Biryani — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Mixed_vegetable_biryani_(side).JPG","title":"File:Mixed vegetable biryani (side).JPG","author":"Daniele Pugliesi","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4608,"sourceHeight":2592,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-risotto','{"id":"vegetable-risotto","name":"Vegetable Risotto","baseServings":4,"batchSize":50,"ingredients":[{"name":"arborio rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"mushroom","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"zucchini","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"vegetarian hard cheese","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":1500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Keep measured water hot in a separate saucepan. Finely chop onion and garlic, slice mushrooms and dice zucchini.","Heat oil and half the butter in a wide pan. Soften onion for 5 minutes, add mushrooms for 6 minutes, then garlic and rice for 1–2 minutes until rice edges turn translucent.","Add a ladle of hot water and stir over medium-low heat until nearly absorbed. Continue adding water one ladle at a time, stirring frequently.","After 10 minutes add zucchini and peas. Continue adding hot water and cooking for another 8–12 minutes until the rice is tender with a slight bite; you may not need every drop.","Turn off heat and fold in remaining butter, grated vegetarian hard cheese, salt, pepper and lemon juice.","Rest for 2 minutes and serve while loose and creamy; risotto should flow gently on the plate rather than stand in a stiff mound."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Risotto","src":"/photos/vegetable-risotto-1200.webp","small":"/photos/vegetable-risotto-600.webp","width":1200,"height":900,"alt":"Vegetable Risotto served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Vegetable_risotto.jpg","title":"File:Vegetable risotto.jpg","author":"Lara604","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('teriyaki-tofu-bowl','{"id":"teriyaki-tofu-bowl","name":"Teriyaki Tofu Bowl","baseServings":4,"batchSize":50,"ingredients":[{"name":"firm tofu","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"broccoli","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"soy sauce","qty":45,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":25,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":30,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cornflour starch","qty":12,"unit":"g","group":"Grains","scale":"linear"},{"name":"sesame seeds","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":750,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse rice and cook with 580 ml water: bring to a boil, cover and simmer on low for 12–15 minutes, then rest for 10 minutes.","Press tofu for 15 minutes and cube it. Mix soy sauce, vinegar, sugar, grated ginger, minced garlic, starch and the remaining 170 ml water.","Cut broccoli into small florets and carrot into thin slices. Steam for 5–7 minutes until tender-crisp.","Heat oil in a wide non-stick pan and brown tofu for 8–10 minutes, turning gently.","Stir the sauce mixture again, pour over tofu and simmer for 3 minutes until thick and glossy, tossing gently to coat.","Divide rice between bowls, add vegetables and tofu and spoon over sauce. Finish with sesame seeds."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Teriyaki Tofu Bowl","src":"/photos/teriyaki-tofu-bowl-1200.webp","small":"/photos/teriyaki-tofu-bowl-600.webp","width":1200,"height":900,"alt":"Teriyaki Tofu Bowl served ready to eat","kind":"generated","title":"Teriyaki Tofu Bowl","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-burrito-bowl','{"id":"vegetarian-burrito-bowl","name":"Vegetarian Burrito Bowl","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"cooked black beans","qty":600,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sweet corn","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"avocado flesh","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"lime juice","qty":45,"unit":"ml","group":"Other","scale":"linear"},{"name":"coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse rice and cook with 580 ml water and half the salt, covered over low heat for 12–15 minutes. Rest for 10 minutes and fold in half the lime juice and coriander.","Heat half the oil, cook half the chopped onion for 4 minutes, add beans, cumin, paprika and remaining water, and simmer for 8 minutes.","In a separate pan heat remaining oil and stir-fry sliced capsicum and corn for 5–6 minutes until lightly browned.","Mix diced tomatoes, remaining onion, remaining lime juice, coriander and salt for salsa.","Slice avocado just before serving and divide rice among four bowls.","Arrange beans, vegetables, salsa and avocado over the rice and serve hot and cold components together immediately."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetarian Burrito Bowl","src":"/photos/vegetarian-burrito-bowl-1200.webp","small":"/photos/vegetarian-burrito-bowl-600.webp","width":1200,"height":900,"alt":"Vegetarian Burrito Bowl served ready to eat","kind":"generated","title":"Vegetarian Burrito Bowl","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mujaddara','{"id":"mujaddara","name":"Mujaddara","baseServings":4,"batchSize":50,"ingredients":[{"name":"brown lentils","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"basmati rice","qty":260,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.12},{"name":"onion","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"olive oil","qty":65,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"water","qty":1500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse lentils and simmer with 700 ml water for 15–20 minutes until partly tender but still holding their shape. Drain, reserving the liquid.","Thinly slice onions and cook in oil over medium-low heat for 25–35 minutes, stirring often, until deeply caramelized but not burnt. Reserve one-third for topping.","Rinse rice and add to remaining onions with cumin, lentils, salt and pepper. Stir gently for 1 minute.","Measure 650 ml of reserved lentil liquid plus fresh water as needed and add to the pan. Bring to a boil, cover and simmer on low heat for 15–18 minutes.","Check that both rice and lentils are tender, adding a little boiling water if needed. Turn off heat and rest covered for 10 minutes.","Fluff gently, top with reserved onions and serve warm."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mujaddara","src":"/photos/mujaddara-1200.webp","small":"/photos/mujaddara-600.webp","width":900,"height":1200,"alt":"Mujaddara — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Liat_Portal_for_Foodie_Disorder_-_Mujaddara.jpg","title":"File:Liat Portal for Foodie Disorder - Mujaddara.jpg","author":"HaJunkiyada","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3024,"sourceHeight":4032,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('millet-breakfast-bowl','{"id":"millet-breakfast-bowl","name":"Millet Breakfast Bowl","baseServings":4,"batchSize":50,"ingredients":[{"name":"millet","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"banana","qty":250,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"dates","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3},{"name":"almond","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"cinnamon powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Rinse millet thoroughly and drain. Pit and chop dates and roughly chop almonds.","Put millet, measured water and salt in a saucepan. Bring to a boil, cover loosely and simmer for 18–22 minutes until the grains are tender.","Add milk, dates and cinnamon and simmer gently for 5–8 minutes, stirring until creamy.","Toast almonds in a dry pan for 2–3 minutes and let cool slightly.","Peel and slice banana immediately before serving. Divide warm millet porridge into four bowls.","Top with banana and almonds and serve. Thin with warm milk if the porridge thickens while standing."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Millet Breakfast Bowl","src":"/photos/millet-breakfast-bowl-1200.webp","small":"/photos/millet-breakfast-bowl-600.webp","width":1200,"height":900,"alt":"Millet Breakfast Bowl served ready to eat","kind":"generated","title":"Millet Breakfast Bowl","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragi-mudde','{"id":"ragi-mudde","name":"Ragi Mudde","baseServings":4,"batchSize":50,"ingredients":[{"name":"ragi flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6}],"steps":["Mix 30 g of the ragi flour with 100 ml cool water to make a smooth slurry.","Bring remaining water and salt to a boil in a heavy deep saucepan. Stir in the slurry and simmer for 2 minutes.","Add remaining ragi flour in an even mound and cook on low heat for 3 minutes before mixing.","Stir firmly with a sturdy wooden spoon, breaking all lumps, then cover and steam on low heat for 8–10 minutes until the mixture is glossy and fully cooked.","Cool just enough to handle safely. Divide into four portions and shape into smooth balls with wet hands or two wet bowls; brush with ghee.","Serve hot with a separately prepared dal or sambar. The dough should be soft and cohesive, with no dry flour pockets."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Ragi Mudde","src":"/photos/ragi-mudde-1200.webp","small":"/photos/ragi-mudde-600.webp","width":1200,"height":800,"alt":"Ragi Mudde — photographed serving","source":"https://commons.wikimedia.org/wiki/File:RAGI_MUDDE.JPG","title":"File:RAGI MUDDE.JPG","author":"Vsigamany","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3888,"sourceHeight":2592,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sakkarai-pongal','{"id":"sakkarai-pongal","name":"Sakkarai Pongal","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"moong dal","qty":60,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"water","qty":850,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"jaggery","qty":180,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"ghee","qty":60,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cashew","qty":35,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"raisins","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Dry-toast moong dal for 2 minutes until aromatic, then rinse with rice and drain.","Cook rice and dal in 650 ml measured water for 25–30 minutes until very soft, stirring and topping up with hot water if needed.","Dissolve jaggery in remaining 200 ml warm water and strain if gritty. Add to the fully softened rice and dal.","Simmer for 6–8 minutes while stirring until thick and creamy. Add 40 g ghee gradually and mix in cardamom.","Heat remaining ghee, toast cashews golden, then add raisins briefly until they puff. Stir into the pongal.","Serve warm as a sweet dish. Stop cooking while slightly loose because it thickens as it cools."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sakkarai Pongal","src":"/photos/sakkarai-pongal-1200.webp","small":"/photos/sakkarai-pongal-600.webp","width":1200,"height":707,"alt":"Sakkarai Pongal served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Sarkarai_Pongal.JPG","title":"File:Sarkarai Pongal.JPG","author":"Babithajcosta","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":754,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bisi-bele-bath','{"id":"bisi-bele-bath","name":"Bisi Bele Bath","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"toor dal","qty":140,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"green beans","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"tamarind paste","qty":30,"unit":"g","group":"Other","scale":"linear"},{"name":"bisi bele bath powder","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":15,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"ghee","qty":35,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cashew","qty":35,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse toor dal and simmer with 800 ml water and turmeric for 35–45 minutes until completely soft. Mash lightly.","Rinse rice, dice carrot and beans and chop tomato. Cook rice with vegetables and 750 ml water in a separate pot for 20 minutes until soft.","Mix tamarind paste, spice powder and jaggery with remaining 150 ml water and simmer separately for 5 minutes.","Combine cooked rice and vegetables, mashed dal and the tamarind-spice mixture. Add salt and simmer for 8–10 minutes, stirring the base.","Heat ghee, toast cashews, pop mustard seeds and add curry leaves. Pour the tempering into the pot.","Adjust with hot water to a soft, flowing consistency and serve hot. The dish should be looser than pulao."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Bisi Bele Bath","src":"/photos/bisi-bele-bath-1200.webp","small":"/photos/bisi-bele-bath-600.webp","width":1200,"height":800,"alt":"Bisi Bele Bath — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Bisi_Bele_Bath_(Bisibelebath).JPG","title":"File:Bisi Bele Bath (Bisibelebath).JPG","author":"Food and Remedy, LLC","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4693,"sourceHeight":3129,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-dhokli','{"id":"dal-dhokli","name":"Dal Dhokli","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":220,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"whole wheat flour","qty":240,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"gram flour","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"water","qty":1800,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"jaggery","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse toor dal and simmer with 1000 ml water and half the turmeric for 35–45 minutes until soft, then whisk smooth.","Mix wheat flour, gram flour, oil, remaining turmeric and 3 g salt. Add about 140 ml water gradually and knead a firm dough; cover for 20 minutes.","Heat ghee, pop mustard seeds and sizzle cumin. Add chopped tomato and chilli powder and cook for 6 minutes. Stir into the dal with jaggery, remaining salt and remaining measured water.","Roll dough thinly, about 2 mm, and cut into small diamonds. Bring dal to a gentle boil and add diamonds one at a time, stirring so they do not clump.","Simmer uncovered for 15–20 minutes, stirring gently, until dough pieces are tender with no raw flour centre. Add boiling water if the dal thickens too much.","Turn off heat, add lemon juice and coriander and serve immediately while loose and soupy."],"tips":["Rinse grains before cooking, use a heavy pan and rest covered before fluffing or serving."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('veg-cutlet','{"id":"veg-cutlet","name":"Veg Cutlet","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":500,"unit":"g","group":"Packaged","scale":"linear"},{"name":"carrot","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"eggless breadcrumbs","qty":100,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Steam diced carrot and peas for 8 minutes until tender, drain and mash coarsely with peeled boiled potato.","Add cumin, garam masala, lemon juice, coriander and salt. For breadcrumb recipes, mix in half the crumbs and reserve the rest for coating.","Mix into a firm dough-like filling. If very soft, chill for 20 minutes; avoid adding water.","Divide into 12 equal portions and shape into patties about 1.5 cm thick. Coat breadcrumb recipes in the reserved crumbs.","Heat a thin layer of oil in a wide skillet over medium heat. Pan-fry in batches for 3–4 minutes per side until crisp and heated through.","Drain briefly and serve three patties per portion. Break the test piece open to check the centre is piping hot."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Veg Cutlet","src":"/photos/veg-cutlet-1200.webp","small":"/photos/veg-cutlet-600.webp","width":1200,"height":719,"alt":"Veg Cutlet served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Veg_Cutlets_-_Aloo_Filled.JPG","title":"File:Veg Cutlets - Aloo Filled.JPG","author":"Siddhantsahni28","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1200,"sourceHeight":719,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('leftover-rice-cutlets','{"id":"leftover-rice-cutlets","name":"Leftover Rice Cutlets","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked chilled rice","qty":350,"unit":"g","group":"Grains","scale":"linear"},{"name":"boiled potato","qty":300,"unit":"g","group":"Packaged","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"eggless breadcrumbs","qty":100,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Use rice cooled promptly and refrigerated after cooking. Mash with peeled boiled potato and finely grated carrot.","Add cumin, garam masala, lemon juice, coriander and salt. For breadcrumb recipes, mix in half the crumbs and reserve the rest for coating.","Mix into a firm dough-like filling. If very soft, chill for 20 minutes; avoid adding water.","Divide into 12 equal portions and shape into patties about 1.5 cm thick. Coat breadcrumb recipes in the reserved crumbs.","Heat a thin layer of oil in a wide skillet over medium heat. Pan-fry in batches for 3–4 minutes per side until crisp and heated through.","Drain briefly and serve three patties per portion. Break the test piece open to check the centre is piping hot."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Leftover Rice Cutlets","src":"/photos/leftover-rice-cutlets-1200.webp","small":"/photos/leftover-rice-cutlets-600.webp","width":1200,"height":900,"alt":"Leftover Rice Cutlets served ready to eat","kind":"generated","title":"Leftover Rice Cutlets","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hara-bhara-kebab','{"id":"hara-bhara-kebab","name":"Hara Bhara Kebab","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":350,"unit":"g","group":"Packaged","scale":"linear"},{"name":"spinach","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"peas","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"roasted gram flour","qty":70,"unit":"g","group":"Grains","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Steam peas until tender. Blanch washed spinach for 1 minute, cool, squeeze very dry and chop finely. Mash both with peeled boiled potato and roasted gram flour.","Add cumin, garam masala, lemon juice, coriander and salt. For breadcrumb recipes, mix in half the crumbs and reserve the rest for coating.","Mix into a firm dough-like filling. If very soft, chill for 20 minutes; avoid adding water.","Divide into 12 equal portions and shape into patties about 1.5 cm thick. Coat breadcrumb recipes in the reserved crumbs.","Heat a thin layer of oil in a wide skillet over medium heat. Pan-fry in batches for 3–4 minutes per side until crisp and heated through.","Drain briefly and serve three patties per portion. Break the test piece open to check the centre is piping hot."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Hara Bhara Kebab","src":"/photos/hara-bhara-kebab-1200.webp","small":"/photos/hara-bhara-kebab-600.webp","width":1200,"height":900,"alt":"Hara Bhara Kebab served ready to eat","kind":"generated","title":"Hara Bhara Kebab","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-tikka','{"id":"paneer-tikka","name":"Paneer Tikka","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"thick curd","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"roasted gram flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"Kashmiri chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Cut paneer, capsicum and onion into similar 3 cm pieces. Mince ginger and garlic.","Whisk thick curd with gram flour, oil, lemon juice, ginger, garlic, spices and salt into a thick marinade.","Coat paneer and vegetables gently and refrigerate for 30 minutes. If using wooden skewers, soak them in water during this time.","Preheat oven to 220°C. Thread pieces loosely onto skewers or arrange in one layer on a lined tray.","Roast for 12–15 minutes, turning once, until the vegetables are tender-crisp and paneer is lightly browned. Use the grill briefly at the end only while watching closely.","Rest for 2 minutes and serve hot. Avoid prolonged cooking, which makes paneer rubbery."],"tips":["Allow an additional 30 minutes marinating."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Paneer Tikka","src":"/photos/paneer-tikka-1200.webp","small":"/photos/paneer-tikka-600.webp","width":1200,"height":399,"alt":"Paneer Tikka served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Paneer_Tikka_in_India.jpg","title":"File:Paneer Tikka in India.jpg","author":"Rutvi Mistry","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":426,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-tikka-wrap','{"id":"paneer-tikka-wrap","name":"Paneer Tikka Wrap","baseServings":4,"batchSize":20,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"thick curd","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"roasted gram flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"Kashmiri chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"lettuce","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Cut paneer, capsicum and onion into similar 3 cm pieces. Mince ginger and garlic.","Whisk thick curd with gram flour, oil, lemon juice, ginger, garlic, spices and salt into a thick marinade.","Coat paneer and vegetables gently and refrigerate for 30 minutes. If using wooden skewers, soak them in water during this time.","Preheat oven to 220°C. Thread pieces loosely onto skewers or arrange in one layer on a lined tray.","Roast for 12–15 minutes, turning once, until the vegetables are tender-crisp and paneer is lightly browned. Use the grill briefly at the end only while watching closely.","Warm tortillas in a dry pan for 20 seconds per side. Spread with mint chutney and add washed, dried lettuce.","Remove cooked paneer and vegetables from the skewers, divide between tortillas and roll tightly, tucking in the ends. Serve warm."],"tips":["Allow 30 minutes marinating before cooking; check the chutney ingredients for exclusions."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-tikka-masala','{"id":"paneer-tikka-masala","name":"Paneer Tikka Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"thick curd","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"roasted gram flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"Kashmiri chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"tomato","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"butter","qty":25,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cream","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cut paneer, capsicum and onion into similar 3 cm pieces. Mince ginger and garlic.","Whisk thick curd with gram flour, oil, lemon juice, ginger, garlic, spices and salt into a thick marinade.","Coat paneer and vegetables gently and refrigerate for 30 minutes. If using wooden skewers, soak them in water during this time.","Preheat oven to 220°C. Thread pieces loosely onto skewers or arrange in one layer on a lined tray.","Roast for 12–15 minutes, turning once, until the vegetables are tender-crisp and paneer is lightly browned. Use the grill briefly at the end only while watching closely.","While the tikka cooks, soak cashews in hot water for 15 minutes. Melt butter and soften the extra chopped onion for 7 minutes; add chopped tomato and cook for 10 minutes until thick.","Blend this tomato base with drained cashews and measured water until smooth, then return to the pan and simmer for 8 minutes.","Fold the cooked paneer tikka and vegetables into the sauce, add cream and warm gently for 3 minutes. Taste and adjust salt before serving."],"tips":["Allow 30 minutes marinating separately. The ingredient list includes both tikka and gravy components."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chilli-paneer-dry','{"id":"chilli-paneer-dry","name":"Chilli Paneer Dry","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"cornflour starch","qty":45,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato ketchup","qty":50,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chilli sauce","qty":25,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"spring onion","qty":50,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cube paneer and mix plain flour, 30 g starch and 60 ml water into a light batter. Toss paneer in the batter.","Heat 40 ml oil in a wide non-stick pan and shallow-fry paneer for 2–3 minutes per side until lightly crisp. Transfer to a plate.","Mix soy sauce, ketchup, chilli sauce, vinegar and sugar. Mix the remaining starch separately with 40 ml cold water.","Heat remaining oil and stir-fry minced ginger and garlic for 30 seconds. Add capsicum and onion squares and toss for 3–4 minutes.","Add the sauce mixture and remaining water, bring to a simmer, then stir in the starch slurry and cook for 2–3 minutes until thick enough to coat the vegetables.","Return paneer and toss gently for 1–2 minutes. Finish with spring onion and serve immediately; taste before adding salt because the sauces already contain it."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chilli Paneer Dry","src":"/photos/chilli-paneer-dry-1200.webp","small":"/photos/chilli-paneer-dry-600.webp","width":1200,"height":900,"alt":"Chilli Paneer Dry served ready to eat","kind":"generated","title":"Chilli Paneer Dry","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chilli-paneer-gravy','{"id":"chilli-paneer-gravy","name":"Chilli Paneer Gravy","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":500,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"cornflour starch","qty":45,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato ketchup","qty":50,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chilli sauce","qty":25,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"spring onion","qty":50,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Cube paneer and mix plain flour, 30 g starch and 60 ml water into a light batter. Toss paneer in the batter.","Heat 40 ml oil in a wide non-stick pan and shallow-fry paneer for 2–3 minutes per side until lightly crisp. Transfer to a plate.","Mix soy sauce, ketchup, chilli sauce, vinegar and sugar. Mix the remaining starch separately with 40 ml cold water.","Heat remaining oil and stir-fry minced ginger and garlic for 30 seconds. Add capsicum and onion squares and toss for 3–4 minutes.","Add the sauce mixture and remaining water, bring to a simmer, then stir in the starch slurry and cook for 2–3 minutes until a glossy pourable gravy forms.","Return paneer and toss gently for 1–2 minutes. Finish with spring onion and serve immediately; taste before adding salt because the sauces already contain it."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Chilli Paneer Gravy","src":"/photos/chilli-paneer-gravy-1200.webp","small":"/photos/chilli-paneer-gravy-600.webp","width":1200,"height":900,"alt":"Chilli Paneer Gravy served ready to eat","kind":"generated","title":"Chilli Paneer Gravy","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('veg-manchurian-dry','{"id":"veg-manchurian-dry","name":"Veg Manchurian Dry","baseServings":4,"batchSize":20,"ingredients":[{"name":"cabbage","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"plain flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"cornflour starch","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":18,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato ketchup","qty":40,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chilli sauce","qty":25,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Finely shred cabbage and carrot and mince capsicum. Mix with plain flour, 40 g starch, half the ginger and garlic, and salt; the vegetables should release enough moisture to bind. Add water only a teaspoon at a time if dry.","Shape 16 small balls firmly. Heat frying oil to about 170°C in a deep pan less than half full and fry one test ball; add a little flour if it breaks.","Fry the remaining balls in batches for 4–5 minutes until golden and cooked through, then drain.","Heat 20 ml oil, stir-fry remaining ginger and garlic with spring onion whites for 30 seconds. Add soy sauce, ketchup, chilli sauce, vinegar and all but 60 ml measured water.","Mix remaining starch with the reserved cold water. Stir into the simmering sauce and cook for 2–3 minutes until glossy and thickened.","Add fried balls only at serving time and toss gently. Finish with spring onion greens; keep sauce separate if preparing ahead to preserve texture."],"tips":["Frying oil is a working quantity and is not all absorbed."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('veg-manchurian-gravy','{"id":"veg-manchurian-gravy","name":"Veg Manchurian Gravy","baseServings":4,"batchSize":50,"ingredients":[{"name":"cabbage","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"plain flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"cornflour starch","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":18,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato ketchup","qty":40,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chilli sauce","qty":25,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"rice vinegar","qty":20,"unit":"ml","group":"Grains","scale":"linear"},{"name":"spring onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Finely shred cabbage and carrot and mince capsicum. Mix with plain flour, 40 g starch, half the ginger and garlic, and salt; the vegetables should release enough moisture to bind. Add water only a teaspoon at a time if dry.","Shape 16 small balls firmly. Heat frying oil to about 170°C in a deep pan less than half full and fry one test ball; add a little flour if it breaks.","Fry the remaining balls in batches for 4–5 minutes until golden and cooked through, then drain.","Heat 20 ml oil, stir-fry remaining ginger and garlic with spring onion whites for 30 seconds. Add soy sauce, ketchup, chilli sauce, vinegar and all but 60 ml measured water.","Mix remaining starch with the reserved cold water. Stir into the simmering sauce and cook for 2–3 minutes until glossy and thickened.","Add fried balls only at serving time and toss gently. Finish with spring onion greens; keep sauce separate if preparing ahead to preserve texture."],"tips":["Frying oil is a working quantity and is not all absorbed."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Veg Manchurian Gravy","src":"/photos/veg-manchurian-gravy-1200.webp","small":"/photos/veg-manchurian-gravy-600.webp","width":1200,"height":900,"alt":"Veg Manchurian Gravy served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Manchurian.jpg","title":"File:Manchurian.jpg","author":"Mahato Rohit","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-corn','{"id":"masala-corn","name":"Masala Corn","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet corn","qty":700,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil or steam corn kernels for 5–8 minutes until tender, then drain thoroughly.","Melt butter in a wide pan over medium-low heat.","Add corn and toss for 2–3 minutes until hot and lightly glossy.","Turn off heat and add chaat masala, cumin, chilli and lemon juice.","Taste before adding salt because chaat masala is already salted. Fold in chopped coriander.","Divide into four small bowls and serve hot."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Masala Corn","src":"/photos/masala-corn-1200.webp","small":"/photos/masala-corn-600.webp","width":1200,"height":898,"alt":"Masala Corn — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Masala_corn_by_be_hungry.jpg","title":"File:Masala corn by be hungry.jpg","author":"Be Hungry Cooking","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4640,"sourceHeight":3472,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('puri','{"id":"puri","name":"Puri","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":170,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mix wheat flour, salt and 20 ml oil. Add water gradually to make a firm smooth dough; rest covered for 15 minutes.","Divide dough into 16 small balls. Keep covered so the surface does not dry out.","Roll each ball with a little oil on the board into an even 10 cm round, about 2 mm thick.","Heat frying oil to about 180°C. A tiny piece of dough should rise promptly without darkening immediately.","Slide in one puri and press lightly with a slotted spoon until it puffs. Turn and fry for 20–30 seconds more until golden and cooked.","Drain and repeat, allowing oil to regain heat between batches. Serve four small puris per portion."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rajgira-puri','{"id":"rajgira-puri","name":"Rajgira Puri","baseServings":4,"batchSize":20,"ingredients":[{"name":"amaranth flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"boiled potato","qty":200,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":40,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mash peeled boiled potato very smoothly. Mix with amaranth flour, salt and 20 ml oil; add only enough water to make a firm pliable dough.","Divide dough into 16 small balls. Keep covered so the surface does not dry out.","Pat or roll each ball between lightly oiled parchment sheets into a 9 cm round; lift carefully because amaranth dough is delicate.","Heat frying oil to about 180°C. A tiny piece of dough should rise promptly without darkening immediately.","Slide in one puri and press lightly with a slotted spoon until it puffs. Turn and fry for 20–30 seconds more until golden and cooked.","Drain and repeat, allowing oil to regain heat between batches. Serve four small puris per portion."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rajgira Puri","src":"/photos/rajgira-puri-1200.webp","small":"/photos/rajgira-puri-600.webp","width":1200,"height":900,"alt":"Rajgira Puri served ready to eat","kind":"generated","title":"Rajgira Puri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('samosa','{"id":"samosa","name":"Samosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"oil","qty":75,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"potato","qty":600,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander seeds","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"fennel seeds","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"dried mango powder","qty":5,"unit":"g","group":"Fruits","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rub 60 ml oil and 3 g salt into flour until a handful holds together when squeezed. Add water gradually to make a firm dough; cover and rest for 30 minutes.","Boil potatoes until tender, peel and break into small pieces. Heat remaining oil, sizzle cumin, crushed coriander and fennel, then add grated ginger and peas for 3 minutes.","Add potatoes, garam masala, dried mango powder and remaining salt. Stir for 4 minutes, then cool the filling completely.","Divide dough into 4 balls. Roll each into an oval, cut in half and form each half into a cone, sealing the straight edge with a little water.","Fill each cone without overpacking, moisten the open edge, pinch tightly closed and press the seam firmly. Make 8 samosas.","Heat oil to 150–160°C and fry in batches for 12–15 minutes, turning occasionally, until the pastry is evenly golden and cooked through. Drain and serve warm."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Samosa","src":"/photos/samosa-1200.webp","small":"/photos/samosa-600.webp","width":1200,"height":800,"alt":"Samosa — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Indian_Samosa_by_clumsy_home_chef.jpg","title":"File:Indian Samosa by clumsy home chef.jpg","author":"ClumsyHomeChef","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2592,"sourceHeight":1728,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kachori','{"id":"kachori","name":"Kachori","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"moong dal","qty":140,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"oil","qty":75,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"fennel seeds","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander seeds","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"asafoetida","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"dried mango powder","qty":5,"unit":"g","group":"Fruits","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rinse moong dal and soak for 2 hours, then drain very well and grind coarsely without extra water.","Rub 60 ml oil and 3 g salt into flour. Add water gradually and knead a soft dough; cover and rest for 25 minutes.","Heat remaining oil, toast cumin, coarsely crushed fennel and coriander and asafoetida. Add ground dal and cook on low heat for 12–15 minutes, stirring until dry, crumbly and cooked.","Mix chilli, dried mango powder and remaining salt into the filling and cool completely.","Divide dough and filling into 10 portions. Flatten each dough ball, fill, gather and seal, then press gently into a 7 cm disc without tearing.","Fry in oil at 150–160°C for 10–14 minutes, turning occasionally, until crisp and golden. Drain and let cool slightly before serving."],"tips":["Allow 2 hours soaking separately. Fry slowly so the inner pastry cooks before the outside browns."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('corn-cheese-balls','{"id":"corn-cheese-balls","name":"Corn Cheese Balls","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked sweet corn","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"boiled potato","qty":350,"unit":"g","group":"Packaged","scale":"linear"},{"name":"vegetarian cheese","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"plain flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"eggless breadcrumbs","qty":140,"unit":"g","group":"Bakery","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Drain cooked corn very well and chop it coarsely. Mash peeled boiled potato and grate cheese labelled suitable for vegetarians.","Mix corn, potato, cheese, 40 g breadcrumbs, salt and pepper into a firm mixture. Chill for 20 minutes if soft.","Whisk flour and water to a smooth coating batter. Place remaining breadcrumbs on a plate.","Shape 16 small balls, dip each in batter and coat completely with breadcrumbs. Chill coated balls for 15 minutes to firm up.","Heat oil to 170–175°C. Fry one test ball; if it bursts, reinforce the coating or chill longer. Fry remaining balls in small batches for 3–4 minutes until golden.","Drain and rest for 2 minutes before serving; the cheese centre will be very hot."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Corn Cheese Balls","src":"/photos/corn-cheese-balls-1200.webp","small":"/photos/corn-cheese-balls-600.webp","width":1200,"height":900,"alt":"Corn Cheese Balls served ready to eat","kind":"generated","title":"Corn Cheese Balls","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dahi-vada','{"id":"dahi-vada","name":"Dahi Vada","baseServings":4,"batchSize":20,"ingredients":[{"name":"urad dal","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curd","qty":700,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":30,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"roasted cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse urad dal and soak for 4 hours. Drain thoroughly and grind with ginger and measured water added a little at a time into a thick smooth batter.","Beat batter by hand for 4–5 minutes until light. Mix in cumin and half the salt; a tiny dollop should float in water when sufficiently aerated.","Heat frying oil to 165–170°C. Drop small spoonfuls carefully and fry for 4–5 minutes, turning until golden and cooked in the centre.","Drain, cool for 2 minutes, then soak vadas in a bowl of warm drinking water for 10 minutes. Press gently between palms to remove excess water without breaking.","Whisk curd with sugar and remaining salt. Arrange softened vadas in a shallow dish and cover generously with curd.","Refrigerate for 30 minutes, then drizzle both chutneys and sprinkle roasted cumin and chilli. Serve chilled."],"tips":["Allow 4 hours soaking plus 30 minutes chilling separately."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dahi Vada","src":"/photos/dahi-vada-1200.webp","small":"/photos/dahi-vada-600.webp","width":1200,"height":900,"alt":"Dahi Vada — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Dahi_Vadas_(Dhai_Bhalla).JPG","title":"File:Dahi Vadas (Dhai Bhalla).JPG","author":"Mdsmds0","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4896,"sourceHeight":3672,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aloo-tikki-chaat','{"id":"aloo-tikki-chaat","name":"Aloo Tikki Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":650,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rice flour","qty":55,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Mash peeled boiled potatoes completely and mix with rice flour, grated ginger, cumin, coriander and salt. Shape into 12 firm patties about 1.5 cm thick.","Heat oil in a wide skillet and pan-fry the patties for 4–5 minutes per side until crisp and heated through. Keep warm while preparing the toppings.","Whisk curd until smooth and set out both chutneys and sev separately.","Arrange three hot tikkis on each plate and spoon curd over them.","Drizzle tamarind and mint chutneys, sprinkle chaat masala and finish with sev.","Serve immediately while the patties are crisp and warm; add toppings only at the last moment."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Aloo Tikki Chaat","src":"/photos/aloo-tikki-chaat-1200.webp","small":"/photos/aloo-tikki-chaat-600.webp","width":1200,"height":900,"alt":"Aloo Tikki Chaat served ready to eat","kind":"generated","title":"Aloo Tikki Chaat","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragda-pattice','{"id":"ragda-pattice","name":"Ragda Pattice","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":650,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rice flour","qty":55,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cooked white peas","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"}],"steps":["Use white peas already soaked and boiled until completely tender, or cooked canned peas. Simmer with measured water and turmeric for 12–15 minutes, mashing some peas to make a thick ragda.","Mash peeled boiled potatoes completely and mix with rice flour, grated ginger, cumin, coriander and salt. Shape into 12 firm patties about 1.5 cm thick.","Heat oil in a wide skillet and pan-fry the patties for 4–5 minutes per side until crisp and heated through. Keep warm while preparing the toppings.","Finely chop onion and set out chutneys and sev. Taste ragda and adjust salt if needed.","Spoon ragda onto four plates, add three patties each and drizzle both chutneys over the top.","Finish with onion and sev and serve immediately. Keep crisp patties separate from ragda until serving."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vada-pav','{"id":"vada-pav","name":"Vada Pav","baseServings":4,"batchSize":20,"ingredients":[{"name":"potato","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"gram flour","qty":200,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"dry garlic chutney","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"mint chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil potatoes until tender, peel and mash. Heat 20 ml oil, pop mustard seeds, add curry leaves and minced ginger and garlic for 30 seconds.","Add potatoes, half the turmeric and 4 g salt and cook for 3 minutes. Cool and shape into 8 round balls.","Whisk gram flour with water, remaining turmeric and salt into a thick smooth batter that coats a spoon.","Heat oil to about 170°C. Dip potato balls in batter and fry in batches for 4–5 minutes until crisp and golden; drain.","Split pav without cutting all the way through. Spread a little mint chutney and sprinkle dry garlic chutney inside each.","Place a hot vada in each bun and serve two small vada pav per portion. Check purchased chutneys and pav ingredients."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('falafel-pita','{"id":"falafel-pita","name":"Falafel Pita","baseServings":4,"batchSize":20,"ingredients":[{"name":"dried chickpeas","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"parsley","qty":50,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":40,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"plain flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"baking powder","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"eggless pita bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tahini","qty":80,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.7},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Soak dried chickpeas in plenty of water for 12–18 hours, then drain and dry thoroughly. Use soaked uncooked chickpeas here; canned chickpeas make a softer mixture that can break during frying.","Pulse chickpeas with onion, garlic, parsley, coriander, ground spices and salt into fine damp crumbs that hold when squeezed; do not puree smooth.","Mix in flour and baking powder, cover and refrigerate for 30 minutes. Shape into 16 small balls or thick discs.","Heat oil to 175°C and fry in batches for 4–5 minutes until deep golden and fully cooked inside. Drain and test one centre before finishing the batch.","Whisk tahini with lemon juice and measured water to a smooth sauce. Slice tomato and cucumber and warm pita briefly.","Split pita pockets and fill with falafel, vegetables and tahini sauce. Serve immediately."],"tips":["Allow 12–18 hours soaking plus 30 minutes chilling separately."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Falafel Pita","src":"/photos/falafel-pita-1200.webp","small":"/photos/falafel-pita-600.webp","width":1200,"height":800,"alt":"Falafel Pita served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Falafel_in_a_pita.jpg","title":"File:Falafel in a pita.jpg","author":"Israel_photo_gallery","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":853,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-spring-roll','{"id":"vegetable-spring-roll","name":"Vegetable Spring Roll","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless spring roll wrappers","qty":250,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cabbage","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":70,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":15,"unit":"ml","group":"Grains","scale":"linear"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"plain flour","qty":30,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":45,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Finely shred cabbage, carrot and capsicum. Slice spring onion and mince garlic.","Heat 25 ml oil in a wok, stir-fry garlic and spring onion whites for 30 seconds, then add vegetables and toss for 4–5 minutes.","Add soy sauce, vinegar and pepper and cook until excess moisture evaporates. Add spring onion greens and cool the filling completely.","Mix flour and water to a thick sealing paste. Place a wrapper as a diamond, put a small amount of filling near one corner, fold sides inward and roll tightly, sealing the tip with paste.","Heat oil to 175°C. Fry sealed rolls in batches for 3–4 minutes until golden and crisp, turning carefully.","Drain on a rack and serve hot. Keep uncooked wrappers covered to prevent drying and splitting."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Spring Roll","src":"/photos/vegetable-spring-roll-1200.webp","small":"/photos/vegetable-spring-roll-600.webp","width":1200,"height":595,"alt":"Vegetable Spring Roll — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Vegetable_spring_roll.jpg","title":"File:Vegetable spring roll.jpg","author":"Eka Samkharadze","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1884,"sourceHeight":935,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aam-panna','{"id":"aam-panna","name":"Aam Panna","baseServings":4,"batchSize":50,"ingredients":[{"name":"raw green mango","qty":600,"unit":"g","group":"Fruits","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"jaggery","qty":130,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"roasted cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mint","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash green mangoes and simmer whole in enough water to cover for 20–25 minutes until soft; this cooking water is separate from the measured drinking water.","Cool until safe to handle, peel and scrape the pulp away from the stones. Discard skin and stones.","Dissolve jaggery in 200 ml warm measured water and strain if gritty.","Blend mango pulp with jaggery water, mint, cumin and black salt until smooth.","Stir in the remaining chilled drinking water. Taste and adjust sweetness or dilution because raw mango acidity varies.","Refrigerate until cold and serve in four glasses, stirring before pouring."],"tips":["Cooling and chilling time are additional."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Aam Panna","src":"/photos/aam-panna-1200.webp","small":"/photos/aam-panna-600.webp","width":1200,"height":800,"alt":"Aam Panna served ready to eat","kind":"generated","title":"Aam Panna","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1536,"sourceHeight":1024,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pineapple-mint-cooler','{"id":"pineapple-mint-cooler","name":"Pineapple Mint Cooler","baseServings":4,"batchSize":50,"ingredients":[{"name":"pineapple flesh","qty":650,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mint","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lime juice","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":60,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ice","qty":200,"unit":"g","group":"Other","scale":"linear"}],"steps":["Peel pineapple, remove the eyes and hard core and weigh the edible flesh. Wash mint and remove tough stems.","Dissolve sugar in 100 ml warm measured water, then cool completely.","Blend pineapple with mint, lime juice, cooled syrup and remaining water until smooth.","Strain through a coarse sieve if you prefer a lighter drink; leave some pulp for a fuller texture.","Taste and adjust lime or sweetness to the ripeness of the pineapple.","Divide ice among four glasses, pour in the cooler and serve immediately."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pineapple Mint Cooler","src":"/photos/pineapple-mint-cooler-1200.webp","small":"/photos/pineapple-mint-cooler-600.webp","width":1200,"height":900,"alt":"Pineapple Mint Cooler served ready to eat","kind":"generated","title":"Pineapple Mint Cooler","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-banana-pancakes','{"id":"eggless-banana-pancakes","name":"Eggless Banana Pancakes","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"ripe banana flesh","qty":220,"unit":"g","group":"Fruits","scale":"linear"},{"name":"milk","qty":300,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"baking powder","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mash banana until smooth and whisk with milk, vanilla and 15 ml oil.","Mix flour, baking powder, sugar and salt in another bowl.","Fold wet and dry ingredients together just until no dry flour remains; a few small lumps are fine. Rest for 5 minutes.","Heat a non-stick skillet over medium-low heat and brush lightly with remaining oil. Pour small ladlefuls into 10 cm rounds.","Cook for 2–3 minutes until bubbles appear and the edges set, then flip and cook for another 1–2 minutes until the centre is cooked.","Repeat to make about 12 small pancakes. Serve warm; toppings are optional and separate from these quantities."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Banana Pancakes","src":"/photos/eggless-banana-pancakes-1200.webp","small":"/photos/eggless-banana-pancakes-600.webp","width":1200,"height":900,"alt":"Eggless Banana Pancakes served ready to eat","kind":"generated","title":"Eggless Banana Pancakes","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-waffles','{"id":"eggless-waffles","name":"Eggless Waffles","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"cornflour starch","qty":30,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":350,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"sugar","qty":45,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"baking powder","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat a waffle iron following its instructions and grease lightly if required.","Whisk flour, starch, sugar, baking powder and salt together.","Whisk milk, oil and vanilla separately, then fold into the dry mixture until just combined. Rest for 5 minutes.","Pour the amount of batter recommended for the waffle iron into its centre, leaving room for expansion, and close gently.","Cook for 4–6 minutes or until the iron signals and the waffle is golden and releases easily. Avoid opening too early, which can tear it.","Keep cooked waffles on a rack in a 100°C oven while finishing the batch so they stay crisp. Serve immediately."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Waffles","src":"/photos/eggless-waffles-1200.webp","small":"/photos/eggless-waffles-600.webp","width":1200,"height":900,"alt":"Eggless Waffles served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Waffles_with_Strawberries.jpg","title":"File:Waffles with Strawberries.jpg","author":"Parkerman & Christie from San Diego, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-suji-toast','{"id":"vegetable-suji-toast","name":"Vegetable Suji Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless bread","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Mix semolina, curd and water and rest for 15 minutes until the grains hydrate.","Grate carrot and finely chop capsicum, onion and coriander. Fold into the semolina mixture with salt; it should be thick and spreadable.","Spread a thin even layer over one side of each bread slice, keeping the topping no more than about 4 mm thick.","Heat a little oil in a non-stick pan over medium-low heat. Place bread topping-side down and cook for 3–4 minutes until golden and set.","Turn and toast the bread side for 1–2 minutes, adding a little oil if needed. Check that the semolina layer is cooked through.","Cut into triangles and serve hot. Repeat in batches without crowding the pan."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Suji Toast","src":"/photos/vegetable-suji-toast-1200.webp","small":"/photos/vegetable-suji-toast-600.webp","width":1200,"height":900,"alt":"Vegetable Suji Toast served ready to eat","kind":"generated","title":"Vegetable Suji Toast","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-quesadilla','{"id":"vegetable-quesadilla","name":"Vegetable Quesadilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sweet corn","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"cooked black beans","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"vegetarian cheese","qty":220,"unit":"g","group":"Dairy","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Dice capsicum and onion finely and drain cooked black beans and corn.","Heat half the oil and soften onion and capsicum for 6 minutes. Add beans, corn, cumin, paprika and salt and cook for 3 minutes until excess moisture evaporates.","Place a tortilla on a board, scatter some grated vegetarian cheese over one half, add a thin layer of filling and more cheese, then fold over.","Heat a heavy skillet over medium heat and brush lightly with remaining oil.","Cook each filled tortilla for 2–3 minutes per side until golden and cheese is melted, pressing gently with a spatula.","Rest for 1 minute, cut into wedges and serve hot."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Quesadilla","src":"/photos/vegetable-quesadilla-1200.webp","small":"/photos/vegetable-quesadilla-600.webp","width":1200,"height":900,"alt":"Vegetable Quesadilla — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Vegetable_quesadilla.jpg","title":"File:Vegetable quesadilla.jpg","author":"StellarD","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":1240,"sourceHeight":930,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sabzi-wrap','{"id":"sabzi-wrap","name":"Sabzi Wrap","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"cooked mixed vegetable sabzi","qty":700,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":150,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mint","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Use cooked vegetarian sabzi with known ingredients that was cooled promptly and refrigerated. Chop large pieces smaller and remove any whole spice sticks.","Reheat sabzi in a pan until steaming hot throughout; cook off excess gravy so the filling does not soak the wrap.","Whisk curd with cumin, chopped mint and salt. Cut cucumber into thin sticks and pat dry.","Warm tortillas in a dry pan for 20 seconds per side until flexible.","Spread a little mint curd on each, add hot sabzi and cucumber, fold the sides inward and roll tightly.","Brush with oil and toast seam-side down for 1–2 minutes, then turn briefly. Serve immediately."],"tips":["This leftover recipe depends on already-cooked sabzi; its dietary suitability depends on all ingredients in that sabzi."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('khakhra-with-curd','{"id":"khakhra-with-curd","name":"Khakhra with Curd","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"curd","qty":600,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"roasted cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Mix flour, cumin and 3 g salt. Rub in 15 ml oil and add water gradually to form a firm smooth dough; cover for 20 minutes.","Divide into 12 balls and roll each as thinly as possible using minimal flour for dusting.","Cook each on a medium-hot tawa for 20–30 seconds per side until just set, then lower the heat.","Brush lightly with remaining oil and press with a clean folded cloth or khakhra press, turning repeatedly for 2–3 minutes until uniformly crisp and golden.","Cool completely on a rack; trapped steam makes khakhra soft. Whisk curd with remaining salt and roasted cumin.","Serve three khakhra per portion with a bowl of curd alongside. Store any extra khakhra airtight once cold."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Khakhra with Curd","src":"/photos/khakhra-with-curd-1200.webp","small":"/photos/khakhra-with-curd-600.webp","width":1200,"height":900,"alt":"Khakhra with Curd served ready to eat","kind":"generated","title":"Khakhra with Curd","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dabeli','{"id":"dabeli","name":"Dabeli","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"boiled potato","qty":600,"unit":"g","group":"Packaged","scale":"linear"},{"name":"dabeli masala","qty":18,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"butter","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic chutney","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"roasted peanuts","qty":80,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"pomegranate arils","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Mash peeled boiled potatoes and finely chop onion and coriander.","Heat oil, stir dabeli masala for 20 seconds, then add potato, water, salt and half the tamarind chutney. Cook for 4–5 minutes until soft and spreadable.","Spread potato filling in a shallow dish and scatter half the peanuts, pomegranate and coriander over it.","Split pav and spread the insides with garlic chutney and remaining tamarind chutney.","Fill with potato mixture, onion and remaining peanuts and pomegranate. Toast the filled buns on a tawa with butter for 1–2 minutes per side.","Press the open edges into sev and serve immediately. Check spice mixes and chutneys for allergens and exclusions."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dabeli","src":"/photos/dabeli-1200.webp","small":"/photos/dabeli-600.webp","width":1200,"height":900,"alt":"Dabeli served ready to eat","kind":"generated","title":"Dabeli","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-sushi-rolls','{"id":"vegetarian-sushi-rolls","name":"Vegetarian Sushi Rolls","baseServings":4,"batchSize":20,"ingredients":[{"name":"sushi rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":390,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"rice vinegar","qty":50,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"nori sheets","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"avocado flesh","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":40,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rinse sushi rice several times, drain for 10 minutes and cook with measured water according to the rice packet, usually covered on low heat for 12–15 minutes followed by 10 minutes resting.","Dissolve sugar and salt in rice vinegar. Fold into hot rice with a slicing motion and spread in a shallow bowl to cool to room temperature; do not mash.","Cut cucumber, carrot and avocado into thin long strips. Steam carrot for 2–3 minutes if you prefer it softer, then cool and dry.","Place a nori sheet shiny-side down on a bamboo mat. With damp hands spread a thin layer of rice over it, leaving 2 cm bare at the far edge.","Lay vegetable strips across the near third. Roll firmly with the mat, tucking the filling in, and seal the bare nori edge with a little water.","Repeat for four rolls. Slice each into six pieces using a sharp damp knife and serve promptly with soy sauce; use only the listed vegetarian fillings and eggless condiments."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-pakwan','{"id":"dal-pakwan","name":"Dal Pakwan","baseServings":4,"batchSize":20,"ingredients":[{"name":"chana dal","qty":260,"unit":"g","group":"Pulses","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dried mango powder","qty":4,"unit":"g","group":"Fruits","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"plain flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse chana dal and soak for 1 hour. Drain and simmer with 1000 ml fresh water, turmeric and 4 g salt for 45–55 minutes until tender but still mostly whole.","Mix flour, semolina, 40 ml oil, remaining salt and about 130 ml water into a firm dough. Cover and rest for 20 minutes.","Heat remaining 30 ml oil, sizzle cumin, soften chopped onion for 6 minutes and add chopped tomato for 7 minutes. Add chilli and dried mango powder, then stir this masala into the cooked dal and simmer for 5 minutes.","Divide dough into eight balls, roll into thin rounds and prick all over with a fork to stop them puffing.","Fry pakwan in oil at 165–170°C for 2–3 minutes per side until crisp and golden, then drain.","Adjust dal with remaining measured water if too thick, finish with coriander and serve with crisp pakwan alongside."],"tips":["Allow 1 hour soaking separately; keep the pakwan dry until serving."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Pakwan","src":"/photos/dal-pakwan-1200.webp","small":"/photos/dal-pakwan-600.webp","width":1200,"height":900,"alt":"Dal Pakwan — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Dal_Pakwan_-_Sindhi_Food_-_4.jpg","title":"File:Dal Pakwan - Sindhi Food - 4.jpg","author":"Urvi Yagnik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5664,"sourceHeight":4248,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fafda-with-kadhi','{"id":"fafda-with-kadhi","name":"Fafda with Kadhi","baseServings":4,"batchSize":20,"ingredients":[{"name":"gram flour","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"ajwain","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["For fafda, mix 250 g gram flour, ajwain, baking soda, 4 g salt and 25 ml oil. Add about 100 ml water gradually and knead a smooth firm dough; rest covered for 15 minutes.","For kadhi, whisk remaining gram flour, curd, sugar, turmeric, remaining salt and 400 ml water until smooth.","Heat remaining 10 ml oil, pop mustard seeds and add curry leaves. Stir in the curd mixture and simmer for 15–20 minutes, stirring until the flour is cooked and the sauce is pourable.","Divide fafda dough into small logs. Press each lengthwise with the heel of your palm on a lightly oiled board into a thin strip and lift with a flat scraper.","Fry strips in oil at 170°C in small batches for 1–2 minutes until crisp but still pale golden. Drain carefully without breaking.","Serve fafda with warm kadhi. Keep the strips and sauce separate until eating."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Fafda with Kadhi","src":"/photos/fafda-with-kadhi-1200.webp","small":"/photos/fafda-with-kadhi-600.webp","width":1200,"height":675,"alt":"Fafda with Kadhi served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Fanfada_and_kadhi(sweet)_with_fried_green_chillis(garnished_with_spices).jpg","title":"File:Fanfada and kadhi(sweet) with fried green chillis(garnished with spices).jpg","author":"Rishabhbenganijain","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":720,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kadhi-pakora','{"id":"kadhi-pakora","name":"Kadhi Pakora","baseServings":4,"batchSize":50,"ingredients":[{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fenugreek seeds","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"dried red chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":35,"unit":"g","group":"Spices","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk curd, gram flour, water, turmeric and salt until smooth with no flour lumps.","Heat half the ghee in a deep pan, sizzle cumin and fenugreek briefly, then lower the heat.","Pour in the curd mixture gradually while stirring. Bring to a gentle boil, stirring continuously so the flour does not settle.","Reduce heat and simmer for 25–30 minutes, stirring often, until the gram flour is cooked and the kadhi is smooth and pourable.","For pakora, thinly slice the extra onion and mix with the extra gram flour, coriander and salt. Add the extra water gradually to form a thick coating batter.","Heat frying oil to 170°C and drop small spoonfuls carefully. Fry for 4–5 minutes until golden and cooked through, then drain.","Heat remaining ghee, add dried chilli, turn off the heat and stir in chilli powder briefly. Pour this tempering over the kadhi.","Finish with coriander and serve hot. Add boiling water if it thickens excessively during simmering.","Add pakoras to the finished kadhi and simmer for 3–4 minutes to soften slightly. Serve hot; add them later if you prefer a firmer texture."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kadhi Pakora","src":"/photos/kadhi-pakora-1200.webp","small":"/photos/kadhi-pakora-600.webp","width":1200,"height":900,"alt":"Kadhi Pakora served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Kadhi_Pakode.jpg","title":"File:Kadhi Pakode.jpg","author":"Neerajmadhavan","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('raj-kachori','{"id":"raj-kachori","name":"Raj Kachori","baseServings":4,"batchSize":20,"ingredients":[{"name":"semolina","qty":160,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"plain flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"gram flour","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cooked moong","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"pomegranate arils","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix semolina, flours and salt, rub in 25 ml oil and add water gradually to make a firm smooth dough. Cover and rest for 25 minutes.","Divide into 8 balls and roll each into an even 11–12 cm round without making the centre too thin.","Heat oil to 175–180°C. Slide in a round and press gently with a slotted spoon to help it puff, then turn and fry for 2–3 minutes until crisp and golden. Drain and cool completely.","Dice boiled potato, drain fully cooked moong and whisk curd until smooth. Set out chutneys and toppings.","Crack a hole in the top of each cooled shell. Fill with potato, moong and curd, then drizzle both chutneys.","Finish with sev, pomegranate, chaat masala and coriander. Serve immediately, two small filled kachori per portion."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Raj Kachori","src":"/photos/raj-kachori-1200.webp","small":"/photos/raj-kachori-600.webp","width":1200,"height":900,"alt":"Raj Kachori — photographed serving","source":"https://commons.wikimedia.org/wiki/File:RAJ_KACHORI.jpg","title":"File:RAJ KACHORI.jpg","author":"SAGAR1511","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3264,"sourceHeight":2448,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aloo-paratha','{"id":"aloo-paratha","name":"Aloo Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 200 ml water for dough. Simmer whole potatoes in the remaining water for 20–25 minutes until a knife passes through; drain, peel and cool.","Knead 300 g flour, 4 g salt and the reserved 200 ml water into soft dough; cover 20 minutes. Keep 30 g flour for rolling.","Mash potatoes without lumps. Mix in finely chopped chilli and coriander, cumin, mango powder, chilli powder and remaining salt; let steam escape completely.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":60,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gobi-paratha','{"id":"gobi-paratha","name":"Gobi Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"cauliflower","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Finely grate washed, thoroughly dried cauliflower. Sauté in 10 g ghee for 7–9 minutes until its moisture evaporates; spread on a plate to cool.","Mix cooled cauliflower with finely grated ginger, chopped chilli and coriander, carom seeds, mango powder and remaining salt immediately before stuffing.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":50,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-paratha','{"id":"paneer-paratha","name":"Paneer Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"paneer","qty":300,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Pat paneer dry and crumble finely. Mix with chopped chilli and coriander, cumin, mango powder and the remaining salt; avoid large pieces that tear dough.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhatura','{"id":"bhatura","name":"Bhatura","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"baking powder","qty":4,"unit":"g","group":"Bakery","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Bakery","scale":"linear"},{"name":"oil","qty":650,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Mix 300 g flour with sugar, salt, baking powder and baking soda. Reserve 30 g flour for rolling; measure 20 ml oil from the total.","Add curd and 20 ml oil. Add water gradually and knead 8 minutes into a smooth, soft dough; cover and rest for 2 hours.","Divide into eight smooth balls. Dust sparingly and roll each into an even oval about 3 mm thick; thick edges prevent full puffing.","Heat the remaining oil in a deep heavy pan to 180°C, leaving ample space above the oil. Fry one bread at a time.","Slide in a bhatura carefully and gently press with a slotted spoon until it puffs. Turn after 30–45 seconds and fry the other side golden.","Lift and drain on a rack. Adjust heat between batches to keep the oil near 180°C; serve immediately while puffed and soft inside."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"2 hours dough resting","status":"complete","notes":"Makes eight bhature. Oil is the frying medium; the full quantity is not consumed. This version uses chemical leavening."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('missi-roti','{"id":"missi-roti","name":"Missi Roti","baseServings":4,"batchSize":8,"ingredients":[{"name":"gram flour","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"whole wheat flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Finely chop onion, chilli and coriander. Mix gram flour with 150 g wheat flour, carom seeds, turmeric and salt; reserve 30 g wheat flour for rolling.","Add chopped vegetables and 10 g ghee. Add water gradually, kneading a soft but non-sticky dough; cover for 20 minutes.","Divide into eight portions and smooth each ball. Dust lightly with reserved flour and roll to 14–15 cm; keep the edges evenly thick.","Place a roti on a medium-hot heavy tawa. Cook about 90 seconds until the surface loses its wet shine and small bubbles form.","Turn, spread a little remaining ghee and cook another minute. Turn again and press around the edges until both sides develop brown spots.","Check one torn edge: there should be no moist flour layer or raw gram-flour smell. Cook remaining rotis and keep covered loosely until serving."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tandoori-roti','{"id":"tandoori-roti","name":"Tandoori Roti","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":20,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour and 20 ml water. Knead remaining flour, salt, curd and remaining water for 6–8 minutes into a smooth, slightly firm dough.","Cover dough for 30 minutes. Preheat the oven to 250°C with a heavy oven-safe baking tray inside for at least 25 minutes.","Divide dough into eight balls. Roll with reserved flour to ovals about 4 mm thick; lightly brush one side with the reserved water.","Using oven gloves, place two or three rotis wet-side down on the hot tray. Bake 3–5 minutes until puffed and the underside is set.","Finish under the oven grill for 30–60 seconds if needed for brown blisters; watch continuously and keep the bread clear of the heating element.","Brush baked rotis with ghee. Tear one to check there is no gummy centre, and serve immediately; reheat the tray briefly between batches."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":35,"passiveTime":"30 minutes dough resting; oven preheating overlaps","status":"complete","notes":"Home-oven adaptation of tandoori roti; eight rotis. A domestic oven gives browned blisters without a traditional tandoor."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-paratha','{"id":"methi-paratha","name":"Methi Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"fenugreek leaves","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"curd","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":50,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Pick fenugreek leaves from tough stems, wash well and dry thoroughly. Chop finely; reserve 30 g flour for rolling.","Mix remaining flour with leaves, salt, carom seeds, turmeric and chilli powder. Add curd, 10 g ghee and water gradually to make soft dough.","Rest covered for 20 minutes, then divide into eight balls. Roll one ball into a small disc and spread a thin film of ghee.","Fold the disc in half, grease lightly and fold again into a triangle. Roll gently with reserved flour to about 3 mm thick.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mooli-paratha','{"id":"mooli-paratha","name":"Mooli Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"radish","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Grate peeled radish, toss with remaining salt and stand for 10 minutes. Squeeze very firmly in a clean cloth; discard the extracted liquid.","Mix squeezed radish with finely chopped chilli and coriander, carom seeds and chilli powder. Stuff immediately, before the filling releases more moisture.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":50,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('amritsari-kulcha','{"id":"amritsari-kulcha","name":"Amritsari Kulcha","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"potato","qty":400,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander powder","qty":4,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"baking powder","qty":4,"unit":"g","group":"Bakery","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Bakery","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"},{"name":"nigella seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Reserve 100 ml water. Mix 300 g flour, curd, sugar, 4 g salt, baking powder, soda and 10 g ghee; knead with reserved water and rest covered 2 hours.","Boil potatoes in remaining water until knife-tender, about 25 minutes. Drain, peel, cool and mash; mix with finely chopped onion, chilli, coriander and remaining spices and salt.","Preheat an oven with a heavy oven-safe tray to 250°C for 25 minutes. Divide dough and cooled filling into eight portions.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Dust with remaining flour and roll filled balls to 15 cm, about 5 mm thick. Press nigella seeds onto the tops.","Bake two at a time on the hot tray for 6–8 minutes until puffed and golden underneath. Grill tops briefly for brown spots, watching closely.","Brush with remaining ghee and serve hot. Check the edge of the first kulcha is cooked through, without a sticky flour layer around the filling."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":65,"passiveTime":"2 hours dough resting","status":"complete","notes":"Makes eight stuffed kulchas using a home oven. Onion and potato are traditional ingredients here; household choices determine suitability."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('malabar-parotta','{"id":"malabar-parotta","name":"Malabar Parotta","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":400,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":70,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Mix flour, sugar and salt. Add water and 15 ml oil; knead vigorously for 10–12 minutes until very smooth and stretchy rather than sticky.","Coat dough with 5 ml oil and rest covered for 1 hour. Divide into eight balls, lightly oil and rest another 20 minutes.","Oil the worktop lightly. Stretch each ball into a very thin sheet using oiled hands; small tears are acceptable. Spread a little measured oil over it.","Pleat the sheet into a long ribbon, coil loosely and tuck the end underneath. Rest the coils covered for 15 minutes before gently flattening to 15 cm.","Cook on a medium-hot heavy tawa for about 2 minutes per side, using remaining oil sparingly. Flip repeatedly until layered edges are cooked and golden spots form.","Stack two or three hot parottas and press their edges inward with clean cloth-covered hands to separate the layers. Serve immediately while tender inside."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":55,"passiveTime":"1 hour 35 minutes total resting","status":"complete","notes":"Makes eight layered parottas. This traditional-style version uses flour, water and oil without added dairy."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kalakand','{"id":"kalakand","name":"Kalakand","baseServings":4,"batchSize":12,"ingredients":[{"name":"whole milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"paneer","qty":250,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":10,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small square tin with 3 g ghee. Crumble fresh paneer into fine, soft grains; do not knead it into a smooth paste.","Bring milk to a boil in a wide heavy pan. Reduce to medium-low and simmer 20–30 minutes, scraping the sides, until approximately half remains.","Add crumbled paneer and stir gently. Cook 10–15 minutes, frequently scraping the bottom, until the mixture is thick but still moist.","Add sugar and remaining ghee. Stir on low heat until released liquid evaporates and the mixture gathers together, leaving a thin moist trail on the pan.","Switch off and mix in cardamom. Spread into the greased tin about 2 cm thick, level lightly and press chopped pistachios onto the surface.","Cool for 30 minutes, then refrigerate for 2 hours until softly set. Cut into twelve pieces; the inside should remain moist and grainy, not rubbery."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":60,"passiveTime":"30 minutes cooling and 2 hours chilling","status":"complete","notes":"Makes twelve small pieces, three per serving. Cool promptly, refrigerate in a covered container and use within 3 days."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('motichoor-ladoo','{"id":"motichoor-ladoo","name":"Motichoor Ladoo","baseServings":4,"batchSize":12,"ingredients":[{"name":"gram flour","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":330,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Dairy","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Other","scale":"linear"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"melon seeds","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Whisk gram flour with 230 ml water into a smooth, thin pouring batter. Rest 10 minutes; ready a fine-hole boondi ladle and a draining sieve.","Heat oil to 170°C in a deep pan. Hold the boondi ladle just above it and tap small ladlefuls of batter through, keeping hands clear.","Fry tiny pearls for 30–45 seconds, just until set without becoming crisp. Drain promptly and wipe the ladle clean between batches.","Boil sugar, saffron and remaining 100 ml water until a cooled drop draws one fine thread. Test only a cooled drop, never hot syrup, and turn off the heat at this stage.","Stir boondi into hot syrup with ghee, cardamom and melon seeds. Cover for 10 minutes so the pearls absorb syrup; stir once halfway through.","If pearls are too large, pulse the warm mixture very briefly, keeping visible grains. Let it cool until comfortable to handle, then press into twelve firm ladoos."],"tips":["A fine-hole ladle makes the characteristic tiny pearls; do not fry the boondi until crunchy."],"substitutions":[],"prepTime":55,"passiveTime":"10 minutes batter resting and 10 minutes syrup absorption","status":"complete","notes":"Makes twelve small ladoos. The oil quantity is a frying bath, not the amount eaten. Refrigerate cooled ladoos and use within 3 days."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-ladoo','{"id":"rava-ladoo","name":"Rava Ladoo","baseServings":4,"batchSize":12,"ingredients":[{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"desiccated coconut","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"powdered sugar","qty":130,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":85,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":50,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"cashew","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Heat 15 g ghee in a heavy pan. Fry chopped cashews until pale golden, add raisins briefly until plump, and lift both onto a plate.","Add remaining ghee and semolina to the pan. Roast on low heat for 10–12 minutes, stirring continuously, until fragrant but still pale.","Add coconut and roast for 2 minutes more. Transfer to a broad bowl and cool until warm; very hot semolina will melt the sugar.","Mix in powdered sugar, cardamom and fried nuts and raisins. Rub gently between fingers to distribute the fat evenly without compacting the entire mixture.","Warm the measured milk and sprinkle it gradually over the mixture. Rest 5 minutes; a squeezed handful should hold together without dripping or feeling wet.","Divide into twelve portions and press firmly into balls while warm. Cool fully, then refrigerate because milk has been added; bring portions to room temperature before serving."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":35,"passiveTime":"5 minutes absorption and 30 minutes cooling","status":"complete","notes":"Makes twelve small pieces, three per serving. Cool promptly, refrigerate in a covered container and use within 3 days."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('doodh-peda','{"id":"doodh-peda","name":"Doodh Peda","baseServings":4,"batchSize":12,"ingredients":[{"name":"unsweetened mawa","qty":300,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":60,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":90,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":12,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Warm 30 ml milk and steep crushed saffron in it for 10 minutes. Grease a plate lightly using a little of the measured ghee.","Crumble the mawa finely into a heavy pan and mix with the remaining milk. Add sugar and the remaining ghee, then place over low heat and stir until evenly combined.","Stir continuously for 8–12 minutes, scraping the base and corners. Add saffron milk and cardamom once the mixture becomes a thick paste.","Continue cooking gently until the mixture pulls away as a soft mass. Cool a small dab on a plate: it should roll without sticking badly.","Transfer to the greased plate and cool until comfortably warm, about 15 minutes. Do not overcook to a dry crumble or the pedas will become hard.","Divide into twelve balls, flatten gently and press chopped pistachios into shallow central dents. Cool completely before refrigerating in a covered container."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":30,"passiveTime":"10 minutes saffron soaking and 15 minutes cooling","status":"complete","notes":"Makes twelve small saffron milk pedas using milk powder for a practical home method. Refrigerate and use within 3 days."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('soan-papdi','{"id":"soan-papdi","name":"Soan Papdi","baseServings":4,"batchSize":12,"ingredients":[{"name":"gram flour","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"plain wheat flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":240,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon juice","qty":2,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Prepare a heatproof silicone mat, two sturdy spatulas and a small greased tin. Sift both flours; use 5 g ghee to grease the mat and tin.","Roast both flours in remaining ghee over low heat for 15–18 minutes until nutty and pale golden. Mix in cardamom and keep the flour paste warm.","Dissolve sugar in water, add lemon juice and boil without stirring to 140°C on a sugar thermometer. Do not test hot syrup with bare fingers.","Pour syrup carefully onto the mat. Using spatulas, fold edges inward as it cools, until the sugar is a pliable mass rather than flowing liquid.","When safe to handle with food-safe heat-resistant gloves, stretch and fold the sugar until opaque. Form a ring; never touch sugar that still burns through protection.","Coat the ring with warm roasted flour paste. Stretch wider, twist into a figure eight and fold together; repeat, coating strands with paste each time.","Continue until many fine strands separate and most paste is incorporated. Gather the strands into the tin without crushing them; scatter pistachios and press only lightly.","Score twelve pieces while just warm and cool fully for 1 hour before lifting. Store airtight in a cool, dry place; moisture makes the strands sticky."],"tips":["Keep the flour paste warm and work steadily; cold sugar snaps instead of forming fine fibres."],"substitutions":[],"prepTime":65,"passiveTime":"1 hour cooling and setting","status":"complete","notes":"Makes twelve small pieces. An advanced pulled-sugar recipe requiring a sugar thermometer, heatproof work surface and food-safe heat protection; texture depends on repeated pulling."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('milk-cake','{"id":"milk-cake","name":"Milk Cake","baseServings":4,"batchSize":40,"ingredients":[{"name":"whole milk","qty":1500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":120,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":10,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":20,"unit":"ml","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small deep metal tin with a little measured ghee. Mix lemon juice with the water. Use a wide heavy pan so milk can reduce without scorching.","Bring milk to a boil, then simmer for 35–45 minutes, stirring and scraping the base and sides, until roughly half remains. Keep returning the soft milk solids to the pan.","Add diluted lemon gradually while stirring until small grains form in the thick milk. Stop adding once grainy; do not separate it into dry curds and clear whey.","Add sugar and cook over low heat for 20–30 minutes, stirring constantly as it thickens. Add the remaining ghee gradually; the mixture should become beige, grainy and pull away from the pan.","Mix in cardamom and pack firmly into the greased tin; scatter chopped pistachio on top. Cover loosely and cool for 45 minutes, then refrigerate until firm for at least 2 hours.","Unmould with a thin knife and cut into small pieces. The texture should be moist and granular, with a deeper colour possible in the centre; keep leftovers refrigerated."],"tips":[],"substitutions":[],"status":"complete","prepTime":95,"passiveTime":"Cool for 45 minutes, then chill for at least 2 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gujiya','{"id":"gujiya","name":"Gujiya","baseServings":4,"batchSize":12,"ingredients":[{"name":"plain flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear"},{"name":"unsweetened mawa","qty":120,"unit":"g","group":"Dairy","scale":"linear"},{"name":"desiccated coconut","qty":30,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"powdered sugar","qty":50,"unit":"g","group":"Packaged","scale":"linear"},{"name":"almond","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rub 30 g ghee into the flour until it resembles breadcrumbs and holds when squeezed. Add water gradually to form a firm dough; cover and rest for 25 minutes.","Crumble mawa and roast in the remaining ghee over low heat for 5–7 minutes until fragrant and slightly dry. Add coconut and chopped almonds for 1 minute, then cool completely.","Stir sugar, raisins and cardamom into the cool filling. Divide dough into 8 balls and roll each into a thin disc, keeping the unused dough covered to prevent drying.","Divide filling between discs, leaving a clean border. Moisten the rim lightly with water, fold into a half-moon and press and crimp firmly; trapped filling at the seam can make it open.","Heat frying oil to about 160°C in a deep pan no more than half full. Fry in batches for 12–15 minutes, turning gently, until evenly golden and the pastry feels crisp.","Drain on a rack and cool before serving; the filling stays very hot. Frying oil is a cooking medium, not an amount to consume. Refrigerate cooled leftovers because the filling contains dairy."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Rest dough for 25 minutes; cool the filling completely before shaping.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('modak','{"id":"modak","name":"Modak","baseServings":4,"batchSize":12,"ingredients":[{"name":"rice flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh coconut","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"jaggery","qty":110,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Grate coconut and jaggery. Heat 5 g ghee, add both and cook over medium-low heat for 6–8 minutes until melted together and moist but not watery. Add cardamom and cool.","Boil the measured water with salt and 5 g ghee. Turn heat low, add rice flour all at once and stir firmly until no dry flour remains; cover off heat for 5 minutes.","When warm enough to handle, knead the dough until smooth, using damp hands. Divide into 8 balls and keep covered; if edges crack when pressed, knead in a few drops of warm water.","Use the remaining ghee on hands and steamer plate. Flatten each ball into a cup, add an equal share of filling, pleat the rim and bring the pleats together into a sealed pointed top.","Bring separate steamer water to a boil below the plate, without touching the modaks. Steam covered for 12–15 minutes until the shells look slightly glossy and feel set.","Rest off heat for 5 minutes before lifting with a damp spoon. Serve warm, taking care with the hot filling; refrigerate any cooled leftovers."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Rest dough for 5 minutes and steamed modaks for 5 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-barfi','{"id":"coconut-barfi","name":"Coconut Barfi","baseServings":4,"batchSize":40,"ingredients":[{"name":"fresh coconut","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"whole milk","qty":250,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":140,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small shallow tray with a little measured ghee. Finely grate the white coconut flesh, avoiding large hard pieces, and chop the pistachio.","Put coconut and milk in a heavy pan and cook over medium-low heat for 10–12 minutes, stirring, until coconut softens and most loose milk has evaporated.","Add sugar and the remaining ghee. The mixture will loosen first; keep stirring for 12–18 minutes until it forms a cohesive mass that leaves the sides, without browning.","Stir in cardamom. Spread promptly in the greased tray, flatten with a greased spoon and press pistachio onto the surface. Score into small squares while still warm.","Cool for 30 minutes, then refrigerate for 1 hour to set before separating the pieces. Keep chilled in a covered container because fresh coconut and milk spoil quickly."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Cool for 30 minutes, then refrigerate for 1 hour.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('balushahi','{"id":"balushahi","name":"Balushahi","baseServings":4,"batchSize":12,"ingredients":[{"name":"plain flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":60,"unit":"g","group":"Packaged","scale":"linear"},{"name":"plain curd","qty":50,"unit":"g","group":"Dairy","scale":"linear"},{"name":"baking soda","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":200,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":5,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mix flour and baking soda, then rub in ghee until crumbly. Fold in curd and up to 40 ml of the measured water just until a rough dough forms; do not knead smooth.","Cover and rest for 25 minutes. Divide into 8 pieces, shape gently into thick rounds and make a shallow central dent; retain the fine surface cracks that create flaky layers.","Dissolve sugar in the remaining 120 ml water and bring to a simmer. Cook until a cooled drop feels sticky and forms a thin thread when stretched; stir in lemon juice and cardamom and keep warm.","Heat frying oil to 140–150°C in a deep pan no more than half full. Lower in a batch carefully and fry slowly for 20–25 minutes, turning occasionally, until puffed and evenly golden.","Drain on a rack and let stand for 5 minutes. Break one test piece to check the centre is cooked and layered, not a wet flour paste; continue frying if necessary.","Dip the warm pieces in warm syrup for 2 minutes on each side. Lift onto a rack and cool until the glaze sets; the listed frying oil is a cooking medium, not a serving quantity."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Rest dough for 25 minutes; cool glazed sweets until set.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-fry','{"id":"dal-fry","name":"Dal Fry","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the dal until the water is fairly clear. Simmer with 900 ml water and turmeric for 35–45 minutes, partly covered, until the grains mash easily; stir and check the water level.","Finely chop onion, tomato, ginger and garlic. Heat ghee in a pan, sizzle cumin, then cook onion for 6–8 minutes until golden at the edges.","Add ginger and garlic and stir for 1 minute. Add tomato, chilli powder and salt; cook for 8 minutes until soft and the ghee appears at the edges.","Whisk the cooked dal lightly and add to the pan with the remaining 200 ml water. Simmer for 6–8 minutes, stirring, until the dal pours thickly from a spoon.","Stir in garam masala and chopped coriander. Taste and serve hot with rice or roti prepared separately; this recipe supplies the dal only."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chana-dal','{"id":"chana-dal","name":"Chana Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"chana dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse and soak the chana dal in plenty of water for 2 hours, then drain. Chop the tomato, ginger and chilli finely.","Bring the drained dal, turmeric and 1000 ml fresh water to a boil. Simmer partly covered for 45–55 minutes, until tender but still holding its shape.","Heat ghee in another pan and sizzle the cumin. Add ginger and chilli for 1 minute, then tomato, salt and chilli powder; cook for 7–8 minutes until pulpy.","Fold the tempering into the dal with the remaining 100 ml water. Simmer for 5 minutes and finish with coriander; the dal should be tender with a light gravy, not a paste."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak chana dal for 2 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('yellow-moong-dal','{"id":"yellow-moong-dal","name":"Yellow Moong Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1050,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the moong dal thoroughly and drain. Put it in a saucepan with 950 ml water and turmeric; bring to a boil and skim any heavy foam.","Simmer partly covered for 25–30 minutes, stirring occasionally, until the grains collapse when pressed. Whisk briefly for a soft, creamy consistency.","Heat ghee in a small pan and sizzle cumin. Add finely chopped ginger and chilli and stir for 1 minute without browning heavily. Pour the tempering into the dal carefully.","Add salt and the remaining 100 ml water, simmer for 3 minutes, then switch off. Stir in lemon juice and coriander; serve warm with separately prepared rice."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pindi-chole','{"id":"pindi-chole","name":"Pindi Chole","baseServings":4,"batchSize":40,"ingredients":[{"name":"dried chickpeas","qty":280,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1600,"unit":"ml","group":"Other","scale":"linear"},{"name":"black tea leaves","qty":4,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried pomegranate powder","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"amchur","qty":4,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":3,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak chickpeas in plenty of water for 8–12 hours in the refrigerator, then discard the soaking water and rinse. Tie the tea leaves securely in a clean food-safe muslin bag.","Boil chickpeas with the measured fresh water and tea bag, then simmer partly covered for 75–95 minutes until easily crushed. Add hot water if needed to keep them covered. Remove the tea bag.","Drain the chickpeas, saving 250 ml cooking liquid. Toss them with coriander powder, cumin powder, pomegranate powder, amchur, chilli powder, garam masala and salt.","Heat ghee in a wide pan, sizzle cumin seeds, then add sliced ginger and chilli for 1 minute. Add the spiced chickpeas and reserved liquid and cook for 10–12 minutes, turning gently.","Stop when the spices cling to the chickpeas and little free liquid remains. Check that the centres are completely tender and serve with separately prepared bread."],"tips":[],"substitutions":[],"status":"complete","prepTime":110,"passiveTime":"Soak chickpeas for 8–12 hours in the refrigerator.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lobia-masala','{"id":"lobia-masala","name":"Lobia Masala","baseServings":4,"batchSize":40,"ingredients":[{"name":"dried black-eyed peas","qty":280,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":240,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the black-eyed peas, soak for 4–6 hours and drain. Simmer in 1000 ml fresh water for 35–45 minutes until tender all the way through; keep the cooking liquid.","Finely chop the onion, tomato, ginger and garlic. Heat oil, sizzle cumin, and fry onion for 8 minutes until golden. Add ginger and garlic and cook for 1 minute.","Add tomato, turmeric, coriander powder, chilli powder and salt. Cook for 8–10 minutes, stirring, until the tomato becomes a thick paste and oil beads at the edges.","Add the cooked peas with their liquid and remaining 200 ml water. Simmer for 10 minutes; mash a spoonful against the pan to thicken the gravy, keeping most peas whole.","Stir in garam masala and chopped coriander. The curry should coat a spoon without being dry; serve hot with rice or roti prepared separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":"Soak black-eyed peas for 4–6 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('langar-wali-dal','{"id":"langar-wali-dal","name":"Langar wali Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"whole black urad","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chana dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1700,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse both dals and soak together in plenty of water for 8 hours in the refrigerator. Drain and put in a heavy saucepan with 1500 ml fresh water and turmeric.","Bring to a boil, then simmer partly covered for 90–110 minutes, stirring often. Add hot water as needed; both dals must crush easily without a chalky centre.","Heat ghee, sizzle cumin and cook finely chopped onion for 8 minutes until golden. Add minced ginger and garlic for 1 minute, then chopped tomato, chilli powder and salt.","Cook the tomato mixture for 8–10 minutes until glossy. Stir it into the dal with the remaining 200 ml water; mash a little dal and simmer for 10 minutes until creamy.","Finish with garam masala and coriander. Keep the consistency gently flowing rather than stiff; serve hot, with rice or flatbread cooked separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":125,"passiveTime":"Soak both dals for 8 hours in the refrigerator.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-methi','{"id":"dal-methi","name":"Dal Methi","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh fenugreek leaves","qty":180,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse the dal and simmer with turmeric and 950 ml water for 35–45 minutes until soft enough to mash. Stir occasionally and replenish water if the pan becomes dry.","Pick the fenugreek leaves, discard tough stems and wash thoroughly to remove grit. Chop the leaves, onion, garlic and tomato separately.","Heat ghee and sizzle cumin. Cook onion for 6 minutes, add garlic for 1 minute, then tomato, chilli powder and salt; cook for 6–8 minutes until pulpy.","Add fenugreek and stir for 4 minutes until wilted. Mix in the dal and remaining 150 ml water; simmer for 5 minutes, then switch off and add lemon juice."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dhuli-urad-dal','{"id":"dhuli-urad-dal","name":"Dhuli Urad Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"split white urad dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the urad dal gently, soak for 30 minutes and drain very well. Cut the ginger into fine strips and chop chilli and coriander.","Heat ghee in a wide pan with a lid. Sizzle cumin, add ginger and chilli for 1 minute, then stir in drained dal, turmeric and salt.","Add the measured water, bring to a simmer and cover. Cook on low heat for 18–22 minutes; check gently with a fork and avoid stirring hard, which breaks the grains.","When tender, uncover and evaporate any remaining water over low heat. Rest off heat for 5 minutes, fluff gently and finish with lemon and coriander; the grains should stay separate."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak for 30 minutes; rest after cooking for 5 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hare-chane-ki-sabzi','{"id":"hare-chane-ki-sabzi","name":"Hare Chane ki Sabzi","baseServings":4,"batchSize":40,"ingredients":[{"name":"fresh green chickpeas","qty":500,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Shell and rinse the green chickpeas; the measured weight is for shelled peas. Chop onion and tomato finely and mince ginger and garlic.","Heat oil and sizzle cumin. Cook onion for 7 minutes until golden, then add ginger and garlic for 1 minute. Add tomato, turmeric, coriander powder, chilli powder and salt.","Cook the masala for 8 minutes until thick and glossy. Stir in chickpeas and water, cover and simmer for 15–20 minutes until a pea crushes easily between a spoon and the pan.","Uncover and reduce excess liquid until the gravy coats the peas. Stir in garam masala and chopped coriander and serve hot with separately prepared roti."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mor-kuzhambu','{"id":"mor-kuzhambu","name":"Mor Kuzhambu","baseServings":4,"batchSize":40,"ingredients":[{"name":"plain curd","qty":500,"unit":"g","group":"Dairy","scale":"linear"},{"name":"ash gourd","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh coconut","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chana dal","qty":10,"unit":"g","group":"Pulses","scale":"linear"},{"name":"raw rice","qty":10,"unit":"g","group":"Grains","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"coconut oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak chana dal and rice for 20 minutes, then drain. Grind with coconut, cumin, green chilli and 100 ml of the measured water to a smooth paste.","Peel and deseed the ash gourd and cut into small cubes. Simmer with 250 ml water, turmeric and salt for 10–12 minutes until translucent and easily pierced.","Add the ground paste and simmer for 4 minutes, stirring to cook the soaked rice and dal. Whisk the curd separately with the remaining 100 ml water until smooth.","Turn the heat to its lowest setting and stir in the curd. Heat gently for 3–4 minutes, stirring, until steaming; do not allow a rolling boil or the curd may split.","Heat coconut oil in a small pan, pop mustard seeds and add dried chilli and curry leaves carefully. Pour over the curry, cover briefly and serve with separately cooked rice."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak rice and chana dal for 20 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-coriander-soup','{"id":"lemon-coriander-soup","name":"Lemon Coriander Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"cabbage","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear"},{"name":"cornflour starch","qty":12,"unit":"g","group":"Grains","scale":"linear"},{"name":"lemon juice","qty":35,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":30,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Finely chop the vegetables, ginger and garlic. Wash coriander well; chop the stems separately from the leaves. Mix cornflour with 50 ml of the measured cold water.","Heat oil and soften onion for 3 minutes without browning. Add ginger, garlic and coriander stems for 1 minute, then carrot and cabbage for 2 minutes.","Add the remaining water, salt and pepper. Simmer for 8 minutes until vegetables are tender with a little bite. Stir the slurry again, pour it in and simmer for 2 minutes until lightly glossy.","Turn off the heat and add lemon juice and coriander leaves. Taste and serve immediately; adding lemon at the end keeps the soup bright and fresh."],"tips":[],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('manchow-soup','{"id":"manchow-soup","name":"Manchow Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"cabbage","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"vinegar","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cornflour starch","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"eggless crispy noodles","qty":60,"unit":"g","group":"Grains","scale":"linear"}],"steps":["Finely chop cabbage, carrot, capsicum, ginger, garlic and chilli. Separate spring onion whites from greens. Mix cornflour with 60 ml of the measured cold water.","Heat oil in a saucepan. Stir-fry ginger, garlic, chilli and onion whites for 1 minute, then add the remaining chopped vegetables and stir over medium-high heat for 3 minutes.","Add the remaining water, soy sauce, pepper and salt. Simmer for 7 minutes until vegetables are tender but not mushy. Taste before adding any more salt because soy sauce is salty.","Stir the slurry and pour in while mixing. Simmer for 2–3 minutes until slightly thickened, add vinegar and onion greens, then divide into bowls. Add crispy noodles only at serving so they stay crunchy."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hot-and-sour-soup','{"id":"hot-and-sour-soup","name":"Hot and Sour Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"firm tofu","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cabbage","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1050,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"vinegar","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cornflour starch","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"white pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sesame oil","qty":5,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Cut tofu into narrow strips and shred cabbage and carrot. Chop ginger, garlic, chilli and spring onion, keeping the greens aside. Mix cornflour with 50 ml cold measured water.","Heat oil and stir-fry ginger, garlic, chilli and onion whites for 1 minute. Add carrot and cabbage and cook for 3 minutes, stirring to keep their texture.","Add remaining water, tofu, soy sauce, white pepper and salt. Simmer for 6–8 minutes; stir the slurry again and pour it in while mixing to avoid lumps.","Simmer for 2 minutes until lightly thickened. Switch off and stir in vinegar, sesame oil and onion greens; taste for a balanced sharp and peppery finish and serve hot."],"tips":[],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('palak-shorba','{"id":"palak-shorba","name":"Palak Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"spinach","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"},{"name":"cream","qty":50,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash spinach in several changes of water and discard tough stems. Chop spinach, onion, ginger and garlic separately; grit left in the leaves will spoil the smooth soup.","Heat ghee and sizzle cumin. Soften onion for 5 minutes without deep browning, then stir in ginger and garlic for 1 minute. Add spinach and stir until wilted.","Add water, salt and pepper and simmer uncovered for 5–6 minutes until leaves are tender. Let the mixture cool until safe for your blender; blend in small batches without sealing hot steam inside.","Return to the pan and heat gently. Stir in cream without a hard boil; the shorba should flow freely and coat a spoon lightly. Taste and serve hot."],"tips":[],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tamatar-shorba','{"id":"tamatar-shorba","name":"Tamatar Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"tomato","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander seeds","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":5,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash and chop the tomatoes. Slice onion, ginger and garlic. Lightly crush cumin, coriander seeds and pepper so they release flavour without becoming a fine powder.","Heat ghee and stir the crushed spices for 30 seconds. Add onion and soften for 4 minutes, then add ginger and garlic for 1 minute.","Add tomatoes, water, sugar and salt. Simmer partly covered for 18–20 minutes until tomatoes collapse. Cool enough for safe blending and blend in small batches.","Pass through a sieve, pressing out the liquid and discarding tough skins and seeds. Reheat the strained shorba for 3 minutes, add coriander leaves and serve; it should be thin, not a thick purée."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pepper-rasam','{"id":"pepper-rasam","name":"Pepper Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"tamarind pulp","qty":25,"unit":"g","group":"Fruits","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"black pepper","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak tamarind in 150 ml warm measured water for 10 minutes. Squeeze and strain, discarding seeds and fibre. Crush pepper, cumin, coriander seeds and peeled garlic coarsely.","Simmer chopped tomato, tamarind extract, turmeric and salt with the remaining water for 8–10 minutes until the tomato is soft and the raw tamarind aroma fades.","Add the crushed spice mixture and simmer for 3–4 minutes. Stop when a light foam rises at the edges; prolonged hard boiling makes the pepper aroma dull.","Heat ghee separately and pop mustard seeds. Add dried chilli and curry leaves carefully, pour over the rasam and stir in coriander. Cover briefly before serving as a broth or with rice prepared separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mysore-rasam','{"id":"mysore-rasam","name":"Mysore Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"chana dal","qty":12,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh coconut","qty":30,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander seeds","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"tamarind pulp","qty":20,"unit":"g","group":"Fruits","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":18,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse toor dal and simmer with turmeric and 450 ml water for 30–40 minutes until completely soft, then mash. Soak tamarind in 150 ml warm water and strain out seeds and fibre.","Heat 5 g of the ghee and roast chana dal, coriander seeds, cumin, pepper and dried chilli over low heat until fragrant. Add coconut and stir until lightly golden, then cool and grind with 100 ml water.","Simmer chopped tomatoes, tamarind extract and salt with the remaining 500 ml water for 8 minutes. Add mashed dal and roasted paste and simmer gently for 5 minutes until aromatic.","Heat the remaining ghee, pop mustard and add curry leaves carefully. Pour into the rasam and finish with coriander; it should be a pourable broth, slightly richer than plain rasam."],"tips":[],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-rasam','{"id":"lemon-rasam","name":"Lemon Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse moong dal and simmer with turmeric and 500 ml water for 25 minutes until it breaks down easily. Mash lightly without draining the cooking liquid.","Add chopped tomato, crushed ginger, slit chilli, salt and the remaining 600 ml water. Simmer for 7–8 minutes until tomato softens and the broth smells fragrant.","Heat ghee in a small pan and pop mustard, then cumin. Add curry leaves carefully and pour this tempering into the simmering rasam; turn off the heat.","Wait 2 minutes, then stir in lemon juice and coriander. Do not boil after adding lemon; taste and serve the light broth hot, with rice separately if desired."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('thukpa','{"id":"thukpa","name":"Thukpa","baseServings":4,"batchSize":40,"ingredients":[{"name":"eggless wheat noodles","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cabbage","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":2200,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Cut carrot, cabbage and capsicum into thin strips. Chop onion, tomato, ginger and garlic finely. Keep vegetables ready before heating the pan so nothing burns while chopping.","Boil noodles in 1000 ml of the measured water according to the packet until just tender. Drain, discard this cooking water and divide noodles between four deep bowls.","Heat oil and soften onion for 5 minutes. Add ginger and garlic for 1 minute, then tomato, cumin powder and pepper; cook for 5 minutes until tomatoes turn pulpy.","Add the vegetables, remaining 1200 ml water, soy sauce and salt. Simmer for 10–12 minutes until carrot is tender but still holds its shape.","Turn off the heat, stir in lemon juice and coriander and ladle hot broth over noodles. Serve immediately so the noodles do not absorb all the soup."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-shorba','{"id":"dal-shorba","name":"Dal Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":150,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash the dal thoroughly. Chop onion, tomato, ginger and garlic finely. Heat ghee in a heavy saucepan and sizzle the cumin without allowing it to blacken.","Cook onion for 5 minutes until softened, then ginger and garlic for 1 minute. Add tomato and turmeric and stir for 4 minutes until the tomato breaks down.","Add dal and water, bring to a boil and simmer partly covered for 25 minutes until dal is very soft. Stir occasionally to prevent the lentils sticking to the bottom.","Cool sufficiently for safe blending and blend until smooth. Return to the pan, add salt and pepper and heat through; the shorba should be thinner than dal for rice.","Take off the heat and stir in lemon juice and coriander. Taste and serve hot in small bowls; reheat any refrigerated portion thoroughly before serving again."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cutting-chai','{"id":"cutting-chai","name":"Cutting Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":250,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse and lightly crush the ginger. Crack the cardamom pods so the seeds are exposed; keep the pods for brewing. Use a deep saucepan with room for the milk to rise.","Bring the water, ginger and cardamom to a boil. Simmer for 2 minutes, then add the tea leaves and boil gently for 2 minutes until the liquid is dark and aromatic.","Add the milk and sugar and stir until dissolved. Bring just to a rising boil, lower the heat immediately and simmer for 3–4 minutes, stirring so the milk does not catch.","When the chai is a rich brown and smells strongly of tea, strain through a fine sieve. Divide into four small heatproof glasses, about 100 ml each, and serve hot."],"tips":["Cutting means a small serving of strong chai; avoid prolonged boiling after the milk has reduced."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Makes four small cutting glasses. Contains caffeine; ginger suitability follows your household choices."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('irani-chai','{"id":"irani-chai","name":"Irani Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":700,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":48,"unit":"g","group":"Other","scale":"seasoning"},{"name":"unsweetened mawa","qty":60,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Bring the water to a boil in a small saucepan. Add the tea leaves, reduce to the lowest heat and cover with a normal loose-fitting lid; do not seal the pan airtight.","Simmer the tea gently for 20–25 minutes to make a dark concentrate. Check occasionally and lower the heat if it boils hard; it should retain roughly 300 ml of liquid.","Meanwhile simmer the milk in a separate heavy pan for 15–20 minutes, stirring and scraping the sides often, until reduced by about a quarter. Crumble in the mawa and whisk until no large lumps remain.","Stir the sugar into the thickened milk and heat for 2 minutes. Strain the tea concentrate, divide it between four cups and top with the sweet milk, stirring each cup before serving."],"tips":["Brew tea and milk separately: boiling mawa directly with tea leaves makes straining difficult."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Four rich cafe-style cups; contains milk and caffeine. The tea and milk pans cook at the same time."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('elaichi-chai','{"id":"elaichi-chai","name":"Elaichi Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Crack the cardamom pods and lightly crush the seeds. Put both pods and seeds in a deep saucepan with the measured water.","Bring to a boil and simmer for 2 minutes to release the cardamom aroma. Add the tea leaves and cook for another 2 minutes over medium-low heat.","Pour in the milk and add the sugar. Stir well, bring to a gentle rising boil and immediately lower the heat; simmer for 3 minutes until evenly caramel-coloured.","Switch off and strain into four warmed cups, discarding the tea leaves and pods. Serve promptly while the cardamom fragrance is fresh."],"tips":["Crush cardamom just before brewing; stored ground cardamom loses aroma quickly."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four regular cups of milk tea. Contains milk and caffeine."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sulaimani-chai','{"id":"sulaimani-chai","name":"Sulaimani Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"black tea leaves","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"seasoning"}],"steps":["Lightly crush the cardamom pods and place them in a saucepan with the water. Bring to a boil, then simmer for 2 minutes until lightly fragrant.","Switch off the heat, add the tea leaves and cover for 2 minutes. The brew should become clear amber rather than opaque and very dark.","Strain into a heatproof jug to stop extraction. Stir in the sugar until fully dissolved and allow the tea to stand for 1 minute off the heat.","Stir in the lemon juice only after straining; taste for a clean citrus finish. Divide between four glasses and serve hot without adding milk."],"tips":["Do not boil the tea leaves for a long time; this light tea is best with a short steep."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Four cups of Malabar-style lemon black tea. Contains caffeine."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('noon-chai','{"id":"noon-chai","name":"Noon Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"Kashmiri green tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":0.5,"unit":"g","group":"Bakery","scale":"seasoning"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"almonds","qty":16,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Put the tea leaves and cracked cardamom in a deep stainless-steel pan with 500 ml of the measured water. Reserve the remaining 300 ml water in the refrigerator until cold.","Bring to a boil and add exactly the measured baking soda. Simmer uncovered for 15–20 minutes, stirring occasionally, until the tea is concentrated and reddish-brown; do not let the pan dry out.","Add the reserved cold water. Keep the pan on low heat and repeatedly lift and pour the tea back with a ladle for 5 minutes, keeping the ladle close to the pan to avoid splashes.","Strain the concentrate into a clean pan, add the milk and salt, and simmer for 5–7 minutes. The colour should soften to dusty pink or pinkish tan; its shade depends on the tea leaves.","Slice the almonds finely. Divide the hot salted tea among four cups and scatter the almonds over each; serve without sugar for this savoury version."],"tips":["Use tea sold for noon chai. Do not add extra baking soda to force a brighter pink: it makes the tea unpleasantly alkaline."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Four cups of traditional salted tea, not a sweet pink dessert drink. Contains milk, almonds and caffeine."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gur-chai','{"id":"gur-chai","name":"Gur Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":48,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Grate the jaggery and check for grit. Crush the washed ginger and crack the cardamom pods; reserve the jaggery until the tea has finished cooking.","Boil the water with ginger and cardamom for 2 minutes. Add the tea leaves and simmer for another 2 minutes until the brew is dark.","Add the milk, bring carefully to a gentle boil and simmer for 3 minutes, stirring. Turn off the heat and strain the tea into a heatproof jug.","Wait 2 minutes so the tea stops bubbling, then stir in the grated jaggery until dissolved. Divide among four cups and serve immediately; do not boil again after adding jaggery."],"tips":["Jaggery varies in acidity and can split milk if boiled together; add it after cooking and use fresh milk."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Four cups sweetened with jaggery. Contains milk and caffeine; jaggery is still an added sweetener."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kesar-chai','{"id":"kesar-chai","name":"Kesar Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":550,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Warm 50 ml of the measured milk until just warm, not boiling. Lightly crumble the saffron into it and leave for 5 minutes while preparing the tea.","Crack the cardamom pods and boil with the water for 2 minutes. Add the tea leaves and simmer for 2 minutes until amber-brown and fragrant.","Add the remaining milk and sugar. Bring to a gentle boil, lower the heat and simmer for 3 minutes, stirring to dissolve the sugar and prevent scorching.","Strain the tea into a jug, then stir in all the saffron milk and threads. Rest for 1 minute and divide into four cups so the saffron aroma is retained."],"tips":["This is a saffron-forward brew; do not keep boiling after the saffron milk is added."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Four fragrant cups. Contains milk and caffeine; the saffron quantity is for the full four-serving batch."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tandoori-chai','{"id":"tandoori-chai","name":"Tandoori Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":550,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["For the heated-clay finish, use only a food-safe kulhad explicitly rated by its maker for direct flame and thermal shock. Follow its heating instructions and use long tongs; if no suitable vessel is available, skip heating the clay and serve the brewed chai in ordinary food-safe kulhads.","Crush the ginger and cardamom. Boil them with the water for 3 minutes in a deep pan, add the tea leaves and simmer for 2 minutes until dark and strongly aromatic.","Add milk and sugar, bring just to a rising boil and reduce the heat. Simmer for 4 minutes, stirring regularly, then strain the hot chai into a pouring jug.","Using tongs, set the correctly heated kulhad upright inside a large deep stainless-steel bowl on a heatproof surface, away from children. Stand back and pour a little hot chai into it slowly; expect vigorous frothing and let it subside before adding more.","Lift the kulhad with tongs and pour its tea into the collecting bowl. Repeat in small additions with the remaining chai, then serve in four separate cups. Discard the tea if the clay vessel chips or cracks; never serve from the heated vessel."],"tips":["Ordinary ceramic mugs and decorative terracotta are unsuitable for direct flame. The safe unheated-kulhad option will have less smoky flavour."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Four cups. Contains milk and caffeine. The heated-clay finish requires purpose-made cookware and careful adult handling."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemongrass-tea','{"id":"lemongrass-tea","name":"Lemongrass Tea","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":36,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh lemongrass","qty":12,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Rinse the lemongrass thoroughly. Snip the leaves into short lengths and gently bruise any tender stalk pieces with the back of a knife to release their lemony scent.","Bring the water and lemongrass to a boil in a deep saucepan. Simmer for 3 minutes until fragrant, then add the tea leaves and simmer for 2 minutes.","Pour in the milk and stir in the sugar. Bring just to the boil, reduce the heat and cook for 3 minutes, watching closely to prevent the milk from boiling over.","Strain through a fine sieve to remove every fibrous leaf and stalk. Divide into four cups and serve hot while the fresh citrus aroma is strongest."],"tips":["Use culinary lemongrass, not lawn grass; strain carefully because the leaves remain fibrous after brewing."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four cups of Maharashtrian gavti chaha. Contains milk and caffeine."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pudina-chai','{"id":"pudina-chai","name":"Pudina Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":36,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh mint leaves","qty":12,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Pick the mint leaves from any tough stems and rinse them in several changes of water. Drain well and lightly tear the leaves just before using.","Bring the water to a boil, add the tea leaves and simmer for 2 minutes. Add half the mint and cook for another 1 minute so its aroma enters the brew.","Add the milk and sugar and stir. Bring to a gentle boil, lower the heat and simmer for 3 minutes, stirring occasionally to prevent a skin forming at the bottom.","Switch off, add the remaining mint and cover for 1 minute. Strain immediately into four cups; the tea should smell fresh and minty rather than taste like overcooked greens."],"tips":["Adding some mint after switching off preserves its fragrance; do not leave the leaves sitting in the finished tea."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four cups of fresh mint milk tea. Contains milk and caffeine."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sabudana-thalipeeth','{"id":"sabudana-thalipeeth","name":"Sabudana Thalipeeth","baseServings":4,"batchSize":12,"ingredients":[{"name":"sabudana (tapioca pearls)","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"roasted peanuts","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rinse the sabudana in a sieve until the runoff is almost clear. Place in a bowl with the measured water, cover and soak for 4–6 hours, until a pearl crushes easily between your fingers without a hard centre. Drain any unabsorbed water thoroughly.","While the pearls soak, simmer the whole potatoes in a separate pan of water for 20–25 minutes, until a knife slides through. Drain, cool enough to handle, peel and mash smoothly; discard the cooking water.","Crush the roasted peanuts coarsely. Finely chop the chilli and coriander, then mix with the drained pearls, potato, cumin, lemon juice and rock salt. Squeeze a small portion: it should hold together without dripping moisture.","Divide into eight portions. With damp fingers, pat each portion on a small piece of baking parchment into a disc about 12 cm wide and 5 mm thick. Make a small hole in the centre so the middle cooks evenly.","Heat a heavy griddle over medium heat. Brush with a little of the measured oil, invert a disc onto it and peel away the parchment immediately. Spoon a little oil around the edge and into the centre.","Cook for 4–5 minutes until the underside has golden patches and releases easily. Turn carefully and cook the other side for 3–4 minutes; the pearls should look translucent and the centre should be set, with no raw crunch. Repeat with the remaining discs and oil."],"tips":["Very wet pearls make the dough sticky; drain well before mixing. Serve two small thalipeeth per person."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak sabudana for 4–6 hours; allow potatoes to cool for about 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('farali-pattice','{"id":"farali-pattice","name":"Farali Pattice","baseServings":4,"batchSize":12,"ingredients":[{"name":"potato","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"arrowroot flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh coconut","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"roasted peanuts","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cashew","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"ginger","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rock salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":80,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Simmer the whole potatoes in water for 25–30 minutes until tender through the centre. Drain completely, peel while warm and mash without adding water. Spread on a plate to cool for 20 minutes so steam escapes.","Grate the coconut and ginger, chop the cashews and raisins, and crush the roasted peanuts. Mix these with finely chopped chilli and coriander, lemon juice, sugar and half the rock salt to make a moist, loose filling.","Mix the cooled potato with 40 g of the arrowroot flour and the remaining salt. Divide into eight portions. Keep the remaining 20 g flour on a plate for dusting.","Flatten a potato portion in your palm, add one eighth of the filling, and bring the edges together. Seal completely, then flatten gently into a thick patty. Repeat, keeping the filling enclosed so it cannot spill into the oil.","Dust each patty lightly with the reserved arrowroot. Heat half the oil in a heavy frying pan over medium heat and add four patties without crowding. Shallow-fry for 4–5 minutes without moving them until a firm golden crust forms.","Turn with a broad spatula and cook for another 4–5 minutes until both faces are crisp and the centre is hot. Drain briefly on kitchen paper. Cook the second batch with the remaining oil and serve two patties per person."],"tips":["This is a shallow-fried potato-shell version with coconut and dry-fruit filling; the oil quantity is for the pan, not a measured absorbed amount."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Cool the mashed potatoes for 20 minutes before shaping.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('samak-pulao','{"id":"samak-pulao","name":"Samak Pulao","baseServings":4,"batchSize":50,"ingredients":[{"name":"barnyard millet","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"peanuts","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Pick over the barnyard millet, rinse in a fine sieve and soak in fresh water for 15 minutes. Drain completely; this soaking water is separate from the measured cooking water.","Peel the potato and cut into 1 cm cubes. Finely chop the chilli and coriander. Measure the cooking water before starting so the small grains do not sit in the hot pan too long.","Warm the ghee in a heavy saucepan. Fry the peanuts over medium-low heat for 3–4 minutes until lightly golden, then lift them out. Add cumin to the remaining ghee and let it sizzle.","Add potato and chilli and cook for 3 minutes, turning often. Stir in the drained millet for 30 seconds, then add the measured water and rock salt. Bring to a gentle boil.","Cover and cook over low heat for 12–15 minutes until the water is absorbed, the potato is tender and the millet is soft. If the grains remain firm, add a small splash of hot water and cook covered for 2 minutes more.","Remove from the heat and rest covered for 5 minutes. Fold in the fried peanuts, lemon juice and coriander gently with a fork; avoid vigorous stirring, which makes the millet pasty."],"tips":["Samak is barnyard millet, not ordinary rice. This potato-and-peanut version is not automatically suitable for a Jain household."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Soak millet for 15 minutes; rest the cooked pulao for 5 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kuttu-paratha','{"id":"kuttu-paratha","name":"Kuttu Paratha","baseServings":4,"batchSize":12,"ingredients":[{"name":"buckwheat flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":50,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"}],"steps":["Boil the whole potatoes in a separate pan of water for 20–25 minutes until tender. Drain well, peel and mash while warm. Let the mash cool for 15 minutes; it must not be wet or steaming when mixed with flour.","Reserve 20 g buckwheat flour for dusting. Mix the remaining flour with the potato, crushed cumin, finely chopped chilli and coriander, and rock salt.","Add the measured water a spoonful at a time, using only enough to bring the mixture into a soft dough. Knead gently just until smooth; buckwheat dough does not stretch like wheat dough.","Divide into eight portions. Dust parchment with some reserved flour and pat or gently roll each portion into a disc about 13 cm across and 3–4 mm thick. Repair cracks at the edges with damp fingers.","Transfer a disc to a medium-hot griddle and cook for about 1 minute until the top loses its wet appearance. Turn, spread a little ghee over the surface and cook for 2 minutes.","Turn again and cook with a little more ghee until both sides have brown patches and the centre is cooked, pressing the edges lightly with a spatula. Use the remaining ghee for the other parathas and serve hot."],"tips":["Potato binds the naturally gluten-free flour. Do not replace it silently when assessing household restrictions."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Cool the potato mash for 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kuttu-pakora','{"id":"kuttu-pakora","name":"Kuttu Pakora","baseServings":4,"batchSize":12,"ingredients":[{"name":"buckwheat flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":210,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Peel the potatoes and slice into even 2 mm rounds; thicker slices can stay raw after the batter browns. Pat the slices dry. Finely chop the chilli and coriander.","Mix buckwheat flour, cumin, chilli, coriander and rock salt. Whisk in the water gradually to make a smooth batter that coats a spoon thickly but still falls in a ribbon.","Pour the oil into a deep, heavy pan with plenty of headroom and heat to about 170°C. A small drop of batter should rise steadily with bubbles, not sink or darken immediately.","Dip a potato slice into the batter, let the excess drip briefly and lower it carefully into the oil. Add a few more without crowding or letting the slices stick together.","Fry for 4–6 minutes, turning halfway, until the coating is crisp and the bubbles have slowed. Cut open the first pakora: the potato must be completely tender, with no firm raw centre. Reduce the heat slightly if the outside colours too quickly.","Lift out with a slotted spoon and drain. Bring the oil back to temperature before frying the next batch. Keep water away from the hot oil and serve the pakoras freshly cooked."],"tips":["The 600 ml oil is the frying medium, not the amount absorbed. Never fill the pan more than halfway with oil."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('singhare-ki-puri','{"id":"singhare-ki-puri","name":"Singhare ki Puri","baseServings":4,"batchSize":12,"ingredients":[{"name":"water chestnut flour","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":40,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":610,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Boil the whole potatoes in a separate pan of water for about 20–25 minutes, until a knife reaches the centre easily. Drain, peel and mash smoothly. Cool for 15 minutes so excess steam escapes.","Reserve 20 g of the flour for dusting. Mix the remaining water chestnut flour with potato, crushed cumin, rock salt and 10 ml oil. Add the measured water gradually, stopping as soon as a smooth, firm dough forms.","Divide the dough into twelve equal portions. Dust lightly with the reserved flour and roll gently between parchment into discs about 9 cm wide and 3 mm thick. Keep the thickness even and repair cracked edges.","Heat the remaining 600 ml oil in a deep pan to about 175°C, keeping the pan less than half full. Test a tiny piece of dough: it should rise promptly without becoming dark at once.","Slide in one puri carefully. Gently nudge the surface with a slotted spoon as it rises; turn after about 30–45 seconds. Cook the second side until both faces are lightly golden and no wet dough remains at the rim.","Drain on kitchen paper and repeat, letting the oil regain heat between puris. Open the first puri to check the middle is cooked; lower the heat slightly and cook longer if it browns before cooking through."],"tips":["Makes twelve small puris, three per person as an accompaniment. Potato binds this traditional dough; check it against your household restrictions."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Cool mashed potatoes for 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('singhare-ke-pakode','{"id":"singhare-ke-pakode","name":"Singhare ke Pakode","baseServings":4,"batchSize":12,"ingredients":[{"name":"water chestnut flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":190,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Peel the potatoes and cut into matchsticks no thicker than 3 mm so they cook at the same rate as the batter. Pat dry, and finely chop the chilli and coriander.","Mix water chestnut flour, cumin, rock salt, chilli and coriander. Add the measured water gradually to make a thick batter, then fold in the potato. The mixture should hold a small mound on a spoon.","Heat the oil in a deep heavy pan to about 170°C with the pan less than half full. Test a little batter: it should rise with steady bubbles, without immediately turning dark.","Lower small spoonfuls into the oil, keeping each mound about 3 cm across. Leave room between them and do not flatten them against the bottom of the pan.","Fry for 5–6 minutes, turning several times, until crisp and golden. Split the first pakora to check that the potato is tender and the centre has no wet flour; make later portions smaller if the centre cooks too slowly.","Remove with a slotted spoon and drain well. Let the oil return to temperature between batches. Serve promptly, since steam softens the crust as the pakode stand."],"tips":["This potato version contains roots. The measured oil is the quantity needed in the frying pan, not the absorbed amount."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sweet-potato-chaat','{"id":"sweet-potato-chaat","name":"Sweet Potato Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet potato","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Scrub the sweet potatoes and rinse off all soil. Place them whole in a heavy covered pan over low heat, without oil, using similarly sized roots so they roast evenly.","Cook for 35–45 minutes, turning every 6–8 minutes with tongs. The skins may blister; lower the heat if they scorch quickly. Test the thickest part with a skewer: it should pass through without resistance.","While the sweet potatoes cook, toast the cumin in a small dry pan for about 1 minute until fragrant. Cool briefly and crush with the black pepper. Finely chop the coriander.","Rest the cooked sweet potatoes off the heat for 5 minutes. Peel carefully while warm and remove any charred skin; cut the soft flesh into bite-sized chunks.","Place the chunks in a bowl and sprinkle with the crushed spices and rock salt. Add lemon juice and turn gently so the pieces are seasoned without being mashed.","Finish with coriander and serve warm. Taste a piece before serving; the lemon should balance the natural sweetness without pooling at the bottom."],"tips":["This fasting-style version uses rock salt and freshly toasted cumin rather than a mixed chaat masala."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Rest roasted sweet potatoes for 5 minutes before peeling.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vrat-wale-aloo','{"id":"vrat-wale-aloo","name":"Vrat Wale Aloo","baseServings":4,"batchSize":50,"ingredients":[{"name":"potato","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash the potatoes and simmer whole in a pan of water for 20–25 minutes until just tender. Test with a knife; the centres should be cooked but the potatoes should not fall apart. Drain fully.","Let the potatoes cool for 10 minutes, then peel and cut into 2 cm chunks. Chop the chilli and coriander, and crush the black pepper.","Heat ghee in a broad heavy pan over medium heat. Add cumin and let it sizzle for 20–30 seconds until aromatic, then add the chilli and stir briefly.","Add the potatoes in a fairly even layer. Cook for 4–5 minutes without frequent stirring so the undersides develop golden patches, then turn carefully.","Sprinkle with rock salt and black pepper. Cook for another 3–4 minutes, turning once or twice, until the edges are lightly crisp and the centres are hot.","Switch off the heat and fold in lemon juice and coriander. Serve as a potato accompaniment with your chosen fasting bread; it is not a complete meal by itself."],"tips":["Keep the potato pieces intact rather than mashing them into the cumin tempering."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Cool boiled potatoes for 10 minutes before peeling.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('shengdana-amti','{"id":"shengdana-amti","name":"Shengdana Amti","baseServings":4,"batchSize":50,"ingredients":[{"name":"roasted peanuts","qty":160,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"fresh coconut","qty":40,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"jaggery","qty":12,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rub the roasted peanuts to loosen the skins and discard any loose skins. Grind the nuts with grated fresh coconut, chopped chilli and 200 ml of the measured water to a smooth paste.","Heat ghee in a heavy saucepan over medium-low heat. Add cumin and let it sizzle until fragrant, keeping it pale brown rather than black.","Lower the heat and carefully stir in the peanut paste. Cook for 2 minutes, stirring the bottom constantly because nut paste catches easily.","Add the remaining 600 ml water gradually, whisking out lumps. Add jaggery and rock salt and bring to a gentle simmer rather than a rapid boil.","Simmer uncovered for 8–10 minutes, stirring often, until the raw paste aroma has gone and the curry lightly coats a spoon. Add a little hot water if it becomes too thick; amti should be pourable.","Take off the heat and stir in the lemon juice. Taste for a gentle sweet-sour balance and serve hot alongside your chosen bhagar or fasting bread, prepared separately."],"tips":["This peanut-based fasting amti is an accompaniment; peanuts must be checked against the household’s own Jain and allergy choices."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules."}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
